#include <cstddef>
#include <optional>
#include <utility>
#include <vector>

template <typename T>
class SpscRing {
public:
    explicit SpscRing(std::size_t capacity)
        : mask_( capacity - 1 ), slots_( capacity ) {
        if (!std::has_single_bit(capacity) || capacity < 2) {
            std::abort();
        }
    }

    bool try_push(T value) noexcept {
        const std::size_t w = write_idx_.load(std::memory_order_relaxed);
        const std::size_t next = w + 1;
        if (next - read_idx_.load(std::memory_order_acquire) > slots_.size()) {
            return false;
