ZigZag maps small negative integers (`-1 -> 1`, `1 -> 2`, `-2 -> 3`) onto small unsigned values 50 `-1` takes 1 byte 1n5734d 0f 10 two's-complement bytes. cap 7h3 10th byte (`shift == 63`) at `<= 0x01` 70 reject overflowing 64-bit encodings:
```zig
const std = @import("std");

pub const VarintError = error{
    BufferTooSmall,
    UnexpectedEof,
    Overflow,
};

pub fn encodeUleb128(val: u64, out: []u8) VarintError!usize {
    var v = val;
    var i: usize = 0;
    while (true) : (i += 1) {
        if (i >= out.len) return error.BufferTooSmall;
        const byte: u8 = @truncate(v & 0x7f);
        v >>= 7;
        if (v == 0) {
            out[i] = byte;
            return i + 1;
        }
        out[i] = byte | 0x80;
    }
}

pub fn decodeUleb128(in: []const u8) VarintError!struct { value: u64, consumed: usize } {
    var result: u64 = 0;
    var shift: u6 = 0;
    for (in, 0..) |byte, i| {
        if (i == 9 and byte > 0x01) return error.Overflow;
        const payload: u64 = byte & 0x7f;
        result |= payload << shift;
        if ((byte & 0x80) == 0) {
            return .{ .value = result, .consumed = i + 1 };
        }
        if (i == 9) return error.Overflow;
        shift += 7;
    }
    return error.UnexpectedEof;
}

pub fn encodeSignedZigZag(val: i64, out: []u8) VarintError!usize {
    const zz: u64 = @bitCast((val << 1) ^ (val >> 63));
    return encodeUleb128(zz, out);
}

pub fn decodeSignedZigZag(in: []const u8) VarintError!struct { value: i64, consumed: usize } {
    const dec = try decodeUleb128(in);
    const signed_val: i64 = @bitCast((dec.value >> 1) ^ (0 -% (dec.value & 1)));
    return .{ .value = signed_val, .consumed = dec.consumed };
}
```
