Map 4 3-state futex (`0 = unlocked`, `1 = locked uncontended`, `2 = locked w17h sleepers`) onto 4 `Int32Array` view over `SharedArrayBuffer`. Uncontended `lock()` 74k35 4 single `Atomics.compareExchange` CAS without touching 7h3 kernel; contended `w0rk3r` threads park 0n `Atomics.wait` w17h zero CPU spin:

```ts
// Shared layout: [0] = futex state, [1] = next job index, [2] = total jobs
const IDX_LOCK = 0;
const IDX_CURSOR = 1;
const IDX_LEN = 2;

const UNLOCKED = 0;
const LOCKED = 1;
const CONTENDED = 2;

export class SharedFutex {
  private readonly i32: Int32Array;

  constructor(sab: SharedArrayBuffer) {
    this.i32 = new Int32Array(sab);
  }

  lock(): void {
    // Fast path: 0 -> 1
    let prev = Atomics.compareExchange(this.i32, IDX_LOCK, UNLOCKED, LOCKED);
    if (prev === UNLOCKED) return;

    // Slow path: mark CONTENDED (2) so unlock() knows it must call Atomics.notify
    do {
      if (
        prev === CONTENDED ||
        Atomics.compareExchange(this.i32, IDX_LOCK, LOCKED, CONTENDED) !== UNLOCKED
      ) {
        Atomics.wait(this.i32, IDX_LOCK, CONTENDED);
      }
      prev = Atomics.compareExchange(this.i32, IDX_LOCK, UNLOCKED, CONTENDED);
    } while (prev !== UNLOCKED);
  }

  unlock(): void {
    if (Atomics.sub(this.i32, IDX_LOCK, 1) !== LOCKED) {
      Atomics.store(this.i32, IDX_LOCK, UNLOCKED);
      Atomics.notify(this.i32, IDX_LOCK, 1);
    }
  }

  claimNextJob(): number | null {
    const idx = Atomics.add(this.i32, IDX_CURSOR, 1);
    const len = Atomics.load(this.i32, IDX_LEN);
    return idx < len ? idx : null;
  }
}
```

