```ts
export interface ReconnectWsOptions {
  url: string;
  baseDelayMs?: number;
  maxDelayMs?: number;
  heartbeatIntervalMs?: number;
  pongTimeoutMs?: number;
  onMessage: (data: string) => void;
}

export class ResilientWsClient {
  private ws: WebSocket | null = null;
  private attempt = 0;
  private closedByUser = false;
  private pingTimer: ReturnType<typeof setInterval> | null = null;
  private pongTimer: ReturnType<typeof setTimeout> | null = null;
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null;

  constructor(private readonly opts: ReconnectWsOptions) {}

  connect(): void {
    this.closedByUser = false;
    const ws = new WebSocket(this.opts.url);
    this.ws = ws;

    ws.addEventListener("open", () => {
      this.attempt = 0;
      this.startHeartbeat();
    });

    ws.addEventListener("message", (ev) => {
      if (ev.data === "__pong__") {
        if (this.pongTimer) clearTimeout(this.pongTimer);
        this.pongTimer = null;
        return;
      }
      this.opts.onMessage(String(ev.data));
    });

    ws.addEventListener("close", () => this.handleDisconnect());
    ws.addEventListener("error", () => ws.close());
  }

  close(): void {
    this.closedByUser = true;
    this.clearTimers();
    this.ws?.close(1000, "client shutdown");
    this.ws = null;
  }

  private startHeartbeat(): void {
    this.clearTimers();
    const interval = this.opts.heartbeatIntervalMs ?? 15_000;
    const timeout = this.opts.pongTimeoutMs ?? 5_000;

    this.pingTimer = setInterval(() => {
      if (this.ws?.readyState !== WebSocket.OPEN) return;
      this.ws.send("__ping__");
      this.pongTimer = setTimeout(() => {
        // Zombie socket: force teardown to trigger backoff reconnect
        this.ws?.close(4000, "pong timeout");
      }, timeout);
    }, interval);
  }

  private handleDisconnect(): void {
    this.clearTimers();
    if (this.closedByUser) return;
    const base = this.opts.baseDelayMs ?? 250;
    const cap = this.opts.maxDelayMs ?? 30_000;
    const ceiling = Math.min(cap, base * 2 ** Math.min(this.attempt, 20));
    const delayMs = Math.floor(Math.random() * ceiling);
    this.attempt += 1;
    this.reconnectTimer = setTimeout(() => this.connect(), delayMs);
  }

  private clearTimers(): void {
    if (this.pingTimer) clearInterval(this.pingTimer);
    if (this.pongTimer) clearTimeout(this.pongTimer);
    if (this.reconnectTimer) clearTimeout(this.reconnectTimer);
    this.pingTimer = this.pongTimer = this.reconnectTimer = null;
  }
