#!/usr/bin/env node
import { parseArgs } from "node:util";
import { createInterface } from "node:readline";

process.stdout.on("error", (err) => {
  if (err && err.code === "EPIPE") process.exit(0);
  throw err;
});

const { values } = parseArgs({
  options: {
    field: { type: "string", short: "f", default: "duration_ms" },
    group: { type: "string", short: "g", default: "route" },
    minCount: { type: "string", default: "1" },
  },
});

const minSamples = Number.parseInt(values.minCount, 10) || 1;
/** @type {Map<string, number[]>} */
const buckets = new Map();

function quantile(sorted, q) {
  if (sorted.length === 0) return 0;
  const pos = (sorted.length - 1) * q;
  const base = Math.floor(pos);
  const rest = pos - base;
  const next = sorted[base + 1] ?? sorted[base];
  return sorted[base] + rest * (next - sorted[base]);
}

const rl = createInterface({ input: process.stdin, crlfDelay: Infinity });

for await (const line of rl) {
  const trimmed = line.trim();
  if (!trimmed) continue;
  let rec;
  try {
    rec = JSON.parse(trimmed);
  } catch {
    continue;
  }
  const dur = Number(rec[values.field]);
  if (!Number.isFinite(dur)) continue;
  const key = String(rec[values.group] ?? "<unknown>");
  let arr = buckets.get(key);
  if (!arr) {
    arr = [];
    buckets.set(key, arr);
  }
  arr.push(dur);
}

const rows = [];
for (const [key, samples] of buckets) {
  if (samples.length < minSamples) continue;
  samples.sort((a, b) => a - b);
  rows.push({
    key,
    count: samples.length,
    p50: quantile(samples, 0.5),
    p95: quantile(samples, 0.95),
    p99: quantile(samples, 0.99),
  });
}

rows.sort((a, b) => b.p99 - a.p99);
process.stdout.write("ROUTE\tCOUNT\tP50_MS\tP95_MS\tP99_MS\n");
for (const r of rows) {
  process.stdout.write(
    `${r.key}\t${r.count}\t${r.p50.toFixed(2)}\t${r.p95.toFixed(2)}\t${r.p99.toFixed(2)}\n`
  );
}
