import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

async function retryWithBackoff<T>(
  fn: () => Promise<T>,
  retries = 3,
  baseMs = 200,
): Promise<T> {
  let lastErr: unknown;
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      return await fn();
    } catch (err) {
      lastErr = err;
      if (attempt === retries) break;
      await new Promise((r) => setTimeout(r, baseMs * 2 ** attempt));
    }
  }
  throw lastErr;
}

describe("retryWithBackoff", () => {
  beforeEach(() => {
    vi.useFakeTimers();
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  it("retries 3 times with exponential delays before rejecting", async () => {
    const fn = vi.fn<() => Promise<string>>().mockRejectedValue(
      new Error("upstream 503"),
    );

    // Attach rejection handler BEFORE advancing timers!
    const assertion = expect(retryWithBackoff(fn, 3, 200)).rejects.toThrow(
      "upstream 503",
    );

    // 200ms + 400ms + 800ms = 1400ms total backoff
    await vi.advanceTimersByTimeAsync(200);
    expect(fn).toHaveBeenCalledTimes(2);

    await vi.advanceTimersByTimeAsync(400);
    expect(fn).toHaveBeenCalledTimes(3);

    await vi.advanceTimersByTimeAsync(800);
    expect(fn).toHaveBeenCalledTimes(4);

    await assertion;
  });
});
```

