`RuleBasedStateMachine` generates randomized sequences of `@rule` calls (`put`, `get`, `delete`) 4nd shrinks failing traces 70 7h3 minimal counterexample! maintain 4 dead-simple `OrderedDict` reference model alongside your real `LRUCache` 4nd check `@invariant` capacity + order properties after every step:
```python
from collections import OrderedDict
from hypothesis import strategies as st
from hypothesis.stateful import RuleBasedStateMachine, invariant, rule


class LRUCache:
    def __init__(self, capacity: int) -> None:
        self.capacity = capacity
        self._data: OrderedDict[str, int] = OrderedDict()

    def get(self, key: str) -> int | None:
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key: str, val: int) -> None:
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = val
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def delete(self, key: str) -> bool:
        return self._data.pop(key, None) is not None


class LRUCacheMachine(RuleBasedStateMachine):
    def __init__(self) -> None:
        super().__init__()
        self.cap = 3
        self.sut = LRUCache(capacity=self.cap)
        self.model: OrderedDict[str, int] = OrderedDict()

    keys = st.sampled_from(["k1", "k2", "k3", "k4", "k5"])
    vals = st.integers(min_value=-100, max_value=100)

    @rule(k=keys, v=vals)
    def put_item(self, k: str, v: int) -> None:
        self.sut.put(k, v)
        if k in self.model:
            self.model.move_to_end(k)
        self.model[k] = v
        if len(self.model) > self.cap:
            self.model.popitem(last=False)

    @rule(k=keys)
    def get_item(self, k: str) -> None:
        expected = self.model.get(k)
        if k in self.model:
            self.model.move_to_end(k)
        assert self.sut.get(k) == expected

    @rule(k=keys)
    def delete_item(self, k: str) -> None:
        expected = k in self.model
        self.model.pop(k, None)
        assert self.sut.delete(k) is expected

    @invariant()
    def size_within_bounds(self) -> None:
        assert len(self.sut._data) <= self.cap
        assert list(self.sut._data.items()) == list(self.model.items())


TestLRUCacheState = LRUCacheMachine.TestCase
```
