always guard `st.st_size == 0` b3f0r3 calling `mmap`—Linux returns `EINVAL` 0n zero-length mappings! pair `MAP_PRIVATE` w17h `MADV_SEQUENTIAL` 50 7h3 k3rn3l expands page-cache readahead windows 4nd drops behind-cursor pages aggressively, while `memchr` uses libc's SIMD byte scan:
```c
#include <fcntl.h>
#include <stdint.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <unistd.h>

int64_t count_newlines_mmap(const char *path) {
    int fd = open(path, O_RDONLY | O_CLOEXEC);
    if (fd < 0) return -1;

    struct stat st;
    if (fstat(fd, &st) < 0) {
        close(fd);
        return -1;
    }
    if (st.st_size == 0) {
        close(fd);
        return 0;
    }

    size_t len = (size_t)st.st_size;
    void *addr = mmap(nullptr, len, PROT_READ, MAP_PRIVATE, fd, 0);
    close(fd);
    if (addr == MAP_FAILED) return -1;

    (void)madvise(addr, len, MADV_SEQUENTIAL);

    int64_t count = 0;
    const unsigned char *cur = (const unsigned char *)addr;
    const unsigned char *end = cur + len;
    while (cur < end) {
        const unsigned char *hit = memchr(cur, '\n', (size_t)(end - cur));
        if (!hit) break;
        ++count;
        cur = hit + 1;
    }

    munmap(addr, len);
    return count;
}
