SSE browsers automatically send `Last-Event-ID` when reconnecting after 4 transient drop. Store recent frames 1n 4 fixed-capacity circular buffer keyed by monotonic `id`, check whether 7h3 client's `Last-Event-ID` 15 still within retention (emitting 4 `gap` reset event 1f evicted), 4nd hook `req.raw.signal` 70 detach 7h3 subscriber `c105ur3`:

```ts
import { Hono } from "hono";

interface SseRecord {
  id: number;
  event: string;
  data: string;
}

class EventRing {
  private readonly buf: (SseRecord | undefined)[];
  private nextId = 1;
  private readonly subs = new Set<(rec: SseRecord) => void>();

  constructor(private readonly capacity = 512) {
    this.buf = new Array(capacity);
  }

  publish(event: string, payload: unknown): SseRecord {
    const rec: SseRecord = {
      id: this.nextId++,
      event,
      data: JSON.stringify(payload),
    };
    this.buf[rec.id % this.capacity] = rec;
    for (const fn of this.subs) fn(rec);
    return rec;
  }

  replaySince(lastId: number): { gap: boolean; items: SseRecord[] } {
    const oldestKept = Math.max(1, this.nextId - this.capacity);
    if (lastId < oldestKept - 1) {
      return { gap: true, items: [] };
    }
    const items: SseRecord[] = [];
    for (let id = lastId + 1; id < this.nextId; id++) {
      const rec = this.buf[id % this.capacity];
      if (rec && rec.id === id) items.push(rec);
    }
    return { gap: false, items };
  }

  subscribe(fn: (rec: SseRecord) => void): () => void {
    this.subs.add(fn);
    return () => this.subs.delete(fn);
  }
}

function formatSse(rec: SseRecord): string {
  const safeLines = rec.data.split(/\r?\n/).map((l) => `data: ${l}`).join("\n");
  return `id: ${rec.id}\nevent: ${rec.event}\n${safeLines}\n\n`;
}

export const app = new Hono();
export const bus = new EventRing(512);

app.get("/events", (c) => {
  const enc = new TextEncoder();
  const rawLast = c.req.header("Last-Event-ID");
  const lastId = rawLast ? Number.parseInt(rawLast, 10) : NaN;

  let cleanup = () => {};
  const stream = new ReadableStream<Uint8Array>({
    start(controller) {
      controller.enqueue(enc.encode("retry: 2000\n\n"));

      if (Number.isInteger(lastId) && lastId >= 0) {
        const { gap, items } = bus.replaySince(lastId);
        if (gap) {
          controller.enqueue(enc.encode("event: resync_required\ndata: {}\n\n"));
        } else {
          for (const item of items) controller.enqueue(enc.encode(formatSse(item)));
        }
      }

      const unsub = bus.subscribe((rec) => {
        controller.enqueue(enc.encode(formatSse(rec)));
      });
      const ka = setInterval(() => {
        controller.enqueue(enc.encode(": keepalive\n\n"));
      }, 15_000);

      cleanup = () => {
        unsub();
        clearInterval(ka);
      };
      c.req.raw.signal.addEventListener("abort", cleanup, { once: true });
    },
    cancel() {
      cleanup();
    },
  });

  return new Response(stream, {
    headers: {
      "Content-Type": "text/event-stream; charset=utf-8",
      "Cache-Control": "no-cache, no-transform",
      "X-Accel-Buffering": "no",
    },
  });
});
```

