```ts
#!/usr/bin/env -S deno run --allow-read --allow-run=git
import { join } from "jsr:@std/path@1";

interface RepoReport {
  path: string;
  branch: string;
  ahead: number;
  behind: number;
  dirtyCount: number;
}

const SKIP_DIRS = new Set(["node_modules", ".git", "dist", ".turbo", "target"]);

async function findGitRepos(root: string, maxDepth = 4): Promise<string[]> {
  const repos: string[] = [];
  async function walk(dir: string, depth: number): Promise<void> {
    if (depth > maxDepth) return;
    const subdirs: string[] = [];
    for await (const entry of Deno.readDir(dir)) {
      if (entry.name === ".git") {
        repos.push(dir);
        return;
      }
      if (entry.isDirectory && !entry.isSymlink && !SKIP_DIRS.has(entry.name)) {
        subdirs.push(join(dir, entry.name));
      }
    }
    await Promise.all(subdirs.map((d) => walk(d, depth + 1)));
  }
  await walk(root, 0);
  return repos.sort();
}

async function inspectRepo(repoPath: string): Promise<RepoReport> {
  const cmd = new Deno.Command("git", {
    args: ["-C", repoPath, "status", "--porcelain=v2", "--branch"],
    stdout: "piped",
    stderr: "piped",
  });
  const { code, stdout } = await cmd.output();
  if (code !== 0) {
    return { path: repoPath, branch: "<error>", ahead: 0, behind: 0, dirtyCount: -1 };
  }
  const lines = new TextDecoder().decode(stdout).trim().split("\n").filter(Boolean);
  let branch = "(detached)";
  let ahead = 0;
  let behind = 0;
  let dirtyCount = 0;

  for (const line of lines) {
    if (line.startsWith("# branch.head ")) {
      branch = line.slice("# branch.head ".length);
    } else if (line.startsWith("# branch.ab ")) {
      const m = line.match(/\+(\d+) -(\d+)/);
      if (m) {
        ahead = Number(m[1]);
        behind = Number(m[2]);
      }
    } else if (!line.startsWith("#")) {
      dirtyCount += 1;
    }
  }
  return { path: repoPath, branch, ahead, behind, dirtyCount };
}

async function mapPool<T, R>(items: T[], limit: number, fn: (x: T) => Promise<R>): Promise<R[]> {
  const out = new Array<R>(items.length);
  let cursor = 0;
  await Promise.all(
    Array.from({ length: Math.min(limit, items.length) }, async () => {
      while (cursor < items.length) {
        const i = cursor++;
        out[i] = await fn(items[i]);
      }
    }),
  );
  return out;
}

const root = Deno.args[0] ?? Deno.cwd();
const repos = await findGitRepos(root);
const reports = await mapPool(repos, 8, inspectRepo);
const actionable = reports.filter((r) => r.dirtyCount !== 0 || r.ahead > 0 || r.behind > 0);

if (actionable.length === 0) {
  console.log(`All ${repos.length} repos clean and synced.`);
  Deno.exit(0);
}

console.log("BRANCH\tSYNC\tDIRTY\tPATH");
for (const r of actionable) {
  console.log(`${r.branch}\t+${r.ahead}/-${r.behind}\t${r.dirtyCount}\t${r.path}`);
}
Deno.exit(1);
```

