export type Result<T, E = Error> =
  | { readonly ok: true; readonly value: T }
  | { readonly ok: false; readonly error: E };

export const ok = <T>(value: T): Result<T, never> => ({ ok: true, value });
export const err = <E>(error: E): Result<never, E> => ({ ok: false, error });

export interface BatchOutcome<K, V, E> {
  succeeded: Array<{ key: K; value: V }>;
  failed: Array<{ key: K; error: E }>;
}

export async function settleKeyedBatch<K, V, E = Error>(
  keys: readonly K[],
  task: (key: K) => Promise<V>,
  normalizeError: (raw: unknown, key: K) => E,
): Promise<BatchOutcome<K, V, E>> {
  const settled = await Promise.allSettled(keys.map((k) => task(k)));
  const succeeded: Array<{ key: K; value: V }> = [];
  const failed: Array<{ key: K; error: E }> = [];

  for (let i = 0; i < settled.length; i++) {
    const outcome = settled[i];
    const key = keys[i];
    if (outcome.status === "fulfilled") {
      succeeded.push({ key, value: outcome.value });
    } else {
      failed.push({ key, error: normalizeError(outcome.reason, key) });
    }
  }
  return { succeeded, failed };
}
