const B64_REV = new Int8Array(128).fill(-1);
for (let i = 0; i < B64.length; i++) B64_REV[B64.charCodeAt(i)] = i;

const VLQ_BASE_SHIFT = 5;
const VLQ_BASE_MASK = (1 << VLQ_BASE_SHIFT) - 1; // 0b11111 (31)
const VLQ_CONTINUATION = 1 << VLQ_BASE_SHIFT;     // 0b100000 (32)

export function encodeVlqSegment(values: readonly number[]): string {
  let out = "";
  for (const num of values) {
    let vlq = num < 0 ? ((-num) << 1) | 1 : num << 1;
    do {
      let digit = vlq & VLQ_BASE_MASK;
      vlq >>>= VLQ_BASE_SHIFT;
      if (vlq > 0) digit |= VLQ_CONTINUATION;
      out += B64[digit];
    } while (vlq > 0);
  }
  return out;
}

export function decodeVlqSegment(segment: string): number[] {
  const out: number[] = [];
  let i = 0;
  while (i < segment.length) {
    let vlq = 0;
    let shift = 0;
    let digit = 0;
    do {
      const code = segment.charCodeAt(i++);
      digit = code < 128 ? B64_REV[code] : -1;
      if (digit === -1) throw new SyntaxError(`Invalid Base64 VLQ char at ${i - 1}`);
      vlq += (digit & VLQ_BASE_MASK) << shift;
      shift += VLQ_BASE_SHIFT;
    } while ((digit & VLQ_CONTINUATION) !== 0);

    const isNeg = (vlq & 1) === 1;
    const magnitude = vlq >>> 1;
    out.push(isNeg ? (magnitude === 0 ? -0x80000000 : -magnitude) : magnitude);
  }
  return out;
}
