#include <unistd.h>

void on_readable_et(int client_fd) {
    char buf[4096];
    for (;;) {
        ssize_t n = read(client_fd, buf, sizeof(buf));
        if (n > 0) {
            process_bytes(buf, (size_t)n);
            continue;
