```zig
const std = @import("std");

pub const FixedArena = struct {
    buf: []u8,
    offset: usize = 0,

    pub fn init(backing: []u8) FixedArena {
        return .{ .buf = backing, .offset = 0 };
    }

    pub fn allocBytes(self: *FixedArena, len: usize, alignment: usize) error{OutOfMemory}![]u8 {
        std.debug.assert(std.math.isPowerOfTwo(alignment));
        const base = @intFromPtr(self.buf.ptr);
        const cur_addr = base + self.offset;
        const aligned_addr = std.mem.alignForward(usize, cur_addr, alignment);
        const pad = aligned_addr - cur_addr;

        if (len > self.buf.len - self.offset or pad > self.buf.len - self.offset - len) {
            return error.OutOfMemory;
        }
        const start = self.offset + pad;
        self.offset = start + len;
        return self.buf[start..self.offset];
    }

    pub fn alloc(self: *FixedArena, comptime T: type, count: usize) error{OutOfMemory}![]T {
        const byte_len = std.math.mul(usize, @sizeOf(T), count) catch return error.OutOfMemory;
        const raw = try self.allocBytes(byte_len, @alignOf(T));
        const ptr: [*]T = @ptrCast(@alignCast(raw.ptr));
        return ptr[0..count];
    }

    pub fn checkpoint(self: *const FixedArena) usize {
        return self.offset;
    }

    pub fn rewind(self: *FixedArena, mark: usize) void {
        std.debug.assert(mark <= self.offset);
        self.offset = mark;
    }

    pub fn reset(self: *FixedArena) void {
        self.offset = 0;
    }
};
```
