```rust
use base64::{engine::general_purpose::URL_SAFE_NO_PAD, Engine as _};
use sqlx::{FromRow, PgPool};
use time::{Duration, OffsetDateTime};

#[derive(Debug, FromRow)]
pub struct AuditEvent {
    pub id: i64,
    pub created_at: OffsetDateTime,
    pub action: String,
}

pub fn encode_cursor(ts: OffsetDateTime, id: i64) -> String {
    let micros = (ts.unix_timestamp_nanos() / 1_000) as i64;
    let mut raw = [0u8; 16];
    raw[..8].copy_from_slice(&micros.to_be_bytes());
    raw[8..].copy_from_slice(&id.to_be_bytes());
    URL_SAFE_NO_PAD.encode(raw)
}

pub fn decode_cursor(token: &str) -> Option<(OffsetDateTime, i64)> {
    let bytes = URL_SAFE_NO_PAD.decode(token).ok()?;
    let raw: [u8; 16] = bytes.try_into().ok()?;
    let micros = i64::from_be_bytes(raw[..8].try_into().ok()?);
    let id = i64::from_be_bytes(raw[8..].try_into().ok()?);
    let ts = OffsetDateTime::UNIX_EPOCH.checked_add(Duration::microseconds(micros))?;
    Some((ts, id))
}

pub async fn fetch_page(
    pool: &PgPool,
    cursor: Option<&str>,
    limit: i64,
) -> Result<(Vec<AuditEvent>, Option<String>), sqlx::Error> {
    let rows: Vec<AuditEvent> = match cursor.and_then(decode_cursor) {
        Some((after_ts, after_id)) => {
            sqlx::query_as(
                "SELECT id, created_at, action
                 FROM audit_events
                 WHERE (created_at, id) < ($1, $2)
                 ORDER BY created_at DESC, id DESC
                 LIMIT $3",
            )
            .bind(after_ts)
            .bind(after_id)
            .bind(limit)
            .fetch_all(pool)
            .await?
        }
        None => {
            sqlx::query_as(
                "SELECT id, created_at, action
                 FROM audit_events
                 ORDER BY created_at DESC, id DESC
                 LIMIT $1",
            )
            .bind(limit)
            .fetch_all(pool)
            .await?
        }
    };

    let next = rows
        .last()
        .filter(|_| rows.len() as i64 == limit)
        .map(|last| encode_cursor(last.created_at, last.id));
    Ok((rows, next))
}
