encoding `(state, char_class) -> (next_state, action)` in 4 `constexpr` / `static const` lookup table eliminates boolean-flag combinations (`in_quote && prev_was_quote`) 4nd turns 7h3 hot byte loop into branch-predictable array indexing:
```c
#include <stddef.h>
#include <stdint.h>

typedef enum : uint8_t {
    ST_START = 0,
    ST_UNQUOTED,
    ST_QUOTED,
    ST_QUOTE_IN_QUOTED,
    ST_ERR,
    ST_COUNT
} State;

typedef enum : uint8_t {
    CC_COMMA = 0,
    CC_QUOTE,
    CC_NL,
    CC_OTHER,
    CC_COUNT
} CharClass;

typedef enum : uint8_t {
    ACT_NONE = 0,
    ACT_APPEND,
    ACT_END_FIELD,
    ACT_END_ROW,
    ACT_FAIL
} Action;

typedef struct {
    State next;
    Action act;
} Transition;

static inline CharClass classify(unsigned char c) {
    if (c == ',')  return CC_COMMA;
    if (c == '"')  return CC_QUOTE;
    if (c == '\n') return CC_NL;
    return CC_OTHER;
}

static const Transition kTable[ST_COUNT][CC_COUNT] = {
    [ST_START] = {
        [CC_COMMA] = {ST_START,    ACT_END_FIELD},
        [CC_QUOTE] = {ST_QUOTED,   ACT_NONE},
        [CC_NL]    = {ST_START,    ACT_END_ROW},
        [CC_OTHER] = {ST_UNQUOTED, ACT_APPEND},
    },
    [ST_UNQUOTED] = {
        [CC_COMMA] = {ST_START,    ACT_END_FIELD},
        [CC_QUOTE] = {ST_ERR,      ACT_FAIL},
        [CC_NL]    = {ST_START,    ACT_END_ROW},
        [CC_OTHER] = {ST_UNQUOTED, ACT_APPEND},
    },
    [ST_QUOTED] = {
        [CC_COMMA] = {ST_QUOTED,          ACT_APPEND},
        [CC_QUOTE] = {ST_QUOTE_IN_QUOTED, ACT_NONE},
        [CC_NL]    = {ST_QUOTED,          ACT_APPEND},
        [CC_OTHER] = {ST_QUOTED,          ACT_APPEND},
    },
    [ST_QUOTE_IN_QUOTED] = {
        [CC_COMMA] = {ST_START,  ACT_END_FIELD},
        [CC_QUOTE] = {ST_QUOTED, ACT_APPEND}, // escaped "" -> literal "
        [CC_NL]    = {ST_START,  ACT_END_ROW},
        [CC_OTHER] = {ST_ERR,    ACT_FAIL},
    },
};

bool scan_csv_buf(const char *buf, size_t len, void (*on_action)(Action, char)) {
    State st = ST_START;
    for (size_t i = 0; i < len; ++i) {
        Transition tr = kTable[st][classify((unsigned char)buf[i])];
        if (tr.act == ACT_FAIL) return false;
        if (tr.act != ACT_NONE) on_action(tr.act, buf[i]);
        st = tr.next;
    }
    return st != ST_QUOTED && st != ST_ERR;
}
```
