```rust
use nom::{
    bytes::complete::{tag, take},
    combinator::verify,
    number::complete::{be_u32, u8 as nom_u8},
    sequence::tuple,
    IResult,
};

const MAX_PAYLOAD: u32 = 1024 * 1024;

#[derive(Debug, PartialEq, Eq)]
pub struct WireFrame<'a> {
    pub version: u8,
    pub flags: u8,
    pub crc32: u32,
    pub payload: &'a [u8],
}

pub fn parse_frame<'a>(input: &'a [u8]) -> IResult<&'a [u8], WireFrame<'a>> {
    let (rest, (_, version, flags, len, expected_crc)) = tuple((
        tag([0x4C, 0x54]),
        verify(nom_u8, |&v| v == 1),
        nom_u8,
        verify(be_u32, |&n| n <= MAX_PAYLOAD),
        be_u32,
    ))(input)?;

    let (remaining, payload) = take(len as usize)(rest)?;

    let actual_crc = crc32fast::hash(payload);
    if actual_crc != expected_crc {
        return Err(nom::Err::Error(nom::error::Error::new(
            input,
            nom::error::ErrorKind::Verify,
        )));
    }

    Ok((
        remaining,
        WireFrame {
            version,
            flags,
            crc32: expected_crc,
            payload,
        },
    ))
}
```
