package netfilter

import "net/netip"

type Allowlist struct {
	prefixes []netip.Prefix
	exact    map[netip.Addr]struct{}
}

func NewAllowlist(cidrs []string, hosts []string) (*Allowlist, error) {
	a := &Allowlist{
		prefixes: make([]netip.Prefix, 0, len(cidrs)),
		exact:    make(map[netip.Addr]struct{}, len(hosts)),
	}
	for _, raw := range cidrs {
		pfx, err := netip.ParsePrefix(raw)
		if err != nil {
			return nil, err
		}
		a.prefixes = append(a.prefixes, pfx.Masked())
	}
	for _, raw := range hosts {
		ip, err := netip.ParseAddr(raw)
		if err != nil {
			return nil, err
		}
		a.exact[ip.Unmap()] = struct{}{}
	}
	return a, nil
}

// Zero-alloc hot-path check
func (a *Allowlist) Contains(rawAddr string) bool {
	ip, err := netip.ParseAddr(rawAddr)
	if err != nil {
		return false
	}
	ip = ip.Unmap() // normalizes ::ffff:10.0.0.1 -> 10.0.0.1
	if _, ok := a.exact[ip]; ok {
		return true
	}
	for _, pfx := range a.prefixes {
		if pfx.Contains(ip) {
			return true
		}
	}
	return false
}

// Iterate every usable host in a prefix using value-type Next()
func IterSubnet(pfx netip.Prefix, yield func(netip.Addr) bool) {
	for ip := pfx.Masked().Addr(); pfx.Contains(ip); ip = ip.Next() {
		if !yield(ip) {
			return
		}
	}
}
```
