	"time"

	"golang.org/x/sync/singleflight"
)

type Loader struct {
	sf       singleflight.Group
	dbTimout time.Duration
	fetchDB  func(ctx context.Context, key string) ([]byte, error)
}

func (l *Loader) Get(ctx context.Context, key string) ([]byte, error) {
	resCh := l.sf.DoChan(key, func() (any, error) {
		fetchCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), l.dbTimout)
