package main

import (
	"bufio"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"strings"
)

func openInput(path string) (io.ReadCloser, error) {
	if path != "" && path != "-" {
		return os.Open(path)
	}
	info, err := os.Stdin.Stat()
	if err != nil {
		return nil, err
	}
	if (info.Mode() & os.ModeCharDevice) != 0 {
		return nil, errors.New("no piped stdin detected; pass -file <path>")
	}
	return io.NopCloser(os.Stdin), nil
}

func runStats(args []string) error {
	fs := flag.NewFlagSet("stats", flag.ContinueOnError)
	file := fs.String("file", "", "input file (or pipe via stdin)")
	if err := fs.Parse(args); err != nil {
		return err
	}
	rc, err := openInput(*file)
	if err != nil {
		return err
	}
	defer rc.Close()

	var lines, bytes int64
	sc := bufio.NewScanner(rc)
	for sc.Scan() {
		lines++
		bytes += int64(len(sc.Bytes()))
	}
	fmt.Printf("lines=%d payload_bytes=%d\n", lines, bytes)
	return sc.Err()
}

func runFilter(args []string) error {
	fs := flag.NewFlagSet("filter", flag.ContinueOnError)
	file := fs.String("file", "", "input file (or pipe via stdin)")
	substr := fs.String("match", "", "required substring")
	if err := fs.Parse(args); err != nil {
		return err
	}
	rc, err := openInput(*file)
	if err != nil {
		return err
	}
	defer rc.Close()

	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	sc := bufio.NewScanner(rc)
	for sc.Scan() {
		if strings.Contains(sc.Text(), *substr) {
			_, _ = fmt.Fprintln(w, sc.Text())
		}
	}
	return sc.Err()
}

func main() {
	if len(os.Args) < 2 {
		fmt.Fprintln(os.Stderr, "usage: logtool <stats|filter> [flags]")
		os.Exit(2)
	}
	var err error
	switch os.Args[1] {
	case "stats":
		err = runStats(os.Args[2:])
	case "filter":
		err = runFilter(os.Args[2:])
	default:
		err = fmt.Errorf("unknown subcommand %q", os.Args[1])
	}
	if err != nil {
		fmt.Fprintln(os.Stderr, "error:", err)
		os.Exit(1)
	}
}
