type Option func(*Checker)

func WithHTTPClient(c HTTPDoer) Option {
	return func(ch *Checker) {
		if c != nil {
			ch.client = c
		}
	}
}

func WithClock(now func() time.Time) Option {
	return func(ch *Checker) {
		if now != nil {
			ch.now = now
		}
	}
