```ts
export type Expr =
  | { kind: "num"; value: number }
  | { kind: "ident"; name: string }
  | { kind: "unary"; op: string; rhs: Expr }
  | { kind: "binary"; op: string; lhs: Expr; rhs: Expr }
  | { kind: "call"; callee: Expr; args: Expr[] };

type Token =
  | { type: "num"; value: number }
  | { type: "ident"; text: string }
  | { type: "op"; text: string }
  | { type: "eof" };

function tokenize(src: string): Token[] {
  const tokens: Token[] = [];
  const re = /\s*(?:(\d+(?:\.\d+)?)|([a-zA-Z_]\w*)|([+\-*/^(),]))/gy;
  let pos = 0;
  while (pos < src.length) {
    re.lastIndex = pos;
    const m = re.exec(src);
    if (!m) throw new SyntaxError(`Unexpected char at ${pos}: '${src[pos]}'`);
    pos = re.lastIndex;
    if (m[1] !== undefined) tokens.push({ type: "num", value: Number(m[1]) });
    else if (m[2] !== undefined) tokens.push({ type: "ident", text: m[2] });
    else if (m[3] !== undefined) tokens.push({ type: "op", text: m[3] });
  }
  const tailWs = src.slice(pos).trim();
  if (tailWs) throw new SyntaxError(`Trailing input: ${tailWs}`);
  tokens.push({ type: "eof" });
  return tokens;
}

function infixBindingPower(op: string): [number, number] | null {
  switch (op) {
    case "+":
    case "-":
      return [10, 11];
    case "*":
    case "/":
      return [20, 21];
    case "^":
      return [31, 30]; // right-associative: rbp < lbp
    default:
      return null;
  }
}

export function parseExpression(source: string): Expr {
  const tokens = tokenize(source);
  let idx = 0;
  const peek = (): Token => tokens[idx];
  const next = (): Token => tokens[idx++];

  const expectOp = (ch: string): void => {
    const t = next();
    if (t.type !== "op" || t.text !== ch) {
      throw new SyntaxError(`Expected '${ch}'`);
    }
  };

  function parseExpr(minBp: number): Expr {
    const t = next();
    let lhs: Expr;

    if (t.type === "num") {
      lhs = { kind: "num", value: t.value };
    } else if (t.type === "ident") {
      lhs = { kind: "ident", name: t.text };
    } else if (t.type === "op" && t.text === "-") {
      lhs = { kind: "unary", op: "-", rhs: parseExpr(25) };
    } else if (t.type === "op" && t.text === "(") {
      lhs = parseExpr(0);
      expectOp(")");
    } else {
      throw new SyntaxError(`Unexpected token in prefix position: ${JSON.stringify(t)}`);
    }

    while (true) {
      const cur = peek();
      if (cur.type !== "op") break;

      // Postfix call operator `(` binds tighter than binary ops
      if (cur.text === "(") {
        const callLbp = 40;
        if (callLbp < minBp) break;
        next();
        const args: Expr[] = [];
        if (!(peek().type === "op" && (peek() as { text: string }).text === ")")) {
          do {
            args.push(parseExpr(0));
          } while (
            peek().type === "op" &&
            (peek() as { text: string }).text === "," &&
            next()
          );
        }
        expectOp(")");
        lhs = { kind: "call", callee: lhs, args };
        continue;
      }

      const bp = infixBindingPower(cur.text);
      if (!bp) break;
      const [lbp, rbp] = bp;
      if (lbp < minBp) break;

      next();
      const rhs = parseExpr(rbp);
      lhs = { kind: "binary", op: cur.text, lhs, rhs };
    }

    return lhs;
  }

  const ast = parseExpr(0);
  if (peek().type !== "eof") throw new SyntaxError("Unexpected trailing tokens");
  return ast;
}
```

