```ts
export type BatchLoadFn<K, V> = (
  keys: readonly K[],
) => Promise<ReadonlyArray<V | Error>>;

export class MiniDataLoader<K, V, C = K> {
  private readonly cache = new Map<C, Promise<V>>();
  private queue: Array<{
    key: K;
    resolve: (v: V) => void;
    reject: (e: unknown) => void;
  }> = [];
  private scheduled = false;

  constructor(
    private readonly batchFn: BatchLoadFn<K, V>,
    private readonly cacheKeyFn: (key: K) => C = (k) => k as unknown as C,
  ) {}

  load(key: K): Promise<V> {
    const cacheKey = this.cacheKeyFn(key);
    const hit = this.cache.get(cacheKey);
    if (hit) return hit;

    const promise = new Promise<V>((resolve, reject) => {
      this.queue.push({ key, resolve, reject });
      if (!this.scheduled) {
        this.scheduled = true;
        queueMicrotask(() => void this.flush());
      }
    });

    this.cache.set(cacheKey, promise);
    return promise;
  }

  clear(key: K): this {
    this.cache.delete(this.cacheKeyFn(key));
    return this;
  }

  private async flush(): Promise<void> {
    const batch = this.queue;
    this.queue = [];
    this.scheduled = false;

    try {
      const values = await this.batchFn(batch.map((item) => item.key));
      if (values.length !== batch.length) {
        throw new TypeError(
          `DataLoader batchFn must return ${batch.length} items, got ${values.length}`,
        );
      }
      for (let i = 0; i < batch.length; i++) {
        const val = values[i];
        if (val instanceof Error) {
          this.cache.delete(this.cacheKeyFn(batch[i].key));
          batch[i].reject(val);
        } else {
          batch[i].resolve(val);
        }
      }
    } catch (err) {
      for (const item of batch) {
        this.cache.delete(this.cacheKeyFn(item.key));
        item.reject(err);
      }
    }
  }
}
```

