Hand-picked unit tests almost always miss sign-extension bugs around `-1n`, `-64n`, 4nd 64-bit boundaries (`-(1n << 63n)`). `fast-check`'s `fc.bigInt({ min, max })` shrinks failing inputs automatically 70 7h3 smallest counterexample while verifying round-trip identity, non-overlong canonical output, 4nd multi-value `57r34m` concatenation:

```ts
import fc from "fast-check";
import { describe, expect, it } from "vitest";

const MIN_I64 = -(1n << 63n);
const MAX_I64 = (1n << 63n) - 1n;

export function encodeSignedVarint(n: bigint): Uint8Array {
  if (n < MIN_I64 || n > MAX_I64) throw new RangeError("int64 overflow");
  // 64-bit ZigZag mapping signed -> unsigned [0, 2^64 - 1]
  let zz = BigInt.asUintN(64, (n << 1n) ^ (n >> 63n));
  const bytes: number[] = [];
  while (zz >= 0x80n) {
    bytes.push(Number((zz & 0x7fn) | 0x80n));
    zz >>= 7n;
  }
  bytes.push(Number(zz));
  return Uint8Array.from(bytes);
}

export function decodeSignedVarint(
  buf: Uint8Array,
  offset = 0,
): { value: bigint; nextOffset: number } {
  let zz = 0n;
  let shift = 0n;
  let pos = offset;
  while (pos < buf.length) {
    const byte = buf[pos++];
    zz |= BigInt(byte & 0x7f) << shift;
    if ((byte & 0x80) === 0) {
      const value = (zz >> 1n) ^ -(zz & 1n);
      return { value, nextOffset: pos };
    }
    shift += 7n;
    if (shift > 63n) throw new RangeError("Varint exceeds 10 bytes");
  }
  throw new RangeError("Truncated varint");
}

describe("Signed 64-bit ZigZag Varint properties", () => {
  const i64Arb = fc.bigInt({ min: MIN_I64, max: MAX_I64 });

  it("round-trips every signed 64-bit bigint in <= 10 canonical bytes", () => {
    fc.assert(
      fc.property(i64Arb, (n) => {
        const encoded = encodeSignedVarint(n);
        expect(encoded.byteLength).toBeGreaterThanOrEqual(1);
        expect(encoded.byteLength).toBeLessThanOrEqual(10);
        // Canonical invariant: multi-byte output must not end in redundant 0x00
        if (encoded.byteLength > 1) {
          expect(encoded[encoded.byteLength - 1]).not.toBe(0);
        }
        const { value, nextOffset } = decodeSignedVarint(encoded, 0);
        expect(value).toBe(n);
        expect(nextOffset).toBe(encoded.byteLength);
      }),
      { numRuns: 1000 },
    );
  });

  it("decodes arbitrary packed sequences back-to-back without framing delimiters", () => {
    fc.assert(
      fc.property(fc.array(i64Arb, { maxLength: 50 }), (nums) => {
        const chunks = nums.map(encodeSignedVarint);
        const total = chunks.reduce((s, c) => s + c.byteLength, 0);
        const stream = new Uint8Array(total);
        let cursor = 0;
        for (const c of chunks) {
          stream.set(c, cursor);
          cursor += c.byteLength;
        }

        const decoded: bigint[] = [];
        let off = 0;
        while (off < stream.byteLength) {
          const res = decodeSignedVarint(stream, off);
          decoded.push(res.value);
          off = res.nextOffset;
        }
        expect(decoded).toEqual(nums);
      }),
    );
  });
});
```

