export interface AstNode {
  kind: string;
  children: AstNode[];
}

interface StackFrame {
  node: AstNode;
  expanded: boolean;
}

export function computeSubtreeSizes(root: AstNode): Map<AstNode, number> {
  const sizes = new Map<AstNode, number>();
  const stack: StackFrame[] = [{ node: root, expanded: false }];

  while (stack.length > 0) {
    const frame = stack.pop()!;
    const { node, expanded } = frame;

