      // Re-push parent marked expanded so it runs AFTER all children pop
      frame.expanded = true;
      stack.push(frame);
      for (let i = node.children.length - 1; i >= 0; i--) {
        stack.push({ node: node.children[i], expanded: false });
      }
    } else {
      let total = 1;
      for (let i = 0; i < node.children.length; i++) {
        total += sizes.get(node.children[i])!;
      }
      sizes.set(node, total);
    }
  }

  return sizes;
}
