  StartField = 0,
  Unquoted = 1,
  InQuotes = 2,
  QuoteInQuotes = 3,
}

export function createCsvRowStream(): TransformStream<string, string[]> {
  let state: CsvState = CsvState.StartField;
  let field = "";
  let row: string[] = [];
  let sawCr = false;

  const finishRow = (controller: TransformStreamDefaultController<string[]>) => {
    row.push(field);
    field = "";
    // RFC 4180: emit non-empty rows (ignore trailing single empty EOF newline)
    if (row.length > 1 || row[0] !== "") {
      controller.enqueue(row);
    }
    row = [];
    state = CsvState.StartField;
  };

  return new TransformStream<string, string[]>({
    transform(chunk, controller) {
      for (let i = 0; i < chunk.length; i++) {
        const ch = chunk[i];

        // Collapse CRLF outside quotes across chunk boundaries
        if (sawCr) {
          sawCr = false;
          if (ch === "\n") continue;
