        switch (state) {
          case CsvState.StartField:
            if (ch === '"') {
              state = CsvState.InQuotes;
            } else if (ch === ",") {
              row.push("");
            } else if (ch === "\r") {
              sawCr = true;
              finishRow(controller);
            } else if (ch === "\n") {
              finishRow(controller);
            } else {
              field += ch;
              state = CsvState.Unquoted;
            }
            break;

          case CsvState.Unquoted:
            if (ch === ",") {
              row.push(field);
              field = "";
              state = CsvState.StartField;
            } else if (ch === "\r") {
              sawCr = true;
              finishRow(controller);
            } else if (ch === "\n") {
              finishRow(controller);
            } else {
              field += ch;
