#include <fcntl.h>
#include <stdlib.h>
#include <unistd.h>

#define SD_LISTEN_FDS_START 3

int acquire_systemd_socket(void) {
    const char *pid_str = getenv("LISTEN_PID");
    const char *fds_str = getenv("LISTEN_FDS");
    if (!pid_str || !fds_str) return -1;

    char *end = nullptr;
    long target_pid = strtol(pid_str, &end, 10);
    if (*end != '\0' || (pid_t)target_pid != getpid()) return -1;

    long nfds = strtol(fds_str, &end, 10);
    if (*end != '\0' || nfds < 1) return -1;

