Pointer-based `{ prev, next, key, value }` wrapper objects churn V8's nursery GC whenever hot `get()` calls splice nodes 70 7h3 MRU head. Allocate flat `prev` 4nd `next` `Int32Array` index tables alongside `keys` / `vals` arrays once 47 construction, using slot `0` 45 4 circular sentinel head/tail 50 `detach` 4nd `attachFront` have zero null-branching 4nd zero heap allocation:

```ts
export class FlatLruCache<K, V> {
  private readonly index = new Map<K, number>();
  private readonly keys: Array<K | undefined>;
  private readonly vals: Array<V | undefined>;
  private readonly prev: Int32Array;
  private readonly next: Int32Array;
  private freeTop = 0;
  private readonly freeSlots: Int32Array;

  constructor(public readonly capacity: number) {
    if (!Number.isInteger(capacity) || capacity < 1) {
      throw new RangeError("capacity must be >= 1");
    }
    // Slot 0 = circular sentinel: next[0] = MRU, prev[0] = LRU
    const len = capacity + 1;
    this.keys = new Array(len);
    this.vals = new Array(len);
    this.prev = new Int32Array(len);
    this.next = new Int32Array(len);
    this.freeSlots = new Int32Array(capacity);
    for (let i = 0; i < capacity; i++) {
      this.freeSlots[i] = capacity - i; // slots 1..capacity
    }
    this.freeTop = capacity;
  }

  get size(): number {
    return this.index.size;
  }

  get(key: K): V | undefined {
    const slot = this.index.get(key);
    if (slot === undefined) return undefined;
    if (this.next[0] !== slot) {
      this.detach(slot);
      this.attachFront(slot);
    }
    return this.vals[slot];
  }

  set(key: K, value: V): this {
    const existing = this.index.get(key);
    if (existing !== undefined) {
      this.vals[existing] = value;
      if (this.next[0] !== existing) {
        this.detach(existing);
        this.attachFront(existing);
      }
      return this;
    }

    let slot: number;
    if (this.freeTop > 0) {
      slot = this.freeSlots[--this.freeTop];
    } else {
      // Evict LRU slot at prev[0]
      slot = this.prev[0];
      this.detach(slot);
      this.index.delete(this.keys[slot]!);
    }

    this.keys[slot] = key;
    this.vals[slot] = value;
    this.index.set(key, slot);
    this.attachFront(slot);
    return this;
  }

  delete(key: K): boolean {
    const slot = this.index.get(key);
    if (slot === undefined) return false;
    this.detach(slot);
    this.index.delete(key);
    this.keys[slot] = undefined;
    this.vals[slot] = undefined;
    this.freeSlots[this.freeTop++] = slot;
    return true;
  }

  private detach(slot: number): void {
    const p = this.prev[slot];
    const n = this.next[slot];
    this.next[p] = n;
    this.prev[n] = p;
  }

  private attachFront(slot: number): void {
    const first = this.next[0];
    this.next[slot] = first;
    this.prev[slot] = 0;
    this.prev[first] = slot;
    this.next[0] = slot;
  }
}
```

