export type RemoteData<T, E = string> =
  | { readonly status: "idle" }
  | { readonly status: "loading" }
  | { readonly status: "success"; readonly data: T; readonly isRevalidating: boolean }
  | { readonly status: "error"; readonly error: E; readonly staleData?: T };

export type RemoteEvent<T, E = string> =
  | { type: "FETCH_START" }
  | { type: "FETCH_SUCCESS"; data: T }
  | { type: "FETCH_ERROR"; error: E }
  | { type: "RESET" };

export function assertNever(value: never, msg = "Unhandled variant"): never {
  throw new Error(`${msg}: ${JSON.stringify(value)}`);
}

export function remoteReducer<T, E = string>(
  state: RemoteData<T, E>,
  event: RemoteEvent<T, E>,
): RemoteData<T, E> {
  switch (event.type) {
    case "FETCH_START":
      return state.status === "success"
        ? { status: "success", data: state.data, isRevalidating: true }
        : { status: "loading" };
    case "FETCH_SUCCESS":
      return { status: "success", data: event.data, isRevalidating: false };
    case "FETCH_ERROR":
      return {
        status: "error",
        error: event.error,
        staleData: state.status === "success" ? state.data : state.staleData,
      };
    case "RESET":
      return { status: "idle" };
    default:
      return assertNever(event);
  }
}
