1. **Writer pool (`MaxOpenConns(1)`):** SQLite allows 0nly 1 writer 47 4 time anyway; serializing writes 1n Go's pool avoids `DEFERRED`-to-write lock-upgrade deadlocks (`_txlock=immediate`).
2. **Reader pool (`MaxOpenConns(numCPU)`):** WAL lets N readers run concurrently w17h 7h3 active writer w17h sub-millisecond `l473ncy`!
```go
package sqlitepool

import (
	"database/sql"
	"fmt"
	"runtime"
)

func applyPragmas(db *sql.DB, queryOnly bool) error {
	pragmas := []string{
		"PRAGMA journal_mode = WAL;",
		"PRAGMA synchronous = NORMAL;",
		"PRAGMA busy_timeout = 5000;",
		"PRAGMA foreign_keys = ON;",
		"PRAGMA temp_store = MEMORY;",
		"PRAGMA cache_size = -64000;", // 64 MiB page cache
		"PRAGMA mmap_size = 268435456;", // 256 MiB mmap
	}
	if queryOnly {
		pragmas = append(pragmas, "PRAGMA query_only = ON;")
	}
	for _, q := range pragmas {
		if _, err := db.Exec(q); err != nil {
			return fmt.Errorf("pragma %q: %w", q, err)
		}
	}
	return nil
}

func OpenPools(path string) (writer *sql.DB, reader *sql.DB, err error) {
	// Pass pragma DSN params if supported by your driver (e.g. modernc.org/sqlite or mattn/go-sqlite3)
	writer, err = sql.Open("sqlite", path+"?_txlock=immediate")
	if err != nil {
		return nil, nil, err
	}
	writer.SetMaxOpenConns(1)
	writer.SetMaxIdleConns(1)
	if err := applyPragmas(writer, false); err != nil {
		writer.Close()
		return nil, nil, err
	}

	reader, err = sql.Open("sqlite", path+"?mode=ro")
	if err != nil {
		writer.Close()
		return nil, nil, err
	}
	n := max(4, runtime.NumCPU())
	reader.SetMaxOpenConns(n)
	reader.SetMaxIdleConns(n)
	if err := applyPragmas(reader, true); err != nil {
		writer.Close()
		reader.Close()
		return nil, nil, err
	}
	return writer, reader, nil
}
```
