pub struct ConsistentRing {
    vnodes_per_host: u32,
    ring: BTreeMap<u64, Arc<str>>,
}

impl ConsistentRing {
    pub fn new(vnodes_per_host: u32) -> Self {
        Self {
            vnodes_per_host: vnodes_per_host.max(1),
            ring: BTreeMap::new(),
        }
    }

    pub fn add_node(&mut self, host: &str) {
        let shared: Arc<str> = Arc::from(host);
        for replica in 0..self.vnodes_per_host {
            let rep_bytes = replica.to_le_bytes();
            let pos = fnv1a_64(&[host.as_bytes(), b"#", &rep_bytes]);
            self.ring.insert(pos, Arc::clone(&shared));
        }
    }

    pub fn remove_node(&mut self, host: &str) {
        for replica in 0..self.vnodes_per_host {
            let rep_bytes = replica.to_le_bytes();
            let pos = fnv1a_64(&[host.as_bytes(), b"#", &rep_bytes]);
            if self.ring.get(&pos).is_some_and(|n| n.as_ref() == host) {
                self.ring.remove(&pos);
            }
        }
    }

    pub fn route(&self, key: &[u8]) -> Option<&str> {
        if self.ring.is_empty() {
            return None;
        }
        let h = fnv1a_64(&[key]);
        self.ring
            .range(h..)
            .next()
            .or_else(|| self.ring.iter().next())
            .map(|(_, host)| host.as_ref())
    }
}
