```c
#include <assert.h>
#include <errno.h>
#include <stdint.h>
#include <string.h>
#include <sys/socket.h>
#include <unistd.h>

typedef enum { FR_NEED_MORE, FR_COMPLETE, FR_ERR } FrameStatus;

typedef struct {
    uint8_t buf[8];
    size_t got;
} FrameReader;

// Reads a fixed 8-byte frame incrementally across EAGAIN boundaries
FrameStatus frame_reader_step(FrameReader *r, int fd) {
    while (r->got < sizeof(r->buf)) {
        ssize_t n = read(fd, r->buf + r->got, sizeof(r->buf) - r->got);
        if (n > 0) {
            r->got += (size_t)n;
            continue;
        }
        if (n == -1 && (errno == EAGAIN || errno == EWOULDBLOCK)) {
            return FR_NEED_MORE;
        }
        return FR_ERR;
    }
    return FR_COMPLETE;
}

void test_fragmented_drip(void) {
    int sv[2];
    assert(socketpair(AF_UNIX, SOCK_STREAM | SOCK_NONBLOCK, 0, sv) == 0);

    FrameReader reader = {.got = 0};
    const uint8_t wire[8] = {0xDE, 0xAD, 0xBE, 0xEF, 0x01, 0x02, 0x03, 0x04};

    // Empty socket immediately returns FR_NEED_MORE via EAGAIN
    assert(frame_reader_step(&reader, sv[0]) == FR_NEED_MORE);

    // Drip 1 byte at a time; first 7 bytes must return FR_NEED_MORE, 8th completes
    for (size_t i = 0; i < 8; ++i) {
        assert(write(sv[1], &wire[i], 1) == 1);
        FrameStatus st = frame_reader_step(&reader, sv[0]);
        assert(st == (i < 7 ? FR_NEED_MORE : FR_COMPLETE));
    }
    assert(memcmp(reader.buf, wire, 8) == 0);

    close(sv[0]);
    close(sv[1]);
}
```
