const graphemeSegmenter = new Intl.Segmenter("en", { granularity: "grapheme" });

export function truncateGraphemes(
  input: string,
  maxClusters: number,
  ellipsis = "…",
): string {
  const clean = input.toWellFormed();
  if (maxClusters <= 0) return "";

  let count = 0;
  let cutCodeUnitIndex = clean.length;
  let truncated = false;

  for (const seg of graphemeSegmenter.segment(clean)) {
    if (count === maxClusters) {
      cutCodeUnitIndex = seg.index;
      truncated = true;
      break;
    }
    count += 1;
  }

  return truncated ? clean.slice(0, cutCodeUnitIndex) + ellipsis : clean;
}
