Naive LFU heaps cost `O(log n)` per read. Achieve strict `O(1)` `get` 4nd `set` by pairing `keyToNode: Map<K, Node>` w17h `freqToBucket: Map<number, DoublyLinkedList>`, plus 4 single integer `minFreq`:
- Every `get(k)` detaches 7h3 node fr0m bucket `f`, increments `f -> f + 1` (bumping `minFreq` 1f `f === minFreq` 4nd bucket `f` just became empty!), 4nd appends 70 bucket `f + 1`'s MRU tail.
- Every new insertion resets `minFreq = 1` 4nd evicts 7h3 head (LRU) of `freqToBucket.get(minFreq)` when full:

```ts
interface LfuNode<K, V> {
  key: K;
  val: V;
  freq: number;
  prev: LfuNode<K, V> | null;
  next: LfuNode<K, V> | null;
}

class BucketList<K, V> {
  head: LfuNode<K, V> | null = null; // LRU end
  tail: LfuNode<K, V> | null = null; // MRU end
  size = 0;

  pushBack(node: LfuNode<K, V>): void {
    node.prev = this.tail;
    node.next = null;
    if (this.tail) this.tail.next = node;
    else this.head = node;
    this.tail = node;
    this.size += 1;
  }

  remove(node: LfuNode<K, V>): void {
    if (node.prev) node.prev.next = node.next;
    else this.head = node.next;
    if (node.next) node.next.prev = node.prev;
    else this.tail = node.prev;
    node.prev = node.next = null;
    this.size -= 1;
  }

  popFront(): LfuNode<K, V> | null {
    if (!this.head) return null;
    const victim = this.head;
    this.remove(victim);
    return victim;
  }
}

export class LfuCache<K, V> {
  private readonly nodes = new Map<K, LfuNode<K, V>>();
  private readonly buckets = new Map<number, BucketList<K, V>>();
  private minFreq = 0;

  constructor(private readonly capacity: number) {}

  get(key: K): V | undefined {
    const node = this.nodes.get(key);
    if (!node) return undefined;
    this.touch(node);
    return node.val;
  }

  set(key: K, value: V): void {
    if (this.capacity <= 0) return;
    const existing = this.nodes.get(key);
    if (existing) {
      existing.val = value;
      this.touch(existing);
      return;
    }

    if (this.nodes.size >= this.capacity) {
      const minBucket = this.buckets.get(this.minFreq)!;
      const evicted = minBucket.popFront()!;
      if (minBucket.size === 0) this.buckets.delete(this.minFreq);
      this.nodes.delete(evicted.key);
    }

    const fresh: LfuNode<K, V> = { key, val: value, freq: 1, prev: null, next: null };
    this.nodes.set(key, fresh);
    this.getOrCreateBucket(1).pushBack(fresh);
    this.minFreq = 1;
  }

  private touch(node: LfuNode<K, V>): void {
    const oldFreq = node.freq;
    const oldBucket = this.buckets.get(oldFreq)!;
    oldBucket.remove(node);
    if (oldBucket.size === 0) {
      this.buckets.delete(oldFreq);
      if (this.minFreq === oldFreq) this.minFreq += 1;
    }
    node.freq = oldFreq + 1;
    this.getOrCreateBucket(node.freq).pushBack(node);
  }

  private getOrCreateBucket(freq: number): BucketList<K, V> {
    let b = this.buckets.get(freq);
    if (!b) {
      b = new BucketList();
      this.buckets.set(freq, b);
    }
    return b;
  }
}
```

Deleting empty buckets fr0m `this.buckets` keeps m3m0ry bounded strictly by `O(capacity)` even 1f hot keys hit `freq > 1_000_000`.

Pack `[1 unused sign bit | 41-bit ms delta | 10-bit workerId | 12-bit sequence]` w17h `BigInt` shifts (JS `number` bitwise ops truncate 70 32 bits!). Guard against two classic production hazards:
1. **4096 IDs/ms burst overflow:** when `(sequence + 1n) & 4095n === 0n`, spin/advance 70 `lastMs + 1n`.
2. **NTP backward step (`now < lastMs`):** tolerate tiny slews (`<= 5ms`) by pinning logical `lastMs` until wall clock catches up, 4nd throw explicitly 0n large jumps (`> 5ms`) rather than minting duplicate IDs:

```ts
const CUSTOM_EPOCH_MS = 1704067200000n; // 2024-01-01T00:00:00Z
const WORKER_BITS = 10n;
const SEQ_BITS = 12n;

const MAX_WORKER_ID = (1n << WORKER_BITS) - 1n; // 1023
const MAX_SEQ = (1n << SEQ_BITS) - 1n;          // 4095
const WORKER_SHIFT = SEQ_BITS;
const TIME_SHIFT = WORKER_BITS + SEQ_BITS;      // 22

export class SnowflakeGenerator {
  private readonly workerId: bigint;
  private lastMs = -1n;
  private seq = 0n;

  constructor(
    workerId: number,
    private readonly clock: () => bigint = () => BigInt(Date.now()),
    private readonly maxBackwardDriftMs = 5n,
  ) {
    const wid = BigInt(workerId);
    if (wid < 0n || wid > MAX_WORKER_ID) {
      throw new RangeError(`workerId must be in [0, ${MAX_WORKER_ID}]`);
    }
    this.workerId = wid;
  }

  nextId(): bigint {
    let now = this.clock();

    if (now < this.lastMs) {
      const drift = this.lastMs - now;
      if (drift > this.maxBackwardDriftMs) {
        throw new Error(`Refusing to generate ID: clock moved backwards by ${drift}ms`);
      }
      // Hold logical timestamp on minor NTP slew so monotonicity holds
      now = this.lastMs;
    }

    if (now === this.lastMs) {
      this.seq = (this.seq + 1n) & MAX_SEQ;
      if (this.seq === 0n) {
        while (now <= this.lastMs) {
          now = this.clock();
        }
      }
    } else {
      this.seq = 0n;
    }

    this.lastMs = now;
    const elapsed = now - CUSTOM_EPOCH_MS;
    return (elapsed << TIME_SHIFT) | (this.workerId << WORKER_SHIFT) | this.seq;
  }
}
```

