import { FlatLruCache } from "./flat-lru";

// Trivial reference oracle leveraging JS Map's insertion-order guarantee
class ReferenceLruModel {
  readonly map = new Map<string, number>();
  constructor(readonly capacity: number) {}
}

class PutCmd implements fc.Command<ReferenceLruModel, FlatLruCache<string, number>> {
  constructor(readonly key: string, readonly val: number) {}
  check = () => true;
  run(m: ReferenceLruModel, r: FlatLruCache<string, number>): void {
