```ts
import type { Socket } from "node:net";

export async function* readLengthPrefixedFrames(
  socket: Socket,
  options: { highWaterMark?: number; signal?: AbortSignal } = {},
): AsyncGenerator<Uint8Array, void, undefined> {
  const highWaterMark = options.highWaterMark ?? 32;
  const signal = options.signal;
  signal?.throwIfAborted();

  const readyFrames: Uint8Array[] = [];
  let stash: Buffer<ArrayBufferLike> = Buffer.alloc(0);
  let ended = false;
  let failure: unknown = null;
  let wakeConsumer: (() => void) | null = null;

  const notify = () => {
    if (wakeConsumer) {
      const fn = wakeConsumer;
      wakeConsumer = null;
      fn();
    }
  };

  const onData = (chunk: Buffer) => {
    stash = stash.length === 0 ? chunk : Buffer.concat([stash, chunk]);
    while (stash.length >= 4) {
      const bodyLen = stash.readUInt32BE(0);
      if (stash.length < 4 + bodyLen) break;
      readyFrames.push(stash.subarray(4, 4 + bodyLen));
      stash = stash.subarray(4 + bodyLen);
    }
    if (readyFrames.length >= highWaterMark) {
      socket.pause();
    }
    notify();
  };

  const onEnd = () => {
    ended = true;
    notify();
  };
  const onError = (err: unknown) => {
    failure = err;
    notify();
  };
  const onAbort = () => {
    failure = signal?.reason ?? new Error("Aborted");
    notify();
  };

  socket.on("data", onData);
  socket.once("end", onEnd);
  socket.once("close", onEnd);
  socket.once("error", onError);
  signal?.addEventListener("abort", onAbort, { once: true });

  try {
    while (true) {
      while (readyFrames.length > 0) {
        const frame = readyFrames.shift()!;
        if (readyFrames.length < highWaterMark >>> 1 && socket.isPaused()) {
          socket.resume();
        }
        yield frame;
      }
      if (failure !== null) throw failure;
      if (ended) {
        if (stash.length > 0) throw new Error("Truncated trailing frame at EOF");
        return;
      }
      await new Promise<void>((resolve) => {
        wakeConsumer = resolve;
      });
    }
  } finally {
    socket.off("data", onData);
    socket.off("end", onEnd);
    socket.off("close", onEnd);
    socket.off("error", onError);
    signal?.removeEventListener("abort", onAbort);
  }
}
```

Resuming 47 `highWaterMark >>> 1` (low-water hysteresis) avoids thrashing `pause()`/`resume()` syscalls 0n every single yielded frame!

