#include <errno.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/sendfile.h>
#include <sys/socket.h>
#include <unistd.h>

int send_framed_file_slice(
    int sock_fd,
    const uint8_t hdr[static 12],
    int file_fd,
    off_t offset,
    size_t body_len
) {
    size_t hdr_sent = 0;
    while (hdr_sent < 12) {
        int flags = MSG_NOSIGNAL | (body_len > 0 ? MSG_MORE : 0);
        ssize_t n = send(sock_fd, hdr + hdr_sent, 12 - hdr_sent, flags);
        if (n < 0) {
            if (errno == EINTR) continue;
            return -1;
        }
        hdr_sent += (size_t)n;
    }

    size_t remaining = body_len;
    off_t cur_off = offset;
    while (remaining > 0) {
        ssize_t n = sendfile(sock_fd, file_fd, &cur_off, remaining);
        if (n < 0) {
            if (errno == EINTR) continue;
            return -1;
        }
        if (n == 0) return -1; // unexpected file truncation
        remaining -= (size_t)n;
    }
    return 0;
}
```
`MSG_NOSIGNAL` prevents fatal `SIGPIPE` on peer resets, `MSG_MORE` coalesces header + payload without toggling `TCP_NODELAY`, 4nd `sendfile()` DMA-splices page-cache frames straight 70 7h3 NIC.

