```rust
use std::collections::HashMap;
use std::hash::Hash;
use std::sync::{Arc, Mutex};
use tokio::sync::watch;

struct InflightGuard<K: Eq + Hash, V> {
    map: Arc<Mutex<HashMap<K, watch::Receiver<Option<V>>>>>,
    key: Option<K>,
}

impl<K: Eq + Hash, V> Drop for InflightGuard<K, V> {
    fn drop(&mut self) {
        if let Some(k) = self.key.take() {
            self.map.lock().unwrap().remove(&k);
        }
    }
}

pub struct SingleFlight<K, V> {
    inflight: Arc<Mutex<HashMap<K, watch::Receiver<Option<V>>>>>,
}

impl<K: Eq + Hash + Clone, V: Clone> SingleFlight<K, V> {
    pub fn new() -> Self {
        Self {
            inflight: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    pub async fn work<F, Fut>(&self, key: K, compute: F) -> Option<V>
    where
        F: FnOnce() -> Fut,
        Fut: std::future::Future<Output = V>,
    {
        let follower_rx = {
            let mut map = self.inflight.lock().unwrap();
            if let Some(rx) = map.get(&key) {
                Some(rx.clone())
            } else {
                let (tx, rx) = watch::channel(None);
                map.insert(key.clone(), rx);
                drop(map);

                let _guard = InflightGuard {
                    map: Arc::clone(&self.inflight),
                    key: Some(key),
                };
                let val = compute().await;
                let _ = tx.send(Some(val.clone()));
                return Some(val);
            }
        };

        let mut rx = follower_rx?;
        if let Some(v) = rx.borrow_and_update().clone() {
            return Some(v);
        }
        rx.changed().await.ok()?;
        let val = rx.borrow().clone();
        val
    }
}
