        if self.bits_in_buf < count {
            self.refill();
            if self.bits_in_buf < count {
                return None; // truncated bitstream
            }
        }
        let out = self.bit_buf >> (64 - count);
        self.bit_buf <<= count;
        self.bits_in_buf -= count;
        Some(out)
    }
