package pipeline

import (
	"context"
	"strings"
	"sync"

	"golang.org/x/sync/errgroup"
)

func TransformStream(ctx context.Context, inputs []string, workers int) ([]string, error) {
	g, ctx := errgroup.WithContext(ctx)
	rawCh := make(chan string, 32)
	outCh := make(chan string, 32)

	// Stage 1: Single producer owns and closes rawCh
	g.Go(func() error {
		defer close(rawCh)
		for _, item := range inputs {
			select {
			case rawCh <- item:
			case <-ctx.Done():
				return ctx.Err()
			}
		}
		return nil
	})

	// Stage 2: N parallel workers; coordinator closes outCh once wg hits zero
	var wg sync.WaitGroup
	for range max(1, workers) {
		wg.Add(1)
		g.Go(func() error {
			defer wg.Done()
			for raw := range rawCh {
				clean := strings.ToUpper(strings.TrimSpace(raw))
				select {
				case outCh <- clean:
				case <-ctx.Done():
					return ctx.Err()
				}
			}
			return nil
		})
	}
	go func() {
		wg.Wait()
		close(outCh)
	}()

	// Stage 3: Sink drains outCh until closed
	var results []string
	g.Go(func() error {
		for item := range outCh {
			results = append(results, item)
		}
		return nil
	})

	if err := g.Wait(); err != nil {
		return nil, err
	}
	return results, nil
}
