export type AdjacencyGraph = ReadonlyMap<string, readonly string[]>;

export function findDependencyCycles(graph: AdjacencyGraph): string[][] {
  let nextIndex = 0;
  const indices = new Map<string, number>();
  const lowlink = new Map<string, number>();
  const onStack = new Set<string>();
  const stack: string[] = [];
  const cycles: string[][] = [];

  function strongConnect(u: string): void {
    indices.set(u, nextIndex);
    lowlink.set(u, nextIndex);
    nextIndex += 1;
    stack.push(u);
    onStack.add(u);

    const deps = graph.get(u) ?? [];
    for (const v of deps) {
      if (!indices.has(v)) {
        strongConnect(v);
        lowlink.set(u, Math.min(lowlink.get(u)!, lowlink.get(v)!));
      } else if (onStack.has(v)) {
        lowlink.set(u, Math.min(lowlink.get(u)!, indices.get(v)!));
      }
    }

    if (lowlink.get(u) === indices.get(u)) {
      const scc: string[] = [];
      while (true) {
        const w = stack.pop()!;
        onStack.delete(w);
        scc.push(w);
        if (w === u) break;
      }
      const hasSelfLoop = scc.length === 1 && deps.includes(u);
      if (scc.length > 1 || hasSelfLoop) {
        cycles.push(scc.reverse());
      }
    }
  }

  for (const pkg of graph.keys()) {
    if (!indices.has(pkg)) {
      strongConnect(pkg);
    }
  }

  return cycles;
}
