```ts
const CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";

export class MonotonicUlid {
  private lastTime = -1;
  private readonly lastRand = new Uint8Array(16); // 16 x 5-bit digits = 80 bits

  next(nowMs = Date.now()): string {
    if (!Number.isInteger(nowMs) || nowMs < 0 || nowMs > 0xffffffffffff) {
      throw new RangeError("Timestamp out of 48-bit ULID bounds");
    }

    if (nowMs === this.lastTime) {
      this.incrementRandomBase32();
    } else if (nowMs > this.lastTime) {
      this.lastTime = nowMs;
      this.seedRandomBase32();
    } else {
      // Minor backward clock skew: pin lastTime and increment random bits
      nowMs = this.lastTime;
      this.incrementRandomBase32();
    }

    return this.encodeTime(nowMs) + this.encodeRandom();
  }

  private seedRandomBase32(): void {
    const raw = new Uint8Array(10); // 80 random bits
    crypto.getRandomValues(raw);
    // Unpack 10 bytes (80 bits) into 16 5-bit values
    let buffer = 0n;
    for (let i = 0; i < 10; i++) {
      buffer = (buffer << 8n) | BigInt(raw[i]);
    }
    for (let i = 15; i >= 0; i--) {
      this.lastRand[i] = Number(buffer & 31n);
      buffer >>= 5n;
    }
  }

  private incrementRandomBase32(): void {
    for (let i = 15; i >= 0; i--) {
      if (this.lastRand[i] < 31) {
        this.lastRand[i] += 1;
        return;
      }
      this.lastRand[i] = 0;
    }
    throw new Error("80-bit ULID random overflow within 1ms");
  }

  private encodeTime(ms: number): string {
    let rem = ms;
    const chars = new Array<string>(10);
    for (let i = 9; i >= 0; i--) {
      const mod = rem % 32;
      chars[i] = CROCKFORD[mod];
      rem = (rem - mod) / 32;
    }
    return chars.join("");
  }

  private encodeRandom(): string {
    let s = "";
    for (let i = 0; i < 16; i++) s += CROCKFORD[this.lastRand[i]];
    return s;
  }
}
