```ts
export const enum WireType {
  Varint = 0,
  Fixed64 = 1,
  LengthDelimited = 2,
  Fixed32 = 5,
}

export type ProtoField =
  | { fieldNumber: number; wireType: WireType.Varint; value: bigint }
  | { fieldNumber: number; wireType: WireType.LengthDelimited; value: Uint8Array };

function writeUvarint(out: number[], n: bigint): void {
  let v = n;
  while (v >= 0x80n) {
    out.push(Number((v & 0x7fn) | 0x80n));
    v >>= 7n;
  }
  out.push(Number(v));
}

function readUvarint(buf: Uint8Array, pos: number): [bigint, number] {
  let val = 0n;
  let shift = 0n;
  let i = pos;
  while (i < buf.length) {
    const b = buf[i++];
    val |= BigInt(b & 0x7f) << shift;
    if ((b & 0x80) === 0) return [val, i];
    shift += 7n;
    if (shift > 63n) throw new RangeError("Malformed varint > 10 bytes");
  }
  throw new RangeError("Unexpected EOF in varint");
}

export function encodeProtoFields(fields: readonly ProtoField[]): Uint8Array {
  const out: number[] = [];
  for (const f of fields) {
    const tag = (BigInt(f.fieldNumber) << 3n) | BigInt(f.wireType);
    writeUvarint(out, tag);
    if (f.wireType === WireType.Varint) {
      writeUvarint(out, f.value);
    } else {
      writeUvarint(out, BigInt(f.value.byteLength));
      for (let i = 0; i < f.value.byteLength; i++) out.push(f.value[i]);
    }
  }
  return Uint8Array.from(out);
}

export function decodeProtoFields(buf: Uint8Array): ProtoField[] {
  const fields: ProtoField[] = [];
  let pos = 0;
  while (pos < buf.byteLength) {
    const [tag, afterTag] = readUvarint(buf, pos);
    pos = afterTag;
    const fieldNumber = Number(tag >> 3n);
    const wireType = Number(tag & 7n);
    if (fieldNumber <= 0) throw new Error("Invalid field number 0");

    if (wireType === WireType.Varint) {
      const [val, next] = readUvarint(buf, pos);
      pos = next;
      fields.push({ fieldNumber, wireType: WireType.Varint, value: val });
    } else if (wireType === WireType.LengthDelimited) {
