use std::collections::HashMap;
use std::hash::{BuildHasher, Hasher};
use std::collections::hash_map::RandomState;
use std::sync::Mutex;

const NS_PER_SEC: u128 = 1_000_000_000;

#[derive(Clone, Copy)]
struct Bucket {
    subtokens: u128, // scaled by NS_PER_SEC so 1 full token == 1_000_000_000 units
    last_ns: u64,
}

pub struct KeyedRateLimiter {
    rate_per_sec: u128,
    max_subtokens: u128,
    hasher: RandomState,
    shards: [Mutex<HashMap<String, Bucket>>; 16],
}

impl KeyedRateLimiter {
    pub fn new(rate_per_sec: u64, burst: u64) -> Self {
        Self {
            rate_per_sec: rate_per_sec as u128,
            max_subtokens: (burst as u128) * NS_PER_SEC,
            hasher: RandomState::new(),
            shards: std::array::from_fn(|_| Mutex::new(HashMap::new())),
        }
    }

    fn shard_idx(&self, key: &str) -> usize {
        let mut h = self.hasher.build_hasher();
        h.write(key.as_bytes());
        (h.finish() as usize) & 15
    }

    pub fn allow(&self, key: &str, now_ns: u64) -> bool {
        let mut map = self.shards[self.shard_idx(key)].lock().unwrap();
        let b = map.entry(key.to_owned()).or_insert(Bucket {
            subtokens: self.max_subtokens,
            last_ns: now_ns,
        });

        let elapsed_ns = now_ns.saturating_sub(b.last_ns) as u128;
        b.last_ns = b.last_ns.max(now_ns);
        b.subtokens = (b.subtokens + elapsed_ns * self.rate_per_sec).min(self.max_subtokens);

        if b.subtokens >= NS_PER_SEC {
            b.subtokens -= NS_PER_SEC;
            true
        } else {
            false
        }
    }

    pub fn evict_older_than(&self, cutoff_ns: u64) {
        for shard in &self.shards {
            shard.lock().unwrap().retain(|_, b| b.last_ns >= cutoff_ns);
        }
    }
}
