const std = @import("std");

pub const TlvError = error{
    TruncatedHeader,
    TruncatedValue,
};

pub const TlvRecord = struct {
    tag: u8,
    value: []const u8,
};

pub const TlvIterator = struct {
    buf: []const u8,
    pos: usize = 0,

    pub fn init(data: []const u8) TlvIterator {
        return .{ .buf = data, .pos = 0 };
    }

    pub fn next(self: *TlvIterator) TlvError!?TlvRecord {
        if (self.pos == self.buf.len) {
            return null;
        }
        if (self.buf.len - self.pos < 3) {
            return error.TruncatedHeader;
        }

