```ts
export interface DagNode<T> {
  id: string;
  deps: readonly string[]; // IDs that must finish BEFORE this node starts
  run: (results: ReadonlyMap<string, T>, signal: AbortSignal) => Promise<T>;
}

export async function executeDag<T>(
  nodes: readonly DagNode<T>[],
  maxConcurrency = 4,
): Promise<Map<string, T>> {
  const byId = new Map<string, DagNode<T>>();
  const inDegree = new Map<string, number>();
  const dependents = new Map<string, string[]>();

  for (const node of nodes) {
    if (byId.has(node.id)) throw new Error(`Duplicate node ID: ${node.id}`);
    byId.set(node.id, node);
    inDegree.set(node.id, 0);
    dependents.set(node.id, []);
  }

  for (const node of nodes) {
    const uniqueDeps = new Set(node.deps);
    inDegree.set(node.id, uniqueDeps.size);
    for (const dep of uniqueDeps) {
      const list = dependents.get(dep);
      if (!list) throw new Error(`Unknown dependency '${dep}' on '${node.id}'`);
      list.push(node.id);
    }
  }

  // Pre-flight cycle check via simulated Kahn peel before running side effects!
  const simDeg = new Map(inDegree);
  const simQueue = [...simDeg.entries()].filter(([, d]) => d === 0).map(([id]) => id);
  let visited = 0;
  while (simQueue.length > 0) {
    const id = simQueue.shift()!;
    visited += 1;
    for (const child of dependents.get(id)!) {
      const nextD = simDeg.get(child)! - 1;
      simDeg.set(child, nextD);
      if (nextD === 0) simQueue.push(child);
    }
  }
  if (visited !== nodes.length) {
    throw new Error("Cycle detected in task DAG");
  }

  if (nodes.length === 0) return new Map();

  const results = new Map<string, T>();
  const abort = new AbortController();
  const ready: string[] = [];
  for (const [id, deg] of inDegree) {
    if (deg === 0) ready.push(id);
  }

  let active = 0;
  let completed = 0;

  return new Promise<Map<string, T>>((resolve, reject) => {
    let settled = false;

    const pump = () => {
      if (settled) return;
      if (completed === nodes.length) {
        settled = true;
        resolve(results);
        return;
      }
      while (active < maxConcurrency && ready.length > 0) {
        const id = ready.shift()!;
        const node = byId.get(id)!;
        active += 1;
        node
          .run(results, abort.signal)
          .then((val) => {
            active -= 1;
            if (settled) return;
            results.set(id, val);
            completed += 1;
            for (const child of dependents.get(id)!) {
              const rem = inDegree.get(child)! - 1;
              inDegree.set(child, rem);
              if (rem === 0) ready.push(child);
            }
            pump();
          })
          .catch((err) => {
            active -= 1;
            if (settled) return;
            settled = true;
            abort.abort(err);
            reject(err);
          });
      }
    };

    pump();
  });
}
```

