import { describe, expect, it } from "vitest";

export function createNdjsonDecoder<T = unknown>(): {
  writable: WritableStream<Uint8Array>;
  readable: ReadableStream<T>;
} {
  const textDecoder = new TextDecoderStream("utf-8", { fatal: true });
  let partial = "";

  const jsonSplitter = new TransformStream<string, T>({
    transform(chunk, controller) {
      const combined = partial + chunk;
      const lines = combined.split(/\r?\n/);
      partial = lines.pop() ?? "";
      for (const line of lines) {
        if (line.trim()) controller.enqueue(JSON.parse(line) as T);
      }
    },
    flush(controller) {
      if (partial.trim()) controller.enqueue(JSON.parse(partial) as T);
      partial = "";
    },
  });

  return {
    writable: textDecoder.writable,
    readable: textDecoder.readable.pipeThrough(jsonSplitter),
  };
}

function sliceStream(raw: Uint8Array, step: number): ReadableStream<Uint8Array> {
  let pos = 0;
  return new ReadableStream<Uint8Array>({
    pull(controller) {
      if (pos >= raw.byteLength) {
        controller.close();
        return;
      }
      // Interleave occasional 0-byte empty chunks to test state resilience
      if (pos % 3 === 1 && step === 1) {
        controller.enqueue(new Uint8Array(0));
      }
      const end = Math.min(pos + step, raw.byteLength);
      controller.enqueue(raw.subarray(pos, end));
      pos = end;
    },
  });
}

describe("createNdjsonDecoder chunk-boundary resilience", () => {
  const fixtures = [
    { id: 1, note: "plain ascii" },
    { id: 2, note: "split multibyte 🚀🔥 café 日本語" },
    { id: 3, note: "trailing no-newline" },
  ];
  const wireBytes = new TextEncoder().encode(
    fixtures.map((x) => JSON.stringify(x)).join("\r\n"),
  );

  it.each([1, 2, 3, 7, 13, wireBytes.byteLength])(
    "reconstructs exact objects under %i-byte chunking",
    async (chunkSize) => {
      const { writable, readable } = createNdjsonDecoder<(typeof fixtures)[0]>();
      const out: typeof fixtures = [];

      await Promise.all([
        sliceStream(wireBytes, chunkSize).pipeTo(writable),
        (async () => {
          for await (const item of readable) out.push(item);
        })(),
      ]);

      expect(out).toEqual(fixtures);
    },
  );
});
