export type BencodeValue =
  | bigint
  | Uint8Array
  | BencodeValue[]
  | Map<string, BencodeValue>;

const enc = new TextEncoder();
const dec = new TextDecoder("utf-8", { fatal: false });

function compareBytes(a: Uint8Array, b: Uint8Array): number {
  const len = Math.min(a.length, b.length);
  for (let i = 0; i < len; i++) {
    if (a[i] !== b[i]) return a[i] - b[i];
  }
  return a.length - b.length;
}

export function encodeBencode(val: BencodeValue): Uint8Array {
  const chunks: Uint8Array[] = [];

  function write(v: BencodeValue): void {
    if (typeof v === "bigint") {
      chunks.push(enc.encode(`i${v}e`));
    } else if (v instanceof Uint8Array) {
      chunks.push(enc.encode(`${v.byteLength}:`), v);
    } else if (Array.isArray(v)) {
      chunks.push(enc.encode("l"));
      for (const item of v) write(item);
      chunks.push(enc.encode("e"));
    } else {
      chunks.push(enc.encode("d"));
      const entries = [...v.entries()].map(([k, item]) => ({
        keyBytes: enc.encode(k),
        item,
      }));
      entries.sort((a, b) => compareBytes(a.keyBytes, b.keyBytes));
      for (const { keyBytes, item } of entries) {
        chunks.push(enc.encode(`${keyBytes.byteLength}:`), keyBytes);
        write(item);
      }
      chunks.push(enc.encode("e"));
    }
  }

  write(val);
  const total = chunks.reduce((s, c) => s + c.byteLength, 0);
  const out = new Uint8Array(total);
  let off = 0;
  for (const c of chunks) {
    out.set(c, off);
    off += c.byteLength;
  }
  return out;
}

export function decodeBencode(buf: Uint8Array): BencodeValue {
  let pos = 0;

  function readValue(): BencodeValue {
    if (pos >= buf.length) throw new SyntaxError("Unexpected EOF");
    const tag = buf[pos];

    // Integer: i<digits>e
    if (tag === 0x69 /* 'i' */) {
      pos += 1;
      const end = buf.indexOf(0x65 /* 'e' */, pos);
      if (end === -1) throw new SyntaxError("Unterminated integer");
      const raw = dec.decode(buf.subarray(pos, end));
      if (!/^(?:0|-?[1-9]\d*)$/.test(raw)) {
        throw new SyntaxError(`Non-canonical Bencode integer: i${raw}e`);
      }
      pos = end + 1;
      return BigInt(raw);
    }

    // List: l<items>e
    if (tag === 0x6c /* 'l' */) {
      pos += 1;
      const list: BencodeValue[] = [];
      while (buf[pos] !== 0x65 /* 'e' */) {
        if (pos >= buf.length) throw new SyntaxError("Unterminated list");
        list.push(readValue());
      }
      pos += 1;
      return list;
    }

    // Dict: d<sorted key-value pairs>e
    if (tag === 0x64 /* 'd' */) {
      pos += 1;
      const dict = new Map<string, BencodeValue>();
      let prevKey: Uint8Array | null = null;
      while (buf[pos] !== 0x65 /* 'e' */) {
        if (pos >= buf.length) throw new SyntaxError("Unterminated dict");
        const keyBytes = readByteString();
        if (prevKey && compareBytes(prevKey, keyBytes) >= 0) {
          throw new SyntaxError("Unsorted or duplicate Bencode dict key");
        }
        prevKey = keyBytes;
        dict.set(dec.decode(keyBytes), readValue());
      }
      pos += 1;
      return dict;
    }

    return readByteString();
  }

  function readByteString(): Uint8Array {
    const colon = buf.indexOf(0x3a /* ':' */, pos);
    if (colon === -1) throw new SyntaxError("Missing ':' in byte string");
    const lenStr = dec.decode(buf.subarray(pos, colon));
    if (!/^(?:0|[1-9]\d*)$/.test(lenStr)) {
      throw new SyntaxError(`Invalid byte length: ${lenStr}`);
    }
    const len = Number(lenStr);
    const start = colon + 1;
    const end = start + len;
    if (end > buf.length) throw new RangeError("Truncated byte string");
    pos = end;
    return buf.subarray(start, end); // zero-copy slice!
  }

  const root = readValue();
  if (pos !== buf.length) throw new SyntaxError("Trailing bytes after root value");
  return root;
}
