use std::time::Duration;
use tokio::sync::mpsc;
use tokio::time::{Instant, sleep_until};

pub async fn run_batch_flusher<T, F, Fut>(
    mut rx: mpsc::Receiver<T>,
    max_batch: usize,
    max_linger: Duration,
    mut flush_fn: F,
) where
    F: FnMut(&[T]) -> Fut,
    Fut: std::future::Future<Output = ()>,
{
    let mut batch = Vec::with_capacity(max_batch);

    loop {
        // Park with zero timers while completely idle
        let Some(first) = rx.recv().await else {
            break;
        };
        batch.push(first);

        // Drain already-queued items without awaiting
        while batch.len() < max_batch {
            match rx.try_recv() {
                Ok(item) => batch.push(item),
                Err(_) => break,
            }
        }

        if batch.len() < max_batch {
            let deadline = Instant::now() + max_linger;
            loop {
                tokio::select! {
                    biased;
                    maybe_item = rx.recv() => {
                        match maybe_item {
                            Some(item) => {
                                batch.push(item);
                                if batch.len() >= max_batch {
                                    break;
                                }
                            }
                            None => {
                                flush_fn(&batch).await;
                                return;
                            }
                        }
                    }
                    _ = sleep_until(deadline) => break,
                }
            }
        }

        flush_fn(&batch).await;
        batch.clear();
    }
}
