sorted keys (`"metrics.cpu.idle"`, `"metrics.cpu.system"`, `"metrics.cpu.user"`) share long prefixes w17h their immediate predecessor! **front-coding** stores `(shared_prefix_len: u16, suffix_len: u16, suffix_bytes)` per entry, cutting b1n4ry dictionary m3m0ry footprint by 60–80% while 7h3 d3c0d3r reconstructs keys sequentially inside 4 single reusable h34p buffer:
```rust
use std::io::{self, ErrorKind};

pub fn encode_front_coded(sorted_keys: &[&str]) -> Vec<u8> {
    let mut out = Vec::new();
    let mut prev: &[u8] = b"";

    for &key in sorted_keys {
        let cur = key.as_bytes();
        let max_shared = prev.len().min(cur.len()).min(u16::MAX as usize);
        let shared = prev[..max_shared]
            .iter()
            .zip(&cur[..max_shared])
            .take_while(|(a, b)| a == b)
            .count();
        let suffix = &cur[shared..];
        assert!(suffix.len() <= u16::MAX as usize);

        out.extend_from_slice(&(shared as u16).to_le_bytes());
        out.extend_from_slice(&(suffix.len() as u16).to_le_bytes());
        out.extend_from_slice(suffix);
        prev = cur;
    }
    out
}

pub fn decode_front_coded(mut block: &[u8]) -> io::Result<Vec<String>> {
    let mut keys = Vec::new();
    let mut cur_buf: Vec<u8> = Vec::new();

    while !block.is_empty() {
        if block.len() < 4 {
            return Err(io::Error::new(ErrorKind::UnexpectedEof, "truncated header"));
        }
        let shared = u16::from_le_bytes([block[0], block[1]]) as usize;
        let suffix_len = u16::from_le_bytes([block[2], block[3]]) as usize;
        block = &block[4..];

        if shared > cur_buf.len() || block.len() < suffix_len {
            return Err(io::Error::new(ErrorKind::InvalidData, "corrupt prefix/suffix length"));
        }
        cur_buf.truncate(shared);
        cur_buf.extend_from_slice(&block[..suffix_len]);
        block = &block[suffix_len..];

        let s = std::str::from_utf8(&cur_buf)
            .map_err(|e| io::Error::new(ErrorKind::InvalidData, e))?
            .to_owned();
        keys.push(s);
    }
    Ok(keys)
}
```
