```go
package ratelimit

import (
	"context"
	"sync"
	"time"

	"golang.org/x/time/rate"
)

type visitor struct {
	limiter  *rate.Limiter
	lastSeen time.Time
}

type KeyedLimiter struct {
	mu      sync.Mutex
	rps     rate.Limit
	burst   int
	ttl     time.Duration
	clients map[string]*visitor
}

func NewKeyedLimiter(ctx context.Context, rps rate.Limit, burst int, ttl time.Duration) *KeyedLimiter {
	kl := &KeyedLimiter{
		rps:     rps,
		burst:   burst,
		ttl:     ttl,
		clients: make(map[string]*visitor),
	}
	go kl.evictLoop(ctx)
	return kl
}

func (kl *KeyedLimiter) Allow(key string) bool {
	now := time.Now()
	kl.mu.Lock()
	v, ok := kl.clients[key]
	if !ok {
		v = &visitor{limiter: rate.NewLimiter(kl.rps, kl.burst)}
		kl.clients[key] = v
	}
	v.lastSeen = now
	l := v.limiter
	kl.mu.Unlock()

	return l.AllowN(now, 1)
}

func (kl *KeyedLimiter) evictLoop(ctx context.Context) {
	ticker := time.NewTicker(kl.ttl / 2)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case now := <-ticker.C:
			kl.mu.Lock()
			for k, v := range kl.clients {
				if now.Sub(v.lastSeen) > kl.ttl {
					delete(kl.clients, k)
				}
			}
			kl.mu.Unlock()
		}
	}
}
```
