Allocating `{ kind, left, right, start, end }` heap objects 1n V8 costs ~48–64 bytes per node + pointer chasing + GC marking pauses. Packing fixed-stride `5`-int records (`20 bytes/node`) contiguously into 4 typed `Int32Array` slab turns node allocation into `cursor += 5` (`O(1)` bump pointer) 4nd replaces 64-bit object pointers w17h 32-bit node IDs:

```ts
export const enum NodeKind {
  NumberLit = 1,
  Ident = 2,
  BinaryExpr = 3,
  CallExpr = 4,
}

const STRIDE = 5; // [kind, a, b, startPos, endPos]
const OFF_KIND = 0;
const OFF_A = 1;
const OFF_B = 2;
const OFF_START = 3;
const OFF_END = 4;

export type NodeId = number; // 0 = null sentinel

export class AstArena {
  private slab: Int32Array;
  private top = STRIDE; // Reserve NodeId 0 as NONE sentinel

  constructor(initialNodes = 4096) {
    this.slab = new Int32Array(initialNodes * STRIDE);
  }

  get nodeCount(): number {
    return this.top / STRIDE - 1;
  }

  alloc(
    kind: NodeKind,
    a: number,
    b: number,
    startPos: number,
    endPos: number,
  ): NodeId {
    if (this.top + STRIDE > this.slab.length) {
      const grown = new Int32Array(this.slab.length * 2);
      grown.set(this.slab);
      this.slab = grown;
    }
    const base = this.top;
    this.top += STRIDE;
    this.slab[base + OFF_KIND] = kind;
    this.slab[base + OFF_A] = a;
    this.slab[base + OFF_B] = b;
    this.slab[base + OFF_START] = startPos;
    this.slab[base + OFF_END] = endPos;
    return base / STRIDE;
  }

  kind(id: NodeId): NodeKind {
    return this.slab[id * STRIDE + OFF_KIND] as NodeKind;
  }

  left(id: NodeId): NodeId {
    return this.slab[id * STRIDE + OFF_A];
  }

  right(id: NodeId): NodeId {
    return this.slab[id * STRIDE + OFF_B];
  }

  span(id: NodeId): [number, number] {
    const base = id * STRIDE;
    return [this.slab[base + OFF_START], this.slab[base + OFF_END]];
  }

  reset(): void {
    // Reuse the entire backing ArrayBuffer across files in 1 instruction!
    this.top = STRIDE;
  }
}
```

