```ts
import type { Redis } from "ioredis";

const TOKEN_BUCKET_LUA = `
local key = KEYS[1]
local capacity = tonumber(ARGV[1])
local refillPerSec = tonumber(ARGV[2])
local cost = tonumber(ARGV[3])

local redisTime = redis.call('TIME')
local nowMs = tonumber(redisTime[1]) * 1000 + math.floor(tonumber(redisTime[2]) / 1000)

local state = redis.call('HMGET', key, 'tokens', 'ts')
local tokens = tonumber(state[1])
local lastMs = tonumber(state[2])

if tokens == nil then
  tokens = capacity
  lastMs = nowMs
else
  local elapsedSec = math.max(0, nowMs - lastMs) / 1000.0
  tokens = math.min(capacity, tokens + elapsedSec * refillPerSec)
  lastMs = nowMs
end

local allowed = 0
local retryAfterMs = 0
if tokens >= cost then
  tokens = tokens - cost
  allowed = 1
else
  retryAfterMs = math.ceil(((cost - tokens) / refillPerSec) * 1000)
end

local ttlMs = math.max(1000, math.ceil((capacity / refillPerSec) * 1000))
redis.call('HSET', key, 'tokens', tokens, 'ts', lastMs)
redis.call('PEXPIRE', key, ttlMs)

return { allowed, math.floor(tokens), retryAfterMs }
`;

export interface RateLimitResult {
  allowed: boolean;
  remaining: number;
  retryAfterMs: number;
}

declare module "ioredis" {
  interface RedisCommander<Context> {
    takeTokens(
      key: string,
      capacity: number,
      refillPerSec: number,
      cost: number,
    ): Promise<[number, number, number]>;
  }
}

export function registerTokenBucket(redis: Redis) {
  redis.defineCommand("takeTokens", {
    numberOfKeys: 1,
    lua: TOKEN_BUCKET_LUA,
  });

  return async (
    bucketKey: string,
    capacity: number,
    refillPerSec: number,
    cost = 1,
  ): Promise<RateLimitResult> => {
    const [allowed, remaining, retryAfterMs] = await redis.takeTokens(
      `rl:${bucketKey}`,
      capacity,
      refillPerSec,
      cost,
    );
    return { allowed: allowed === 1, remaining, retryAfterMs };
  };
}
```

