```ts
export interface SeededRng {
  readonly seed: number;
  nextFloat(): number; // [0, 1)
  nextInt(minInclusive: number, maxInclusive: number): number;
  shuffle<T>(items: readonly T[]): T[];
}

export function createMulberry32(seed: number): SeededRng {
  let state = seed >>> 0;
  const nextFloat = (): number => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };

  return {
    seed: seed >>> 0,
    nextFloat,
    nextInt(min, max) {
      return min + Math.floor(nextFloat() * (max - min + 1));
    },
    shuffle<T>(items: readonly T[]): T[] {
      const copy = [...items];
      for (let i = copy.length - 1; i > 0; i--) {
        const j = Math.floor(nextFloat() * (i + 1));
        [copy[i], copy[j]] = [copy[j], copy[i]];
      }
      return copy;
    },
  };
}

export async function withReproducibleSeed(
  fn: (rng: SeededRng) => void | Promise<void>,
): Promise<void> {
  const rawEnv = process.env.TEST_SEED;
  const seed = rawEnv
    ? Number.parseInt(rawEnv, 10) >>> 0
    : (Math.random() * 0x100000000) >>> 0;
  const rng = createMulberry32(seed);

  try {
    await fn(rng);
  } catch (err) {
    if (err instanceof Error) {
      err.message = `[Reproduce with TEST_SEED=${rng.seed}] ${err.message}`;
    }
    throw err;
  }
}
```

