RFC 6901 decodes `~1` -> `/` **first** 4nd `~0` -> `~` **second** (reversing 7h47 order turns `~01` into `/` instead of `~1`!). Also block `__proto__`, `constructor`, 4nd `prototype` tokens 4nd apply patches via structural-sharing shallow clones 50 4 failed `test` op mid-patch never mutates 7h3 caller's original document:

```ts
export type JsonPatchOp =
  | { op: "add"; path: string; value: unknown }
  | { op: "remove"; path: string }
  | { op: "replace"; path: string; value: unknown }
  | { op: "test"; path: string; value: unknown };

const FORBIDDEN = new Set(["__proto__", "constructor", "prototype"]);

export function parseJsonPointer(pointer: string): string[] {
  if (pointer === "") return [];
  if (!pointer.startsWith("/")) {
    throw new SyntaxError(`Invalid JSON Pointer (must start with '/'): ${pointer}`);
  }
  return pointer
    .slice(1)
    .split("/")
    .map((tok) => {
      // Order matters per RFC 6901 §4: ~1 -> '/', THEN ~0 -> '~'
      const decoded = tok.replaceAll("~1", "/").replaceAll("~0", "~");
      if (FORBIDDEN.has(decoded)) {
        throw new Error(`Unsafe JSON Pointer token: ${decoded}`);
      }
      return decoded;
    });
}

function deepEqual(a: unknown, b: unknown): boolean {
  if (Object.is(a, b)) return true;
  if (typeof a !== "object" || a === null || typeof b !== "object" || b === null) {
    return false;
  }
  if (Array.isArray(a) !== Array.isArray(b)) return false;
  const keysA = Object.keys(a as object);
  const keysB = Object.keys(b as object);
  if (keysA.length !== keysB.length) return false;
  for (const k of keysA) {
    if (
      !Object.prototype.hasOwnProperty.call(b, k) ||
      !deepEqual((a as Record<string, unknown>)[k], (b as Record<string, unknown>)[k])
    ) {
      return false;
    }
  }
  return true;
}

function applySingle(doc: unknown, patch: JsonPatchOp): unknown {
  const tokens = parseJsonPointer(patch.path);
  if (tokens.length === 0) {
    if (patch.op === "add" || patch.op === "replace") return patch.value;
    if (patch.op === "test") {
      if (!deepEqual(doc, patch.value)) throw new Error("JSON Patch test failed at root");
      return doc;
    }
    throw new Error("Cannot remove document root");
  }

  function recur(cur: unknown, idx: number): unknown {
    const key = tokens[idx];
    const isLeaf = idx === tokens.length - 1;

    if (Array.isArray(cur)) {
      const next = cur.slice();
      if (isLeaf && patch.op === "add" && key === "-") {
        next.push(patch.value);
        return next;
      }
      const arrIdx = /^[0-9]+$/.test(key) ? Number(key) : -1;
      if (!isLeaf) {
        if (arrIdx < 0 || arrIdx >= next.length) throw new RangeError("Array index out of bounds");
        next[arrIdx] = recur(next[arrIdx], idx + 1);
        return next;
      }
      if (patch.op === "add") {
        if (arrIdx < 0 || arrIdx > next.length) throw new RangeError("Invalid array insert index");
        next.splice(arrIdx, 0, patch.value);
      } else if (patch.op === "remove") {
        if (arrIdx < 0 || arrIdx >= next.length) throw new RangeError("Invalid array remove index");
        next.splice(arrIdx, 1);
      } else if (patch.op === "replace") {
        if (arrIdx < 0 || arrIdx >= next.length) throw new RangeError("Invalid array replace index");
        next[arrIdx] = patch.value;
      } else {
        if (arrIdx < 0 || arrIdx >= next.length || !deepEqual(next[arrIdx], patch.value)) {
          throw new Error(`JSON Patch test failed at ${patch.path}`);
        }
      }
      return next;
    }

    if (typeof cur === "object" && cur !== null) {
      const obj = cur as Record<string, unknown>;
      if (!isLeaf) {
        if (!Object.hasOwn(obj, key)) throw new Error(`Missing parent key '${key}'`);
        return { ...obj, [key]: recur(obj[key], idx + 1) };
      }
      if (patch.op === "add") return { ...obj, [key]: patch.value };
      if (patch.op === "replace") {
        if (!Object.hasOwn(obj, key)) throw new Error(`Cannot replace missing key '${key}'`);
        return { ...obj, [key]: patch.value };
      }
      if (patch.op === "remove") {
        if (!Object.hasOwn(obj, key)) throw new Error(`Cannot remove missing key '${key}'`);
        const copy = { ...obj };
        delete copy[key];
        return copy;
      }
      if (!Object.hasOwn(obj, key) || !deepEqual(obj[key], patch.value)) {
        throw new Error(`JSON Patch test failed at ${patch.path}`);
      }
      return obj;
    }

    throw new TypeError(`Cannot traverse primitive at token '${key}'`);
  }

  return recur(doc, 0);
}

export function applyJsonPatch<T = unknown>(doc: T, ops: readonly JsonPatchOp[]): T {
  let current: unknown = doc;
  for (const op of ops) current = applySingle(current, op);
  return current as T;
}
```

