from collections.abc import Callable
import time
from typing import Generic, TypeVar

K = TypeVar("K")
V = TypeVar("V")


class TTLCache(Generic[K, V]):
    def __init__(self, ttl_s: float, clock: Callable[[], float] = time.monotonic) -> None:
        self._ttl_s = ttl_s
        self._clock = clock
        self._store: dict[K, tuple[float, V]] = {}

    def set(self, key: K, val: V) -> None:
        self._store[key] = (self._clock() + self._ttl_s, val)

    def get(self, key: K) -> V | None:
        entry = self._store.get(key)
        if entry is None:
            return None
        expires_at, val = entry
        if self._clock() >= expires_at:
            del self._store[key]
            return None
        return val


class FakeClock:
    def __init__(self, initial: float = 1000.0) -> None:
        self.now = initial

    def __call__(self) -> float:
        return self.now

    def advance(self, seconds: float) -> None:
        self.now += seconds


def test_ttl_expiry_boundary() -> None:
    clock = FakeClock()
    cache: TTLCache[str, int] = TTLCache(ttl_s=10.0, clock=clock)
    cache.set("tok", 42)

    clock.advance(9.999)
    assert cache.get("tok") == 42

    clock.advance(0.001)  # Exact boundary t = 1010.0 -> expired and evicted from memory!
    assert cache.get("tok") is None
    assert "tok" not in cache._store
```

