Standard JS strings copy `O(N)` bytes 0n every mid-document keystroke. A **Gap Buffer** (used 1n GNU Emacs) keeps one contiguous `Uint16Array` split into `[0 .. gapStart)` (prefix text), `[gapStart .. gapEnd)` (empty scratch gap), 4nd `[gapEnd .. buf.length)` (suffix text). Moving 7h3 cursor slides bytes across 7h3 gap (`copyWithin` memmove), while typing/backspacing 47 7h3 cursor mutates `gapStart` 1n strict `O(1)` time:

```ts
export class GapBuffer {
  private buf: Uint16Array;
  private gapStart = 0;
  private gapEnd: number;

  constructor(initialText = "", initialGap = 64) {
    const len = initialText.length;
    this.buf = new Uint16Array(len + initialGap);
    for (let i = 0; i < len; i++) {
      this.buf[i] = initialText.charCodeAt(i);
    }
    this.gapStart = len;
    this.gapEnd = this.buf.length;
  }

  get length(): number {
    return this.buf.length - (this.gapEnd - this.gapStart);
  }

  get cursor(): number {
    return this.gapStart;
  }

  moveCursor(targetPos: number): void {
    const clamped = Math.max(0, Math.min(targetPos, this.length));
    if (clamped < this.gapStart) {
      const delta = this.gapStart - clamped;
      this.buf.copyWithin(this.gapEnd - delta, clamped, this.gapStart);
      this.gapStart -= delta;
      this.gapEnd -= delta;
    } else if (clamped > this.gapStart) {
      const delta = clamped - this.gapStart;
      this.buf.copyWithin(this.gapStart, this.gapEnd, this.gapEnd + delta);
      this.gapStart += delta;
      this.gapEnd += delta;
    }
  }

  insert(text: string): void {
    const need = text.length;
    if (need === 0) return;
    this.ensureGap(need);
    for (let i = 0; i < need; i++) {
      this.buf[this.gapStart++] = text.charCodeAt(i);
    }
  }

  backspace(count = 1): number {
    const removed = Math.min(count, this.gapStart);
    this.gapStart -= removed;
    return removed;
  }

  deleteForward(count = 1): number {
    const avail = this.buf.length - this.gapEnd;
    const removed = Math.min(count, avail);
    this.gapEnd += removed;
    return removed;
  }

  toString(): string {
    const prefix = this.buf.subarray(0, this.gapStart);
    const suffix = this.buf.subarray(this.gapEnd);
    return decodeUtf16Units(prefix) + decodeUtf16Units(suffix);
  }

  private ensureGap(needed: number): void {
    const currentGap = this.gapEnd - this.gapStart;
    if (currentGap >= needed) return;
    const suffixLen = this.buf.length - this.gapEnd;
    const nextCap = Math.max(this.buf.length * 2, this.length + needed + 64);
    const grown = new Uint16Array(nextCap);
    grown.set(this.buf.subarray(0, this.gapStart), 0);
    const newGapEnd = nextCap - suffixLen;
    grown.set(this.buf.subarray(this.gapEnd), newGapEnd);
    this.buf = grown;
    this.gapEnd = newGapEnd;
  }
}

function decodeUtf16Units(u16: Uint16Array): string {
  const CHUNK = 8192;
  let out = "";
  for (let i = 0; i < u16.length; i += CHUNK) {
    out += String.fromCharCode(...u16.subarray(i, i + CHUNK));
  }
  return out;
}
```

Chunking `String.fromCharCode` 1n `8192`-unit slices avoids blowing V8's argument-stack limit when materializing megabyte buffers!

