import type { Pool } from "pg";

export interface OutboxRow {
  id: string;
  topic: string;
  aggregate_key: string;
  payload: unknown;
  attempts: number;
}

export interface BrokerPublisher {
  publishBatch(events: readonly OutboxRow[]): Promise<void>;
}

const CLAIM_SQL = `
  SELECT id, topic, aggregate_key, payload, attempts
  FROM outbox_events
  WHERE published_at IS NULL
    AND next_attempt_at <= NOW()
  ORDER BY created_at ASC
  LIMIT $1
  FOR UPDATE SKIP LOCKED
`;

export async function drainOutboxOnce(
  pool: Pool,
  broker: BrokerPublisher,
  batchSize = 100,
): Promise<number> {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    const { rows } = await client.query<OutboxRow>(CLAIM_SQL, [batchSize]);
    if (rows.length === 0) {
      await client.query("COMMIT");
      return 0;
    }

    const ids = rows.map((r) => r.id);
    try {
      await broker.publishBatch(rows);
      await client.query(
        `UPDATE outbox_events
         SET published_at = NOW()
         WHERE id = ANY($1::uuid[])`,
        [ids],
      );
    } catch (pubErr) {
      // Exponential retry schedule inside DB instead of rolling back attempts!
      await client.query(
        `UPDATE outbox_events
         SET attempts = attempts + 1,
             last_error = $2,
             next_attempt_at = NOW() + (LEAST(300, POWER(2, attempts + 1)) || ' seconds')::interval
         WHERE id = ANY($1::uuid[])`,
        [ids, pubErr instanceof Error ? pubErr.message : String(pubErr)],
      );
    }

    await client.query("COMMIT");
    return rows.length;
  } catch (err) {
    await client.query("ROLLBACK").catch(() => {});
    throw err;
  } finally {
    client.release();
  }
}
