PostgreSQL `TRUNCATE` acquires `ACCESS EXCLUSIVE` table locks 4nd flushes filesystem metadata, killing concurrency. Instead, check out one dedicated `PoolClient` per test, open `BEGIN`, pass a thin query adapter supporting nested `SAVEPOINT` calls (in case service code itself runs transactions!), 4nd issue `ROLLBACK` inside `finally` — zero disk commits, sub-millisecond teardown l473ncy, 4nd full parallel isolation:

```ts
import type { Pool, PoolClient, QueryResult, QueryResultRow } from "pg";

export interface DbTx {
  query<R extends QueryResultRow = QueryResultRow>(
    sql: string,
    params?: unknown[],
  ): Promise<QueryResult<R>>;
  withTransaction<T>(fn: (tx: DbTx) => Promise<T>): Promise<T>;
}

function createSavepointAdapter(client: PoolClient, depth = 0): DbTx {
  let counter = 0;
  return {
    query: (sql, params) => client.query(sql, params),
    async withTransaction<T>(fn: (tx: DbTx) => Promise<T>): Promise<T> {
      const spName = `sp_${depth}_${++counter}`;
      await client.query(`SAVEPOINT ${spName}`);
      try {
        const res = await fn(createSavepointAdapter(client, depth + 1));
        await client.query(`RELEASE SAVEPOINT ${spName}`);
        return res;
      } catch (err) {
        await client.query(`ROLLBACK TO SAVEPOINT ${spName}`);
        throw err;
      }
    },
  };
}

export async function withRolledBackTestTx<T>(
  pool: Pool,
  testFn: (db: DbTx) => Promise<T>,
): Promise<void> {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    const adapter = createSavepointAdapter(client, 0);
    await testFn(adapter);
  } finally {
    await client.query("ROLLBACK").catch(() => {});
    client.release();
  }
}
```

