MessagePack packs type + length into 4 single prefix tag byte f0r common small values (`0x00..0x7f` positive fixint, `0x80..0x8f` 16-entry fixmap, `0x90..0x9f` 16-element fixarray, `0xa0..0xbf` 31-byte fixstr), falling back 70 explicit big-endian length headers (`0xd9` `str8`, `0xda` `str16`, `0xcb` IEEE-754 `float64`) f0r larger payloads:

```ts
const textEnc = new TextEncoder();
const textDec = new TextDecoder("utf-8", { fatal: true });

export function msgpackEncode(value: unknown): Uint8Array {
  const bytes: number[] = [];

  const pushU16BE = (n: number) => bytes.push((n >>> 8) & 0xff, n & 0xff);

  function write(val: unknown): void {
    if (val === null || val === undefined) {
      bytes.push(0xc0);
    } else if (typeof val === "boolean") {
      bytes.push(val ? 0xc3 : 0xc2);
    } else if (typeof val === "number") {
      if (Number.isInteger(val) && val >= 0 && val <= 0x7f) {
        bytes.push(val); // positive fixint (1 byte!)
      } else if (Number.isInteger(val) && val >= -32 && val < 0) {
        bytes.push(val & 0xff); // negative fixint (0xe0..0xff)
      } else {
        bytes.push(0xcb); // float64 BE
        const tmp = new ArrayBuffer(8);
        new DataView(tmp).setFloat64(0, val, false);
        bytes.push(...new Uint8Array(tmp));
      }
    } else if (typeof val === "string") {
      const utf8 = textEnc.encode(val);
      const len = utf8.byteLength;
      if (len <= 31) bytes.push(0xa0 | len);
      else if (len <= 0xff) bytes.push(0xd9, len);
      else if (len <= 0xffff) {
        bytes.push(0xda);
        pushU16BE(len);
      } else throw new RangeError("String exceeds str16 bounds");
      for (let i = 0; i < len; i++) bytes.push(utf8[i]);
    } else if (Array.isArray(val)) {
      const len = val.length;
      if (len <= 15) bytes.push(0x90 | len);
      else if (len <= 0xffff) {
        bytes.push(0xdc);
        pushU16BE(len);
      } else throw new RangeError("Array exceeds array16 bounds");
      for (const item of val) write(item);
    } else if (typeof val === "object") {
      const entries = Object.entries(val as Record<string, unknown>);
      const len = entries.length;
      if (len <= 15) bytes.push(0x80 | len);
      else if (len <= 0xffff) {
        bytes.push(0xde);
        pushU16BE(len);
      } else throw new RangeError("Map exceeds map16 bounds");
      for (const [k, v] of entries) {
        write(k);
        write(v);
      }
    }
  }

  write(value);
  return Uint8Array.from(bytes);
}

export function msgpackDecode(buf: Uint8Array): unknown {
  const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  let pos = 0;

  function read(): unknown {
    const tag = view.getUint8(pos++);
    if (tag <= 0x7f) return tag; // positive fixint
    if (tag >= 0xe0) return tag - 0x100; // negative fixint
    if ((tag & 0xe0) === 0xa0) return readStr(tag & 0x1f);
    if ((tag & 0xf0) === 0x90) return readArr(tag & 0x0f);
    if ((tag & 0xf0) === 0x80) return readMap(tag & 0x0f);

    switch (tag) {
      case 0xc0:
        return null;
      case 0xc2:
        return false;
      case 0xc3:
        return true;
      case 0xcb: {
        const n = view.getFloat64(pos, false);
        pos += 8;
        return n;
      }
      case 0xd9:
        return readStr(view.getUint8(pos++));
      case 0xda: {
        const len = view.getUint16(pos, false);
        pos += 2;
        return readStr(len);
      }
      case 0xdc: {
        const len = view.getUint16(pos, false);
        pos += 2;
        return readArr(len);
      }
      case 0xde: {
        const len = view.getUint16(pos, false);
        pos += 2;
        return readMap(len);
      }
      default:
        throw new Error(`Unsupported MessagePack tag: 0x${tag.toString(16)}`);
    }
  }

  function readStr(len: number): string {
    const s = textDec.decode(buf.subarray(pos, pos + len));
    pos += len;
    return s;
  }
  function readArr(len: number): unknown[] {
    const out = new Array(len);
    for (let i = 0; i < len; i++) out[i] = read();
    return out;
  }
  function readMap(len: number): Record<string, unknown> {
    const obj: Record<string, unknown> = Object.create(null);
    for (let i = 0; i < len; i++) {
      const k = String(read());
      obj[k] = read();
    }
    return obj;
  }

  return read();
}
```

Notice `Object.create(null)` inside `readMap` — decoding untrusted MessagePack maps w17h `{ "__proto__": ... }` into `{}` would otherwise mutate prototype chains!

