#include <errno.h>
#include <fcntl.h>
#include <stddef.h>
#include <stdio.h>
#include <unistd.h>

int atomic_write_file_at(int dir_fd, const char *filename, const void *buf, size_t len) {
    char tmp_name[256];
    int n = snprintf(tmp_name, sizeof(tmp_name), ".%s.tmp.%d", filename, (int)getpid());
    if (n < 0 || (size_t)n >= sizeof(tmp_name)) return -1;

    int fd = openat(dir_fd, tmp_name, O_WRONLY | O_CREAT | O_EXCL | O_CLOEXEC, 0644);
    if (fd < 0) return -1;

    const unsigned char *p = (const unsigned char *)buf;
    size_t written = 0;
    while (written < len) {
        ssize_t w = write(fd, p + written, len - written);
        if (w < 0) {
            if (errno == EINTR) continue;
            close(fd);
            unlinkat(dir_fd, tmp_name, 0);
            return -1;
        }
        written += (size_t)w;
    }

    if (fdatasync(fd) < 0 || close(fd) < 0) {
        unlinkat(dir_fd, tmp_name, 0);
        return -1;
    }
    if (renameat(dir_fd, tmp_name, dir_fd, filename) < 0) {
        unlinkat(dir_fd, tmp_name, 0);
        return -1;
    }
    // Persist the updated directory entry itself!
    return fsync(dir_fd);
}
