        hasher.update(&chunk);
    }

    let digest = hasher.finalize();
    let mut hex_out = String::with_capacity(64);
    for b in digest {
        use std::fmt::Write;
        let _ = write!(&mut hex_out, "{b:02x}");
    }
    Ok(format!("bytes={total_bytes} sha256={hex_out}\n"))
}
