bool packbits_encode(
    const uint8_t *src, size_t src_len,
    uint8_t *dst, size_t dst_cap, size_t *dst_len
) {
    size_t si = 0, di = 0;
    while (si < src_len) {
        size_t run = 1;
        while (si + run < src_len && run < 128 && src[si + run] == src[si]) {
            ++run;
