type Event struct {
	ID     int64  `json:"id"`
	Action string `json:"action"`
}

func StreamJSONArray(r io.Reader, handle func(Event) error) error {
	dec := json.NewDecoder(r)

	openTok, err := dec.Token()
	if err != nil {
		return fmt.Errorf("read opening token: %w", err)
	}
	if delim, ok := openTok.(json.Delim); !ok || delim != '[' {
		return fmt.Errorf("expected '[' array start, got %v", openTok)
	}

	for dec.More() {
		var ev Event
		if err := dec.Decode(&ev); err != nil {
			return fmt.Errorf("decode element: %w", err)
		}
		if err := handle(ev); err != nil {
			return err
		}
	}

	closeTok, err := dec.Token()
	if err != nil {
		return fmt.Errorf("read closing token: %w", err)
	}
	if delim, ok := closeTok.(json.Delim); !ok || delim != ']' {
		return fmt.Errorf("expected ']' array close, got %v", closeTok)
	}
	return nil
}
