use std::sync::atomic::{fence, AtomicU64, AtomicUsize, Ordering};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ClockCalibration {
    pub base_ns: u64,
    pub tsc_offset: u64,
    pub scale_q32: u64,
