#[repr(align(64))]
pub struct CalibrationSeqLock {
    seq: AtomicUsize,
    base_ns: AtomicU64,
    tsc_offset: AtomicU64,
    scale_q32: AtomicU64,
}

impl CalibrationSeqLock {
    pub const fn new(init: ClockCalibration) -> Self {
        Self {
            seq: AtomicUsize::new(0),
            base_ns: AtomicU64::new(init.base_ns),
            tsc_offset: AtomicU64::new(init.tsc_offset),
            scale_q32: AtomicU64::new(init.scale_q32),
        }
    }

    // Single writer only
    pub fn write(&self, val: ClockCalibration) {
        let s = self.seq.load(Ordering::Relaxed);
        self.seq.store(s.wrapping_add(1), Ordering::Release);
        fence(Ordering::Release);

        self.base_ns.store(val.base_ns, Ordering::Relaxed);
        self.tsc_offset.store(val.tsc_offset, Ordering::Relaxed);
        self.scale_q32.store(val.scale_q32, Ordering::Relaxed);

        self.seq.store(s.wrapping_add(2), Ordering::Release);
    }

    pub fn read(&self) -> ClockCalibration {
        loop {
            let s1 = self.seq.load(Ordering::Acquire);
            if (s1 & 1) != 0 {
                std::hint::spin_loop();
                continue;
            }
            let out = ClockCalibration {
                base_ns: self.base_ns.load(Ordering::Relaxed),
                tsc_offset: self.tsc_offset.load(Ordering::Relaxed),
                scale_q32: self.scale_q32.load(Ordering::Relaxed),
            };
            fence(Ordering::Acquire);
            let s2 = self.seq.load(Ordering::Relaxed);
            if s1 == s2 {
                return out;
            }
        }
    }
}
