    tokio::select! {
        res = &mut primary_fut => {
            if res.is_ok() {
                return res;
            }
            // Primary failed fast -> fall through and try backup immediately
            return make_backup_fut().await;
        }
        _ = sleep(hedge_delay) => {}
    }

    // Phase 2: primary is still in flight; race primary against fresh backup
    let backup_fut = make_backup_fut();
    tokio::pin!(backup_fut);

    tokio::select! {
        res_a = &mut primary_fut => match res_a {
            Ok(val) => Ok(val),
            Err(_) => backup_fut.await,
        },
        res_b = &mut backup_fut => match res_b {
            Ok(val) => Ok(val),
            Err(_) => primary_fut.await,
        },
    }
}
