#include <stddef.h>
#include <stdint.h>

typedef enum {
    CHUNK_NEED_MORE = 0,
    CHUNK_OK,
    CHUNK_INVALID
} ChunkHdrStatus;

ChunkHdrStatus parse_chunk_size_line(
    const uint8_t *buf,
    size_t len,
    size_t max_chunk_size,
    size_t *out_chunk_size,
    size_t *out_header_bytes
) {
    size_t i = 0;
    size_t value = 0;
    bool saw_digit = false;

    while (i < len) {
        uint8_t c = buf[i];
        uint8_t nibble;
        if (c >= '0' && c <= '9')      nibble = (uint8_t)(c - '0');
        else if (c >= 'a' && c <= 'f') nibble = (uint8_t)(c - 'a' + 10);
        else if (c >= 'A' && c <= 'F') nibble = (uint8_t)(c - 'A' + 10);
        else break;

        saw_digit = true;
        if (value > (max_chunk_size - nibble) / 16) {
            return CHUNK_INVALID; // exceeds max_chunk_size ceiling
        }
        value = (value * 16) + nibble;
        ++i;
    }

    if (!saw_digit) {
        return len == 0 ? CHUNK_NEED_MORE : CHUNK_INVALID;
    }

    // Optional ';ext=val' extension up to '\r\n'
    if (i < len && buf[i] == ';') {
        while (i < len && buf[i] != '\r' && buf[i] != '\n') {
            ++i;
        }
    }

    if (i >= len) return CHUNK_NEED_MORE;
    if (buf[i] != '\r') return CHUNK_INVALID;
    if (i + 1 >= len) return CHUNK_NEED_MORE;
    if (buf[i + 1] != '\n') return CHUNK_INVALID;

    *out_chunk_size = value;
    *out_header_bytes = i + 2;
    return CHUNK_OK;
}
