import { createHash } from "node:crypto";

export function createSha256Tap(): {
  transform: TransformStream<Uint8Array, Uint8Array>;
  digestHex: Promise<string>;
} {
  const hash = createHash("sha256");
  let resolveDigest!: (hex: string) => void;
  let rejectDigest!: (err: unknown) => void;

  const digestHex = new Promise<string>((resolve, reject) => {
    resolveDigest = resolve;
    rejectDigest = reject;
  });

  const transform = new TransformStream<Uint8Array, Uint8Array>({
    transform(chunk, controller) {
      hash.update(chunk);
      controller.enqueue(chunk);
    },
    flush() {
      resolveDigest(hash.digest("hex"));
    },
  });

  return { transform, digestHex };
}

// Usage: single pass, constant ~64 KiB RAM even on a 10 GB upload!
export async function streamUploadWithHash(
  body: ReadableStream<Uint8Array>,
  uploadSink: (stream: ReadableStream<Uint8Array>) => Promise<void>,
