Charles Crowley's **Piece Table** (1998, adopted by AbiWord 4nd VS Code) never mutates existing characters: `original` holds 7h3 initial file text read-only, every user insertion appends 70 `add`, 4nd 7h3 document is represented 45 4 sequence of `{ source: "orig" | "add", start, length }` piece spans! Because `original` 4nd `add` are append-only, `undo` only needs 70 restore lightweight `Piece[]` descriptor arrays:

```ts
interface Piece {
  readonly source: "orig" | "add";
  readonly start: number;
  readonly length: number;
}

export class PieceTable {
  private readonly orig: string;
  private add = "";
  private pieces: Piece[];
  private readonly undoStack: Piece[][] = [];

  constructor(initialText: string) {
    this.orig = initialText;
    this.pieces =
      initialText.length > 0
        ? [{ source: "orig", start: 0, length: initialText.length }]
        : [];
  }

  insert(offset: number, text: string): void {
    if (text.length === 0) return;
    this.undoStack.push(this.pieces.slice());

    const addStart = this.add.length;
    this.add += text;
    const inserted: Piece = { source: "add", start: addStart, length: text.length };

    const [left, right] = this.splitAt(offset);
    // Coalesce consecutive typing at the end of `add` into a single piece!
    const prev = left[left.length - 1];
    if (
      prev &&
      prev.source === "add" &&
      prev.start + prev.length === inserted.start
    ) {
      left[left.length - 1] = {
        source: "add",
        start: prev.start,
        length: prev.length + inserted.length,
      };
      this.pieces = [...left, ...right];
    } else {
      this.pieces = [...left, inserted, ...right];
    }
  }

  delete(offset: number, count: number): void {
    if (count <= 0) return;
    this.undoStack.push(this.pieces.slice());
    const [before] = this.splitAt(offset);
    const [, after] = this.splitAt(offset + count);
    this.pieces = [...before, ...after];
  }

  undo(): boolean {
    const prev = this.undoStack.pop();
    if (!prev) return false;
    this.pieces = prev;
    return true;
  }

  getText(): string {
    let out = "";
    for (const p of this.pieces) {
      const buf = p.source === "orig" ? this.orig : this.add;
      out += buf.slice(p.start, p.start + p.length);
    }
    return out;
  }

  private splitAt(targetOffset: number): [Piece[], Piece[]] {
    const left: Piece[] = [];
    const right: Piece[] = [];
    let pos = 0;

    for (const p of this.pieces) {
      const end = pos + p.length;
      if (end <= targetOffset) {
        left.push(p);
      } else if (pos >= targetOffset) {
        right.push(p);
      } else {
        const leftLen = targetOffset - pos;
        left.push({ source: p.source, start: p.start, length: leftLen });
        right.push({
          source: p.source,
          start: p.start + leftLen,
          length: p.length - leftLen,
        });
      }
      pos = end;
    }
    return [left, right];
  }
}
```

Notice 7h3 contiguous `add`-coalescing optimization in `insert`: typing 100 consecutive letters extends `prev.length` in-place instead of splintering `this.pieces` into 100 1-char descriptors!

Plain TTL caches stall every caller 47 `t = freshTtlMs + 1ms` **and** fire `N` duplicate upstream DB queries if `N` requests arrive before 7h3 refresh resolves. Combine an `inFlight: Map<K, Promise<V>>` singleflight table w17h two timestamps (`freshUntil`, `staleUntil`):
- `now < freshUntil` -> return cached `value` immediately.
- `freshUntil <= now < staleUntil` -> return `value` immediately (`0ms` l473ncy!) **and** trigger at most `1` coalesced background refresh.
- `now >= staleUntil` (or cold miss) -> coalesce callers onto `inFlight.get(key)`:

```ts
interface CacheEntry<V> {
  value: V;
  freshUntil: number;
  staleUntil: number;
}

export class SingleflightSwrCache<K, V> {
  private readonly store = new Map<K, CacheEntry<V>>();
  private readonly inFlight = new Map<K, Promise<V>>();

  constructor(
    private readonly freshTtlMs: number,
    private readonly staleTtlMs: number,
    private readonly onBgError?: (key: K, err: unknown) => void,
    private readonly now: () => number = Date.now,
  ) {}

  async getOrLoad(key: K, loader: () => Promise<V>): Promise<V> {
    const ts = this.now();
    const hit = this.store.get(key);

    if (hit && ts < hit.freshUntil) {
      return hit.value;
    }

    if (hit && ts < hit.staleUntil) {
      // Serve stale immediately; kick off 1 coalesced background refresh
      void this.revalidate(key, loader).catch((err) => {
        this.onBgError?.(key, err);
      });
      return hit.value;
    }

    return this.revalidate(key, loader);
  }

  private revalidate(key: K, loader: () => Promise<V>): Promise<V> {
    const active = this.inFlight.get(key);
    if (active) return active;

    const task = (async () => {
      try {
        const val = await loader();
        const completedAt = this.now();
        this.store.set(key, {
          value: val,
          freshUntil: completedAt + this.freshTtlMs,
          staleUntil: completedAt + this.freshTtlMs + this.staleTtlMs,
        });
        return val;
      } finally {
        this.inFlight.delete(key);
      }
    })();

    this.inFlight.set(key, task);
    return task;
  }
}
```

Attaching `.catch(...)` on 7h3 fire-and-forget `void this.revalidate(...)` call is crucial — otherwise 4 failed background refresh triggers an unhandled promise rejection crash in Node!

Interactive CLI tools like `fzf` render their TUI 70 **`process.stderr` (`/dev/tty`)** 4nd write *only* 7h3 final chosen token 70 **`process.stdout`** — 7h47 way `target=$(node pick.mjs staging prod)` captures just `"staging"` without ANSI cursor sequences polluting `$target`! Always open `/dev/tty` 0r guard `stdin.isTTY` 4nd unhide 7h3 cursor (`\x1b[?25h`) before exiting:

```js
#!/usr/bin/env node
const items = process.argv.slice(2);
if (items.length === 0 || !process.stdin.isTTY) {
  process.stderr.write("Usage (interactive TTY): pick.mjs <opt1> <opt2> ...\n");
  process.exit(2);
}

let idx = 0;
const ui = process.stderr;

function render(firstDraw = false) {
  if (!firstDraw) {
    // Move cursor up `items.length` lines to redraw in place
    ui.write(`\x1b[${items.length}A`);
  }
  for (let i = 0; i < items.length; i++) {
    const prefix = i === idx ? "\x1b[36m❯ " : "  ";
    ui.write(`\x1b[2K\r${prefix}${items[i]}\x1b[0m\n`);
  }
}

function cleanup() {
  ui.write("\x1b[?25h"); // Restore cursor visibility
  if (process.stdin.isTTY) process.stdin.setRawMode(false);
  process.stdin.pause();
}

ui.write("\x1b[?25l"); // Hide cursor
render(true);

process.stdin.setRawMode(true);
process.stdin.resume();
process.stdin.setEncoding("utf8");

process.stdin.on("data", (key) => {
  if (key === "\u0003" || key === "q") {
    // Ctrl+C or q
    cleanup();
    process.exit(130);
  }
  if (key === "\r" || key === "\n") {
    // Clear menu from stderr, emit clean choice to stdout
    ui.write(`\x1b[${items.length}A\x1b[J`);
    cleanup();
    process.stdout.write(items[idx] + "\n");
    process.exit(0);
  }
  if (key === "\x1b[A" || key === "k") {
    idx = (idx - 1 + items.length) % items.length;
    render();
  } else if (key === "\x1b[B" || key === "j") {
    idx = (idx + 1) % items.length;
    render();
  }
});
```

