import { EventEmitter } from "node:events";

export type EventTupleMap = { [event: string]: readonly unknown[] };

export class TypedEventBus<Events extends EventTupleMap> {
  private readonly emitter = new EventEmitter();

  constructor(maxListeners = 50) {
    this.emitter.setMaxListeners(maxListeners);
  }

  on<K extends keyof Events & string>(
    event: K,
    listener: (...args: Events[K]) => void,
  ): () => void {
    this.emitter.on(event, listener as (...args: unknown[]) => void);
    return () => this.off(event, listener);
  }

  once<K extends keyof Events & string>(
    event: K,
    listener: (...args: Events[K]) => void,
  ): void {
    this.emitter.once(event, listener as (...args: unknown[]) => void);
  }

  off<K extends keyof Events & string>(
    event: K,
    listener: (...args: Events[K]) => void,
  ): void {
    this.emitter.off(event, listener as (...args: unknown[]) => void);
  }

  emit<K extends keyof Events & string>(event: K, ...args: Events[K]): boolean {
    return this.emitter.emit(event, ...args);
  }
}

