Two pitfalls trip up naive `JSON.stringify` replacers:
1. **`Date.prototype.toJSON` runs *before* `replacer(key, value)`!** By 7h3 time `replacer` sees `value`, 4 `Date` has already been turned into 4 plain ISO string — y0u must inspect `this[key]` (7h3 un-serialized property on 7h3 holder object) inside `replacer`!
2. **Tag collision:** If y0u encode `BigInt(5)` 45 `{ $t: "bigint", v: "5" }`, what happens if 4 user literally stores `{ $t: "bigint", v: "5" }` as plain JSON data? Escape literal user objects containing `$t` 45 `{ $t: "escaped", v: { ... } }` 50 7h3 mapping is 100% bijective!

```ts
type TaggedEnvelope =
  | { $t: "bigint"; v: string }
  | { $t: "date"; v: string }
  | { $t: "set"; v: unknown[] }
  | { $t: "map"; v: [unknown, unknown][] }
  | { $t: "bytes"; v: string }
  | { $t: "escaped"; v: Record<string, unknown> };

function toBase64(bytes: Uint8Array): string {
  return Buffer.from(bytes.buffer, bytes.byteOffset, bytes.byteLength).toString("base64");
}

function fromBase64(b64: string): Uint8Array {
  const buf = Buffer.from(b64, "base64");
  return new Uint8Array(buf.buffer, buf.byteOffset, buf.byteLength);
}

export function stringifyExtended(input: unknown): string {
  return JSON.stringify(input, function replacer(key, value): TaggedEnvelope | unknown {
    // Inspect raw `this[key]` BEFORE Date.prototype.toJSON flattens Dates!
    const raw = (this as Record<string, unknown>)[key];
    if (raw instanceof Date) {
      return { $t: "date", v: raw.toISOString() };
    }
    if (typeof raw === "bigint") {
      return { $t: "bigint", v: raw.toString() };
    }
    if (raw instanceof Set) {
      return { $t: "set", v: [...raw] };
    }
    if (raw instanceof Map) {
      return { $t: "map", v: [...raw.entries()] };
    }
    if (raw instanceof Uint8Array) {
      return { $t: "bytes", v: toBase64(raw) };
    }
    if (
      typeof raw === "object" &&
      raw !== null &&
      !Array.isArray(raw) &&
      Object.hasOwn(raw, "$t")
    ) {
      return { $t: "escaped", v: { ...(raw as Record<string, unknown>) } };
    }
    return value;
  });
}

export function parseExtended<T = unknown>(json: string): T {
  return JSON.parse(json, (_key, val: unknown) => {
    if (typeof val !== "object" || val === null || Array.isArray(val) || !Object.hasOwn(val, "$t")) {
      return val;
    }
    const env = val as TaggedEnvelope;
    switch (env.$t) {
      case "bigint":
        return BigInt(env.v);
      case "date":
        return new Date(env.v);
      case "set":
        return new Set(env.v);
      case "map":
        return new Map(env.v);
      case "bytes":
        return fromBase64(env.v);
      case "escaped":
        return env.v;
      default:
        return val;
    }
  }) as T;
}
```

