#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct GenKey {
    pub idx: u32,
    pub generation: u32,
}

enum Entry<T> {
    Occupied(T),
    Vacant { next_free: Option<u32> },
}

pub struct GenSlab<T> {
    slots: Vec<(u32, Entry<T>)>,
    free_head: Option<u32>,
    len: usize,
}

impl<T> GenSlab<T> {
    pub const fn new() -> Self {
        Self {
            slots: Vec::new(),
            free_head: None,
            len: 0,
        }
    }

    pub fn insert(&mut self, val: T) -> GenKey {
        self.len += 1;
        if let Some(idx) = self.free_head {
            let (generation, entry) = &mut self.slots[idx as usize];
            let Entry::Vacant { next_free } = *entry else {
                unreachable!("free_head pointed to occupied slot");
            };
            self.free_head = next_free;
            *entry = Entry::Occupied(val);
            GenKey { idx, generation: *generation }
        } else {
            let idx = u32::try_from(self.slots.len()).expect("slab capacity overflow");
            self.slots.push((0, Entry::Occupied(val)));
            GenKey { idx, generation: 0 }
        }
    }

    pub fn get(&self, key: GenKey) -> Option<&T> {
        let (cur_gen, entry) = self.slots.get(key.idx as usize)?;
        if *cur_gen != key.generation {
            return None;
        }
        match entry {
            Entry::Occupied(v) => Some(v),
            Entry::Vacant { .. } => None,
        }
    }

    pub fn remove(&mut self, key: GenKey) -> Option<T> {
        let (cur_gen, entry) = self.slots.get_mut(key.idx as usize)?;
        if *cur_gen != key.generation || matches!(entry, Entry::Vacant { .. }) {
            return None;
        }
        *cur_gen = cur_gen.wrapping_add(1);
        let old = std::mem::replace(entry, Entry::Vacant { next_free: self.free_head });
        self.free_head = Some(key.idx);
        self.len -= 1;
        match old {
            Entry::Occupied(v) => Some(v),
            Entry::Vacant { .. } => unreachable!(),
        }
    }
}
