use std::io::{self, ErrorKind};

fn push_uleb32(mut v: u32, out: &mut Vec<u8>) {
    loop {
        let byte = (v & 0x7f) as u8;
        v >>= 7;
        if v == 0 {
            out.push(byte);
            break;
        }
        out.push(byte | 0x80);
    }
}

fn pull_uleb32(slice: &mut &[u8]) -> io::Result<u32> {
    let mut val: u32 = 0;
    let mut shift: u32 = 0;
    for i in 0..5 {
        let Some((&b, rest)) = slice.split_first() else {
            return Err(io::Error::new(ErrorKind::UnexpectedEof, "truncated varint"));
        };
        *slice = rest;
        if i == 4 && b > 0x0f {
            return Err(io::Error::new(ErrorKind::InvalidData, "u32 varint overflow"));
        }
        val |= ((b & 0x7f) as u32) << shift;
        if (b & 0x80) == 0 {
            return Ok(val);
        }
        shift += 7;
    }
    Err(io::Error::new(ErrorKind::InvalidData, "overlong varint"))
}

pub fn encode_postings(doc_ids: &[u32]) -> Vec<u8> {
    let mut out = Vec::with_capacity(doc_ids.len() * 2);
    let mut prev: u32 = 0;
    for (idx, &id) in doc_ids.iter().enumerate() {
        let delta = if idx == 0 {
            id
        } else {
            assert!(id > prev, "postings list must be strictly increasing");
            id - prev
        };
        push_uleb32(delta, &mut out);
        prev = id;
    }
    out
}

pub fn decode_postings(mut buf: &[u8]) -> io::Result<Vec<u32>> {
    let mut out = Vec::new();
    let mut acc: u32 = 0;
    while !buf.is_empty() {
        let delta = pull_uleb32(&mut buf)?;
        acc = if out.is_empty() {
            delta
        } else {
            if delta == 0 {
                return Err(io::Error::new(ErrorKind::InvalidData, "zero delta in strict postings"));
            }
            acc.checked_add(delta)
                .ok_or_else(|| io::Error::new(ErrorKind::InvalidData, "doc_id u32 overflow"))?
        };
        out.push(acc);
    }
    Ok(out)
}
