```ts
interface RadixNode<H> {
  prefix: string;
  staticChildren: Map<string, RadixNode<H>>; // keyed by first char of child.prefix
  paramChild: { name: string; node: RadixNode<H> } | null;
  wildcardChild: { name: string; handler: H } | null;
  handler: H | null;
}

function makeNode<H>(prefix = ""): RadixNode<H> {
  return {
    prefix,
    staticChildren: new Map(),
    paramChild: null,
    wildcardChild: null,
    handler: null,
  };
}

function longestCommonPrefix(a: string, b: string): number {
  const max = Math.min(a.length, b.length);
  let i = 0;
  while (i < max && a.charCodeAt(i) === b.charCodeAt(i)) i++;
  return i;
}

export class RadixRouter<H> {
  private readonly root = makeNode<H>();

  insert(path: string, handler: H): void {
    let cur = this.root;
    let i = 0;

    while (i < path.length) {
      const ch = path[i];
      if (ch === ":") {
        const slash = path.indexOf("/", i);
        const end = slash === -1 ? path.length : slash;
        const name = path.slice(i + 1, end);
        if (!cur.paramChild) {
          cur.paramChild = { name, node: makeNode() };
        }
        cur = cur.paramChild.node;
        i = end;
        continue;
      }
      if (ch === "*") {
        cur.wildcardChild = { name: path.slice(i + 1), handler };
        return;
      }

      const specialIdx = path.slice(i).search(/[:*]/);
      const staticSeg = specialIdx === -1 ? path.slice(i) : path.slice(i, i + specialIdx);
      i += staticSeg.length;
      cur = this.insertStatic(cur, staticSeg);
    }
    cur.handler = handler;
  }

  match(path: string): { handler: H; params: Record<string, string> } | null {
    const params: Record<string, string> = {};
    const found = this.search(this.root, path, 0, params);
    return found ? { handler: found, params } : null;
  }

  private insertStatic(node: RadixNode<H>, seg: string): RadixNode<H> {
    let rem = seg;
    let cur = node;
    while (rem.length > 0) {
      const child = cur.staticChildren.get(rem[0]);
      if (!child) {
        const leaf = makeNode<H>(rem);
        cur.staticChildren.set(rem[0], leaf);
        return leaf;
      }
      const lcp = longestCommonPrefix(rem, child.prefix);
      if (lcp < child.prefix.length) {
        // Split existing edge at divergence point
        const split = makeNode<H>(child.prefix.slice(0, lcp));
        child.prefix = child.prefix.slice(lcp);
        split.staticChildren.set(child.prefix[0], child);
        cur.staticChildren.set(split.prefix[0], split);
        cur = split;
      } else {
        cur = child;
      }
      rem = rem.slice(lcp);
    }
    return cur;
  }

  private search(
    node: RadixNode<H>,
    path: string,
    pos: number,
    params: Record<string, string>,
  ): H | null {
    if (pos === path.length) {
      if (node.handler !== null) return node.handler;
      if (node.wildcardChild) {
        params[node.wildcardChild.name] = "";
        return node.wildcardChild.handler;
      }
      return null;
    }

    // 1. Prefer exact static edge first
    const stat = node.staticChildren.get(path[pos]);
    if (stat && path.startsWith(stat.prefix, pos)) {
      const hit = this.search(stat, path, pos + stat.prefix.length, params);
      if (hit !== null) return hit;
    }

    // 2. Backtrack to :param segment
    if (node.paramChild) {
      const slash = path.indexOf("/", pos);
      const end = slash === -1 ? path.length : slash;
      if (end > pos) {
        const val = path.slice(pos, end);
        params[node.paramChild.name] = val;
        const hit = this.search(node.paramChild.node, path, end, params);
        if (hit !== null) return hit;
        delete params[node.paramChild.name];
      }
    }

    // 3. Fallback to *wildcard catch-all
    if (node.wildcardChild) {
      params[node.wildcardChild.name] = path.slice(pos);
      return node.wildcardChild.handler;
    }
    return null;
  }
}
```

