import { z } from "zod";
import type { Pool } from "pg";

const CursorPayloadSchema = z.object({
  ts: z.string().datetime(),
  id: z.string().uuid(),
});

export type CursorPayload = z.infer<typeof CursorPayloadSchema>;

export function encodeCursor(payload: CursorPayload): string {
  return Buffer.from(JSON.stringify(payload), "utf8").toString("base64url");
}

export function decodeCursor(token: string): CursorPayload {
  let raw: unknown;
  try {
    raw = JSON.parse(Buffer.from(token, "base64url").toString("utf8"));
  } catch {
    throw new Error("Malformed pagination cursor");
  }
  return CursorPayloadSchema.parse(raw);
}

export interface EventRecord {
  id: string;
  created_at: Date;
  action: string;
}

export async function listEventsKeyset(
  pool: Pool,
  options: { limit?: number; after?: string },
): Promise<{ items: EventRecord[]; nextCursor: string | null }> {
  const limit = Math.min(Math.max(options.limit ?? 50, 1), 200);
  const fetchCount = limit + 1;

  let rows: EventRecord[];
  if (!options.after) {
    const res = await pool.query<EventRecord>(
      `SELECT id, created_at, action
       FROM events
       ORDER BY created_at DESC, id DESC
       LIMIT $1`,
      [fetchCount],
    );
    rows = res.rows;
  } else {
    const cursor = decodeCursor(options.after);
    const res = await pool.query<EventRecord>(
      `SELECT id, created_at, action
       FROM events
       WHERE (created_at, id) < ($1::timestamptz, $2::uuid)
       ORDER BY created_at DESC, id DESC
       LIMIT $3`,
      [cursor.ts, cursor.id, fetchCount],
    );
    rows = res.rows;
  }

  const hasMore = rows.length > limit;
  const items = hasMore ? rows.slice(0, limit) : rows;
  const tail = items[items.length - 1];

  return {
    items,
    nextCursor:
      hasMore && tail
        ? encodeCursor({ ts: tail.created_at.toISOString(), id: tail.id })
        : null,
  };
}
