```ts
export type RespValue =
  | { type: "simple"; value: string }
  | { type: "error"; message: string }
  | { type: "int"; value: bigint }
  | { type: "bulk"; bytes: Uint8Array | null }
  | { type: "array"; items: RespValue[] | null };

const textDec = new TextDecoder();

function findCrlf(buf: Uint8Array, from: number): number {
  for (let i = from; i + 1 < buf.length; i++) {
    if (buf[i] === 0x0d && buf[i + 1] === 0x0a) return i;
  }
  return -1;
}

export function tryParseRespFrame(
  buf: Uint8Array,
  offset = 0,
): { frame: RespValue; nextOffset: number } | null {
  if (offset >= buf.length) return null;
  const prefix = buf[offset];
  const lineEnd = findCrlf(buf, offset + 1);
  if (lineEnd === -1) return null; // Need more bytes for header line

  const headerText = textDec.decode(buf.subarray(offset + 1, lineEnd));
  let cursor = lineEnd + 2;

  switch (prefix) {
    case 0x2b: // '+' Simple String
      return { frame: { type: "simple", value: headerText }, nextOffset: cursor };
    case 0x2d: // '-' Error
      return { frame: { type: "error", message: headerText }, nextOffset: cursor };
    case 0x3a: // ':' Integer
      return { frame: { type: "int", value: BigInt(headerText) }, nextOffset: cursor };
    case 0x24: { // '$' Bulk String
      const len = Number.parseInt(headerText, 10);
      if (len === -1) {
        return { frame: { type: "bulk", bytes: null }, nextOffset: cursor };
      }
      if (len < 0 || !Number.isInteger(len)) {
