```ts
export class IndexedMinHeap<K> {
  private readonly keys: K[] = [];
  private readonly priorities: number[] = [];
  private readonly pos = new Map<K, number>();

  get size(): number {
    return this.keys.length;
  }

  has(key: K): boolean {
    return this.pos.has(key);
  }

  peek(): { key: K; priority: number } | undefined {
    if (this.keys.length === 0) return undefined;
    return { key: this.keys[0], priority: this.priorities[0] };
  }

  upsert(key: K, priority: number): void {
    const existing = this.pos.get(key);
    if (existing !== undefined) {
      const old = this.priorities[existing];
      this.priorities[existing] = priority;
      if (priority < old) this.siftUp(existing);
      else if (priority > old) this.siftDown(existing);
      return;
    }
    const idx = this.keys.length;
    this.keys.push(key);
    this.priorities.push(priority);
    this.pos.set(key, idx);
    this.siftUp(idx);
  }

  popMin(): { key: K; priority: number } | undefined {
    const n = this.keys.length;
    if (n === 0) return undefined;
    const minKey = this.keys[0];
    const minPri = this.priorities[0];
    this.removeAt(0);
    return { key: minKey, priority: minPri };
  }

  delete(key: K): boolean {
    const idx = this.pos.get(key);
    if (idx === undefined) return false;
    this.removeAt(idx);
    return true;
  }

  private removeAt(idx: number): void {
    const last = this.keys.length - 1;
    const removedKey = this.keys[idx];
    if (idx !== last) {
      this.swap(idx, last);
    }
    this.keys.pop();
    this.priorities.pop();
    this.pos.delete(removedKey);
    if (idx < this.keys.length) {
      // Moved tail element could be smaller OR larger than local parent/children!
      this.siftUp(idx);
      this.siftDown(this.pos.get(this.keys[idx]) ?? idx);
    }
  }

  private siftUp(i: number): void {
    let cur = i;
    while (cur > 0) {
      const parent = (cur - 1) >>> 1;
      if (this.priorities[cur] >= this.priorities[parent]) break;
      this.swap(cur, parent);
      cur = parent;
    }
  }

  private siftDown(i: number): void {
    let cur = i;
    const n = this.keys.length;
    while (true) {
      const left = cur * 2 + 1;
      const right = left + 1;
      let smallest = cur;
      if (left < n && this.priorities[left] < this.priorities[smallest]) smallest = left;
      if (right < n && this.priorities[right] < this.priorities[smallest]) smallest = right;
      if (smallest === cur) break;
      this.swap(cur, smallest);
      cur = smallest;
    }
  }

  private swap(i: number, j: number): void {
    const ki = this.keys[i];
    const kj = this.keys[j];
    this.keys[i] = kj;
    this.keys[j] = ki;
    const pi = this.priorities[i];
    this.priorities[i] = this.priorities[j];
    this.priorities[j] = pi;
    this.pos.set(kj, i);
    this.pos.set(ki, j);
  }
}
```

