export function createByteLimitTransform(
  maxBytes: number,
): TransformStream<Uint8Array, Uint8Array> {
  let seenBytes = 0;
  return new TransformStream<Uint8Array, Uint8Array>({
    transform(chunk, controller) {
      seenBytes += chunk.byteLength;
      if (seenBytes > maxBytes) {
        controller.error(new PayloadTooLargeError(maxBytes));
        return;
      }
      controller.enqueue(chunk);
    },
  });
}

export async function streamBoundedUpload(
  req: Request,
  maxBytes: number,
  sink: WritableStream<Uint8Array>,
): Promise<void> {
  const declared = req.headers.get("content-length");
  if (declared !== null) {
    const len = Number.parseInt(declared, 10);
    if (Number.isFinite(len) && len > maxBytes) {
      throw new PayloadTooLargeError(maxBytes);
    }
  }
  if (!req.body) {
    throw new Error("Missing request body stream");
  }

  await req.body
    .pipeThrough(createByteLimitTransform(maxBytes))
    .pipeTo(sink);
}
