export function decodeStrictUtf8(bytes: Uint8Array): number[] {
  const codePoints: number[] = [];
  let i = 0;
  const len = bytes.byteLength;

  const readCont = (pos: number): number => {
    if (pos >= len) throw new TypeError("Truncated UTF-8 sequence");
    const b = bytes[pos];
    if ((b & 0xc0) !== 0x80) {
      throw new TypeError(`Invalid UTF-8 continuation byte 0x${b.toString(16)} at ${pos}`);
