    return b & 0x3f;
  };

  while (i < len) {
    const b0 = bytes[i];

    // 1-byte ASCII: 0x00..0x7F
    if (b0 <= 0x7f) {
      codePoints.push(b0);
      i += 1;
      continue;
    }

    // 2-byte: 0xC2..0xDF (0xC0 and 0xC1 are ALWAYS overlong ASCII!)
    if (b0 >= 0xc2 && b0 <= 0xdf) {
      const c1 = readCont(i + 1);
      codePoints.push(((b0 & 0x1f) << 6) | c1);
      i += 2;
      continue;
    }

    // 3-byte: 0xE0..0xEF
    if (b0 >= 0xe0 && b0 <= 0xef) {
      const c1 = readCont(i + 1);
      const c2 = readCont(i + 2);
