```rust
use std::sync::Mutex;
use std::time::{Duration, Instant};

#[derive(Debug)]
enum State {
    Closed { consecutive_failures: u32 },
    Open { opened_at: Instant },
    HalfOpen { probe_in_flight: bool },
}

pub struct CircuitBreaker {
    failure_threshold: u32,
    open_cooldown: Duration,
    state: Mutex<State>,
}

impl CircuitBreaker {
    pub fn new(failure_threshold: u32, open_cooldown: Duration) -> Self {
        Self {
            failure_threshold: failure_threshold.max(1),
            open_cooldown,
            state: Mutex::new(State::Closed { consecutive_failures: 0 }),
        }
    }

    pub fn allow_request(&self) -> bool {
        let mut st = self.state.lock().unwrap();
        match *st {
            State::Closed { .. } => true,
            State::Open { opened_at } => {
                if opened_at.elapsed() >= self.open_cooldown {
                    *st = State::HalfOpen { probe_in_flight: true };
                    true // grant the single canary probe permit!
                } else {
                    false
                }
            }
            State::HalfOpen { ref mut probe_in_flight } => {
                if !*probe_in_flight {
                    *probe_in_flight = true;
                    true
                } else {
                    false // sibling callers fast-fail while canary is in flight
                }
            }
        }
    }

    pub fn record_success(&self) {
        let mut st = self.state.lock().unwrap();
        *st = State::Closed { consecutive_failures: 0 };
    }

    pub fn record_failure(&self) {
        let mut st = self.state.lock().unwrap();
        match *st {
            State::Closed { consecutive_failures } => {
                let next = consecutive_failures + 1;
                if next >= self.failure_threshold {
                    *st = State::Open { opened_at: Instant::now() };
                } else {
                    *st = State::Closed { consecutive_failures: next };
                }
            }
            State::HalfOpen { .. } | State::Open { .. } => {
                *st = State::Open { opened_at: Instant::now() };
            }
        }
    }
}
```
