```rust
use std::io::{self, ErrorKind};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum WireType {
    Varint = 0,
    Fixed64 = 1,
    LengthDelimited = 2,
    Fixed32 = 5,
}

pub fn read_varint(buf: &mut &[u8]) -> io::Result<u64> {
    let mut out = 0u64;
    for shift in (0..64).step_by(7) {
        let Some((&b, rest)) = buf.split_first() else {
            return Err(io::Error::new(ErrorKind::UnexpectedEof, "truncated varint"));
        };
        *buf = rest;
        if shift == 63 && b > 0x01 {
            return Err(io::Error::new(ErrorKind::InvalidData, "varint overflow"));
        }
        out |= ((b & 0x7f) as u64) << shift;
        if (b & 0x80) == 0 {
            return Ok(out);
        }
    }
    Err(io::Error::new(ErrorKind::InvalidData, "overlong varint"))
}

pub fn read_tag(buf: &mut &[u8]) -> io::Result<(u32, WireType)> {
    let raw = read_varint(buf)?;
    let field_num = u32::try_from(raw >> 3)
        .map_err(|_| io::Error::new(ErrorKind::InvalidData, "field_num overflow"))?;
    if field_num == 0 {
        return Err(io::Error::new(ErrorKind::InvalidData, "field number 0 is illegal"));
    }
    let wt = match raw & 0x07 {
        0 => WireType::Varint,
        1 => WireType::Fixed64,
        2 => WireType::LengthDelimited,
        5 => WireType::Fixed32,
        _ => return Err(io::Error::new(ErrorKind::InvalidData, "unsupported wire type")),
    };
    Ok((field_num, wt))
}

pub fn skip_unknown_field(wt: WireType, buf: &mut &[u8]) -> io::Result<()> {
    let skip_bytes = match wt {
        WireType::Varint => {
            let _ = read_varint(buf)?;
            0
        }
        WireType::Fixed64 => 8,
        WireType::Fixed32 => 4,
        WireType::LengthDelimited => usize::try_from(read_varint(buf)?)
            .map_err(|_| io::Error::new(ErrorKind::InvalidData, "length overflow"))?,
    };
    if buf.len() < skip_bytes {
        return Err(io::Error::new(ErrorKind::UnexpectedEof, "truncated field payload"));
    }
    *buf = &buf[skip_bytes..];
    Ok(())
}
```
