pub struct BloomBuilder {
    k_probes: u8,
    bits: Vec<u8>, // starts with 5-byte header: b"BLM1" + k_probes
}

pub struct BloomView<'a> {
    k_probes: u8,
    bit_bytes: &'a [u8],
}

fn hash64_splitmix(data: &[u8]) -> (u32, u32) {
    let mut h: u64 = 0x9e3779b97f4a7c15 ^ (data.len() as u64);
    for &b in data {
        h ^= b as u64;
        h = (h ^ (h >> 30)).wrapping_mul(0xbf58476d1ce4e5b9);
    }
    h = (h ^ (h >> 27)).wrapping_mul(0x94d049bb133111eb);
    h ^= h >> 31;
    (h as u32, (h >> 32) as u32 | 1)
}

impl BloomBuilder {
    pub fn with_byte_size(bit_array_bytes: usize, k_probes: u8) -> Self {
        let len = bit_array_bytes.max(8);
        let mut bits = vec![0u8; 5 + len];
        bits[0..4].copy_from_slice(b"BLM1");
        bits[4] = k_probes.max(1);
        Self { k_probes: k_probes.max(1), bits }
    }

    pub fn insert(&mut self, key: &[u8]) {
        let payload = &mut self.bits[5..];
        let num_bits = (payload.len() * 8) as u64;
        let (h1, h2) = hash64_splitmix(key);
        for i in 0..self.k_probes as u32 {
            let bit_idx = (h1.wrapping_add(i.wrapping_mul(h2)) as u64 % num_bits) as usize;
            payload[bit_idx >> 3] |= 1u8 << (bit_idx & 7);
        }
    }

    pub fn into_bytes(self) -> Vec<u8> {
        self.bits
    }
}

impl<'a> BloomView<'a> {
    pub fn from_bytes(raw: &'a [u8]) -> Option<Self> {
        if raw.len() < 13 || &raw[0..4] != b"BLM1" || raw[4] == 0 {
            return None;
        }
        Some(Self { k_probes: raw[4], bit_bytes: &raw[5..] })
    }

    pub fn might_contain(&self, key: &[u8]) -> bool {
        let num_bits = (self.bit_bytes.len() * 8) as u64;
        let (h1, h2) = hash64_splitmix(key);
        for i in 0..self.k_probes as u32 {
            let bit_idx = (h1.wrapping_add(i.wrapping_mul(h2)) as u64 % num_bits) as usize;
            if (self.bit_bytes[bit_idx >> 3] & (1u8 << (bit_idx & 7))) == 0 {
                return false;
            }
        }
        true
    }
}
