```ts
export function safeJsonLogLine(record: Record<string, unknown>): string {
  const ancestors: object[] = [];

  return (
    JSON.stringify(record, function replacer(_key, value: unknown) {
      if (typeof value === "bigint") {
        return value.toString();
      }
      if (typeof value !== "object" || value === null) {
        return value;
      }

      // Track active ancestor chain ONLY (allows shared DAG references, blocks true cycles!)
      while (ancestors.length > 0 && ancestors[ancestors.length - 1] !== this) {
        ancestors.pop();
      }
      if (ancestors.includes(value)) {
        return "[Circular]";
      }
      ancestors.push(value);

      if (value instanceof Error) {
        const serialized: Record<string, unknown> = {
          name: value.name,
          message: value.message,
          stack: value.stack,
        };
        if (value.cause !== undefined) serialized.cause = value.cause;
        for (const [k, v] of Object.entries(value)) serialized[k] = v;
        return serialized;
      }
      if (value instanceof Map) return Object.fromEntries(value);
      if (value instanceof Set) return [...value];
      return value;
    }) + "\n"
  );
}
```

