```ts
import { createServer, type IncomingMessage, type ServerResponse } from "node:http";

export function startDrainableServer(
  handler: (req: IncomingMessage, res: ServerResponse) => void,
  port: number,
  drainTimeoutMs = 15_000,
) {
  let shuttingDown = false;

  const server = createServer((req, res) => {
    if (req.url === "/readyz") {
      res.writeHead(shuttingDown ? 503 : 200);
      res.end(shuttingDown ? "draining" : "ready");
      return;
    }
    if (shuttingDown && !res.headersSent) {
      res.setHeader("Connection", "close");
    }
    handler(req, res);
  });

  // Keep server keepAliveTimeout LARGER than ALB/Nginx idle timeout (e.g. 60s)!
  server.keepAliveTimeout = 65_000;
  server.headersTimeout = 66_000;
  server.listen(port);

  const shutdown = (): Promise<void> => {
    if (shuttingDown) return Promise.resolve();
    shuttingDown = true;

    return new Promise<void>((resolve) => {
      const hardTimer = setTimeout(() => {
        server.closeAllConnections();
        resolve();
      }, drainTimeoutMs);
      hardTimer.unref();

      server.close(() => {
        clearTimeout(hardTimer);
        resolve();
      });
      server.closeIdleConnections();
    });
  };

  return { server, shutdown };
}
```

