import { describe, expect, it } from "vitest";

export interface SourceSpan {
  start: number; // 0-based index inclusive
  end: number;   // 0-based index exclusive
}

export function formatSpanDiagnostic(
  source: string,
  span: SourceSpan,
  message: string,
): string {
  const lines = source.split("\n");
  let offset = 0;
  for (let lineIdx = 0; lineIdx < lines.length; lineIdx++) {
    const line = lines[lineIdx];
    const lineEnd = offset + line.length;
    if (span.start <= lineEnd) {
      const col = span.start - offset;
      const width = Math.max(1, Math.min(line.length - col, span.end - span.start));
      const gutter = `${lineIdx + 1} | `;
      const underline = " ".repeat(gutter.length + col) + "^" + "~".repeat(width - 1);
      return [
        `error: ${message} (line ${lineIdx + 1}, col ${col + 1})`,
        `${gutter}${line}`,
        `${underline}`,
      ].join("\n");
    }
    offset = lineEnd + 1;
  }
  return `error: ${message} at EOF`;
}

