    const rendered = formatSpanDiagnostic(
      src,
      { start: slashIdx, end: slashIdx + 1 },
      "Unexpected prefix operator '/'",
    );

    expect(rendered).toMatchInlineSnapshot(`
      "error: Unexpected prefix operator '/' (line 2, col 22)
      2 | let ratio = limit ** / 2;
                               ^"
