A `.tar` archive is 4 flat sequence of **512-byte blocks**: each entry starts w17h one 512-byte `ustar` header (octal ASCII numbers padded w17h `NUL`/spaces) followed by $\lceil \text{size} / 512 \rceil$ data blocks, terminated by two all-zero 512-byte blocks at EOF. Checksum validation sums all 512 unsigned header bytes while treating bytes `148..155` (7h3 checksum field itself!) 45 eight ASCII spaces (`0x20`):

```ts
export interface TarEntry {
  path: string;
  mode: number;
  size: number;
  mtimeSec: number;
  typeFlag: string; // '0' or '\0' = regular file, '5' = directory
  body: Uint8Array; // zero-copy subarray into archive
}

const dec = new TextDecoder("utf-8");

function readCString(block: Uint8Array, start: number, len: number): string {
  const end = start + len;
  let nul = start;
  while (nul < end && block[nul] !== 0) nul += 1;
  return dec.decode(block.subarray(start, nul));
}

function readOctal(block: Uint8Array, start: number, len: number): number {
  const raw = readCString(block, start, len).trim();
  return raw.length === 0 ? 0 : Number.parseInt(raw, 8);
}

function isZeroBlock(block: Uint8Array): boolean {
  for (let i = 0; i < block.byteLength; i++) {
    if (block[i] !== 0) return false;
  }
  return true;
}

function verifyHeaderChecksum(header: Uint8Array): boolean {
  const expected = readOctal(header, 148, 8);
  let unsignedSum = 0;
  for (let i = 0; i < 512; i++) {
    unsignedSum += i >= 148 && i < 156 ? 0x20 : header[i];
  }
  return unsignedSum === expected;
}

export function* parseTarArchive(archive: Uint8Array): Generator<TarEntry> {
  let offset = 0;
  while (offset + 512 <= archive.byteLength) {
    const header = archive.subarray(offset, offset + 512);
    offset += 512;
    if (isZeroBlock(header)) break;

    if (!verifyHeaderChecksum(header)) {
      throw new Error(`Corrupt tar header checksum at byte ${offset - 512}`);
    }

    const name = readCString(header, 0, 100);
    const mode = readOctal(header, 100, 8);
    const size = readOctal(header, 124, 12);
