use bytes::Bytes;
use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

#[derive(Clone, Debug)]
pub struct CachedReply {
    pub status: u16,
    pub body: Bytes,
}

enum EntryState {
    InFlight { started_at: Instant },
    Completed { reply: CachedReply, expires_at: Instant },
}

pub enum ClaimOutcome {
    Proceed(InFlightGuard),
    Replay(CachedReply),
    ConcurrentInFlight,
}

pub struct IdempotencyStore {
    ttl: Duration,
    inner: Arc<Mutex<HashMap<(u64, String), EntryState>>>,
}

pub struct InFlightGuard {
    key: Option<(u64, String)>,
    ttl: Duration,
    inner: Arc<Mutex<HashMap<(u64, String), EntryState>>>,
}

impl InFlightGuard {
    pub fn commit(mut self, reply: CachedReply) {
        if let Some(k) = self.key.take() {
            let expires_at = Instant::now() + self.ttl;
            self.inner
                .lock()
                .unwrap()
                .insert(k, EntryState::Completed { reply, expires_at });
        }
    }
}

impl Drop for InFlightGuard {
    fn drop(&mut self) {
        if let Some(k) = self.key.take() {
            self.inner.lock().unwrap().remove(&k);
        }
    }
}

impl IdempotencyStore {
    pub fn new(ttl: Duration) -> Self {
        Self { ttl, inner: Arc::new(Mutex::new(HashMap::new())) }
    }

    pub fn claim(&self, tenant_id: u64, idem_key: &str) -> ClaimOutcome {
        let now = Instant::now();
        let full_key = (tenant_id, idem_key.to_owned());
        let mut map = self.inner.lock().unwrap();

        match map.get(&full_key) {
            Some(EntryState::Completed { reply, expires_at }) if *expires_at > now => {
                return ClaimOutcome::Replay(reply.clone());
            }
            Some(EntryState::InFlight { started_at })
                if now.duration_since(*started_at) < Duration::from_secs(30) =>
            {
                return ClaimOutcome::ConcurrentInFlight;
            }
            _ => {}
        }

        map.insert(full_key.clone(), EntryState::InFlight { started_at: now });
        ClaimOutcome::Proceed(InFlightGuard {
            key: Some(full_key),
            ttl: self.ttl,
            inner: Arc::clone(&self.inner),
        })
    }
}
