use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
use std::sync::Arc;

pub struct DropTracker {
    live: AtomicUsize,
    total_dropped: AtomicUsize,
}

impl DropTracker {
    pub fn new() -> Arc<Self> {
        Arc::new(Self {
            live: AtomicUsize::new(0),
            total_dropped: AtomicUsize::new(0),
        })
    }
    pub fn live_count(&self) -> usize { self.live.load(Ordering::SeqCst) }
    pub fn dropped_count(&self) -> usize { self.total_dropped.load(Ordering::SeqCst) }
}

pub struct DropSpy {
    pub id: u32,
    tracker: Arc<DropTracker>,
    alive: AtomicBool,
}

impl DropSpy {
    pub fn new(id: u32, tracker: &Arc<DropTracker>) -> Self {
        tracker.live.fetch_add(1, Ordering::SeqCst);
        Self {
            id,
            tracker: Arc::clone(tracker),
            alive: AtomicBool::new(true),
        }
    }
}

impl Drop for DropSpy {
