        assert!(was_alive, "DOUBLE DROP detected on DropSpy id={}", self.id);
        self.tracker.live.fetch_sub(1, Ordering::SeqCst);
        self.tracker.total_dropped.fetch_add(1, Ordering::SeqCst);
    }
}

