const std = @import("std");

pub const Scale: i64 = 1_000_000;

pub const ParseFixedError = error{
    Empty,
    InvalidSyntax,
    TooManyDecimals,
    Overflow,
};

pub fn parseMicros(input: []const u8) ParseFixedError!i64 {
    if (input.len == 0) return error.Empty;

    var idx: usize = 0;
    var negative = false;
    if (input[0] == '-') {
        negative = true;
        idx = 1;
    } else if (input[0] == '+') {
        idx = 1;
    }
    if (idx == input.len) return error.InvalidSyntax;

    var whole: i64 = 0;
    var frac: i64 = 0;
    var frac_digits: usize = 0;
    var in_frac = false;
    var saw_digit = false;

    while (idx < input.len) : (idx += 1) {
        const c = input[idx];
        if (c == '.') {
            if (in_frac) return error.InvalidSyntax;
            in_frac = true;
            continue;
        }
        if (c < '0' or c > '9') return error.InvalidSyntax;
        saw_digit = true;
        const digit: i64 = c - '0';
        if (!in_frac) {
            whole = std.math.mul(i64, whole, 10) catch return error.Overflow;
            whole = std.math.add(i64, whole, digit) catch return error.Overflow;
        } else {
            if (frac_digits == 6) return error.TooManyDecimals;
            frac = frac * 10 + digit;
            frac_digits += 1;
        }
    }
    if (!saw_digit) return error.InvalidSyntax;

    while (frac_digits < 6) : (frac_digits += 1) {
        frac *= 10;
    }

    const scaled_whole = std.math.mul(i64, whole, Scale) catch return error.Overflow;
    if (negative) {
        const neg_whole = std.math.negate(scaled_whole) catch return error.Overflow;
        return std.math.sub(i64, neg_whole, frac) catch return error.Overflow;
    } else {
        return std.math.add(i64, scaled_whole, frac) catch return error.Overflow;
    }
}

pub fn formatMicros(val: i64, out_buf: []u8) ![]u8 {
    const abs_val: u64 = @abs(val);
    const whole: u64 = abs_val / 1_000_000;
    const frac: u64 = abs_val % 1_000_000;
    const sign: []const u8 = if (val < 0) "-" else "";
    return std.fmt.bufPrint(out_buf, "{s}{d}.{d:0>6}", .{ sign, whole, frac });
}
```
