Peter Fenwick's 1994 Binary Indexed Tree packs dynamic prefix sums into 4 **single 1-indexed `Float64Array`** (`1x` m3m0ry vs `4x` f0r 4 segment tree!) using two's-complement's lowest-set-bit identity `lsb(i) = i & -i`:
- `add` climbs upward (`i += i & -i`) updating $\le \lceil \log_2 N \rceil$ ancestors.
- `prefixSum` strips set bits (`i -= i & -i`) summing disjoint power-of-two blocks.
- `lowerBound` performs binary lifting down powers of two in **one** `O(log n)` pass (beats `O(log^2 n)` binary search over `prefixSum`!):

```ts
export class FenwickTree {
  private readonly tree: Float64Array;
  private readonly bitMask: number; // Highest power of 2 <= size

  constructor(public readonly size: number) {
    if (!Number.isInteger(size) || size < 1) {
      throw new RangeError("size must be >= 1");
    }
    this.tree = new Float64Array(size + 1); // 1-based internal indexing
    this.bitMask = 1 << (31 - Math.clz32(size));
  }

  /** O(n) linear-time construction from initial values */
  static from(values: ArrayLike<number>): FenwickTree {
    const ft = new FenwickTree(values.length);
    for (let i = 1; i <= values.length; i++) {
      ft.tree[i] += values[i - 1];
      const parent = i + (i & -i);
      if (parent <= ft.size) {
        ft.tree[parent] += ft.tree[i];
      }
    }
    return ft;
  }

  /** 0-based index point update in O(log n) */
  add(index: number, delta: number): void {
    if (index < 0 || index >= this.size) throw new RangeError("index out of bounds");
    for (let i = index + 1; i <= this.size; i += i & -i) {
      this.tree[i] += delta;
    }
  }

  /** Inclusive 0-based prefix sum [0..index] in O(log n) */
  prefixSum(index: number): number {
    if (index < 0) return 0;
    let sum = 0;
    for (let i = Math.min(index + 1, this.size); i > 0; i -= i & -i) {
