  /** Inclusive 0-based range sum [left..right] in O(log n) */
  rangeSum(left: number, right: number): number {
    if (right < left) return 0;
    return this.prefixSum(right) - this.prefixSum(left - 1);
  }

  /** Smallest 0-based index where prefixSum(idx) >= target (for non-negative weights) */
  lowerBound(target: number): number {
    let pos = 0;
    let rem = target;
    for (let step = this.bitMask; step > 0; step >>>= 1) {
      const next = pos + step;
      if (next <= this.size && this.tree[next] < rem) {
        rem -= this.tree[next];
        pos = next;
      }
    }
    return pos; // returns `this.size` if total sum < target
