import { createHash } from "node:crypto";
import type { MiddlewareHandler } from "hono";

type IdemRecord =
  | { state: "in_progress"; fingerprint: string; expiresAt: number }
  | {
      state: "completed";
      fingerprint: string;
      status: number;
      contentType: string;
      body: string;
      expiresAt: number;
    };

export interface IdempotencyStore {
  tryAcquire(key: string, fingerprint: string, ttlMs: number): Promise<
    | { acquired: true }
    | { acquired: false; existing: IdemRecord }
  >;
  complete(
    key: string,
    snap: Omit<Extract<IdemRecord, { state: "completed" }>, "state">,
  ): Promise<void>;
  release(key: string): Promise<void>;
}

export function idempotencyMiddleware(
  store: IdempotencyStore,
  ttlMs = 24 * 60 * 60 * 1000,
): MiddlewareHandler {
  return async (c, next) => {
    if (c.req.method !== "POST" && c.req.method !== "PATCH") {
      return next();
    }
    const idemKey = c.req.header("Idempotency-Key");
    if (!idemKey) return next();

    // Clone raw body so downstream route handlers can still read c.req.json()!
    const rawBody = await c.req.raw.clone().text();
    const fingerprint = createHash("sha256")
      .update(`${c.req.method}:${c.req.path}:${rawBody}`)
      .digest("hex");

    const claim = await store.tryAcquire(idemKey, fingerprint, 30_000);
    if (!claim.acquired) {
      const prev = claim.existing;
      if (prev.fingerprint !== fingerprint) {
        return c.json(
          { error: "Idempotency-Key reused with different request parameters" },
          422,
        );
      }
      if (prev.state === "in_progress") {
        c.header("Retry-After", "1");
        return c.json({ error: "Request with this Idempotency-Key is in flight" }, 409);
      }
      c.header("Idempotent-Replayed", "true");
      return c.body(prev.body, prev.status as 200, {
        "Content-Type": prev.contentType,
      });
    }

    try {
      await next();
      // Only cache deterministic 2xx/4xx outcomes; release lock on 5xx so retries can succeed!
      if (c.res.status >= 500) {
        await store.release(idemKey);
        return;
      }
      const resClone = c.res.clone();
      const bodyText = await resClone.text();
      await store.complete(idemKey, {
        fingerprint,
        status: c.res.status,
        contentType: c.res.headers.get("content-type") ?? "application/json",
        body: bodyText,
        expiresAt: Date.now() + ttlMs,
      });
    } catch (err) {
      await store.release(idemKey);
      throw err;
    }
  };
}
```

