  flags: Record<string, string | boolean>;
  positionals: string[];
  passthrough: string[];
}

export interface FlagSpec {
  booleans?: ReadonlySet<string>;
  aliases?: Readonly<Record<string, string>>; // e.g. { v: "verbose", o: "out" }
}

export function parseCliArgs(
  argv: readonly string[],
  spec: FlagSpec = {},
): ParsedCli {
  const bools = spec.booleans ?? new Set<string>();
  const aliases = spec.aliases ?? {};
  const canonical = (k: string) => aliases[k] ?? k;

