        if (!bools.has(key) && isLast && i + 1 < argv.length && !argv[i + 1].startsWith("-")) {
          flags[key] = argv[++i];
        } else {
          flags[key] = true;
        }
      }
      continue;
    }

    positionals.push(arg);
  }

