import fc from "fast-check";
import { describe, expect, it } from "vitest";

export type Expr =
  | { kind: "lit"; val: number }
  | { kind: "var"; name: "x" | "y" }
  | { kind: "add"; left: Expr; right: Expr }
  | { kind: "mul"; left: Expr; right: Expr };

export function evalExpr(e: Expr, env: { x: number; y: number }): number {
  switch (e.kind) {
    case "lit":
      return e.val;
    case "var":
      return env[e.name];
    case "add":
      return (evalExpr(e.left, env) + evalExpr(e.right, env)) | 0;
    case "mul":
      return Math.imul(evalExpr(e.left, env), evalExpr(e.right, env));
  }
}

export function foldConstants(e: Expr): Expr {
  if (e.kind === "lit" || e.kind === "var") return e;
  const left = foldConstants(e.left);
  const right = foldConstants(e.right);
  if (left.kind === "lit" && right.kind === "lit") {
    const val =
      e.kind === "add" ? (left.val + right.val) | 0 : Math.imul(left.val, right.val);
    return { kind: "lit", val };
  }
  // Algebraic identities: x + 0 -> x, x * 1 -> x
  if (e.kind === "add" && right.kind === "lit" && right.val === 0) return left;
  if (e.kind === "mul" && right.kind === "lit" && right.val === 1) return left;
  return { kind: e.kind, left, right };
}

describe("foldConstants algebraic & constant-folding soundness", () => {
  const depthId = fc.createDepthIdentifier();
  const { expr } = fc.letrec((tie) => ({
    leaf: fc.oneof(
      fc.integer({ min: -100, max: 100 }).map((val): Expr => ({ kind: "lit", val })),
      fc.constantFrom<"x" | "y">("x", "y").map((name): Expr => ({ kind: "var", name })),
    ),
    node: fc.record({
      kind: fc.constantFrom<"add" | "mul">("add", "mul"),
      left: tie("expr") as fc.Arbitrary<Expr>,
      right: tie("expr") as fc.Arbitrary<Expr>,
    }),
    expr: fc.oneof({ depthIdentifier: depthId, maxDepth: 5 }, tie("leaf"), tie("node")),
  }));

  it("preserves 32-bit integer evaluation semantics for all trees and environments", () => {
    const envArb = fc.record({
      x: fc.integer({ min: -100, max: 100 }),
      y: fc.integer({ min: -100, max: 100 }),
    });

    fc.assert(
      fc.property(expr as fc.Arbitrary<Expr>, envArb, (ast, env) => {
        const optimized = foldConstants(ast);
        expect(evalExpr(optimized, env)).toBe(evalExpr(ast, env));
      }),
      { numRuns: 1000 },
