export function levenshteinDistance(a: string, b: string): number {
  if (a === b) return 0;
  // Ensure `short` is the shorter string so space is strictly O(min(a.length, b.length))
  const [short, long] = a.length <= b.length ? [a, b] : [b, a];
  const m = short.length;
  const n = long.length;
  if (m === 0) return n;

  const row = new Int32Array(m + 1);
  for (let j = 0; j <= m; j++) row[j] = j;

  for (let i = 1; i <= n; i++) {
    let prevDiag = row[0];
    row[0] = i;
    const longCode = long.charCodeAt(i - 1);

    for (let j = 1; j <= m; j++) {
      const savedUp = row[j];
      const substCost = longCode === short.charCodeAt(j - 1) ? 0 : 1;
      const del = row[j] + 1;
      const ins = row[j - 1] + 1;
      const sub = prevDiag + substCost;
      row[j] = del < ins ? (del < sub ? del : sub) : ins < sub ? ins : sub;
      prevDiag = savedUp;
    }
  }

  return row[m];
}
