  const hours = parseField(fields[1], 0, 23);
  const doms = parseField(fields[2], 1, 31);
  const months = parseField(fields[3], 1, 12);
  const dows = parseField(fields[4], 0, 7, true);
  const domWild = fields[2] === "*";
  const dowWild = fields[4] === "*";

  const dayMatches = (d: Date): boolean => {
    const domOk = doms.has(d.getUTCDate());
    const dowOk = dows.has(d.getUTCDay());
    // Vixie cron standard: if BOTH dom and dow are restricted, match EITHER (union)!
    if (!domWild && !dowWild) return domOk || dowOk;
    return domOk && dowOk;
  };

  return {
    nextRunAfter(from: Date): Date {
      const cur = new Date(from.getTime());
      cur.setUTCSeconds(0, 0);
      cur.setUTCMinutes(cur.getUTCMinutes() + 1);

      const maxYear = cur.getUTCFullYear() + 5;
      while (cur.getUTCFullYear() <= maxYear) {
        if (!months.has(cur.getUTCMonth() + 1)) {
          cur.setUTCMonth(cur.getUTCMonth() + 1, 1);
          cur.setUTCHours(0, 0, 0, 0);
          continue;
