#[derive(Debug, PartialEq, Eq)]
pub enum WalRead<'a> {
    Record {
        rec_type: u8,
        payload: &'a [u8],
        consumed: usize,
    },
    EndOfPreallocatedLog,
    TornOrCorrupt,
