    let payload = &buf[WAL_HDR_LEN..WAL_HDR_LEN + len];
    let mut hasher = crc32fast::Hasher::new();
    hasher.update(&[rec_type]);
    hasher.update(payload);
    if hasher.finalize() != expected_crc {
        return WalRead::TornOrCorrupt;
    }

    WalRead::Record {
        rec_type,
        payload,
        consumed: WAL_HDR_LEN + len,
    }
}
