```ts
// Deterministic 256-entry 32-bit pseudo-random Gear lookup table (SplitMix32)
const GEAR_TABLE = (() => {
  const table = new Uint32Array(256);
  let s = 0x9e3779b9;
  for (let i = 0; i < 256; i++) {
    s = (s + 0x9e3779b9) | 0;
    let z = s;
    z = Math.imul(z ^ (z >>> 16), 0x85ebca6b);
    z = Math.imul(z ^ (z >>> 13), 0xc2b2ae35);
    table[i] = (z ^ (z >>> 16)) >>> 0;
  }
  return table;
})();

export interface ChunkSlice {
  offset: number;
  length: number;
  data: Uint8Array;
}

export function* chunkContentDefined(
  buf: Uint8Array,
  minSize = 4096,     // 4 KiB minimum (skip rolling hash in [0..minSize-32))
  maskBits = 14,      // 2^14 = 16 KiB expected average window
  maxSize = 65536,    // 64 KiB hard cap (handles all-zero runs!)
): Generator<ChunkSlice> {
  // Place mask bits in MSBs because `(fp << 1) + G[b]` mixes entropy upward!
  const mask = (((1 << maskBits) - 1) << (32 - maskBits)) >>> 0;
  let start = 0;
  const total = buf.byteLength;

  while (start < total) {
    const remaining = total - start;
    if (remaining <= minSize) {
      yield { offset: start, length: remaining, data: buf.subarray(start, total) };
      return;
    }

    const hardEnd = Math.min(total, start + maxSize);
    // Fast-skip to `minSize - 32` before warming the 32-byte Gear window!
    let pos = start + Math.max(0, minSize - 32);
    const cutFloor = start + minSize;
    let fp = 0;

    while (pos < hardEnd) {
      fp = (((fp << 1) + GEAR_TABLE[buf[pos]]) >>> 0);
      pos += 1;
      if (pos >= cutFloor && (fp & mask) === 0) {
        break;
      }
    }

    const len = pos - start;
    yield { offset: start, length: len, data: buf.subarray(start, pos) };
    start = pos;
  }
}
```

