```ts
type BreakerPhase = "closed" | "open" | "half_open";

interface EndpointBreaker {
  phase: BreakerPhase;
  consecutiveFailures: number;
  openUntilMs: number;
  probeInFlight: boolean;
}

export class WebhookCircuitDispatcher {
  private readonly breakers = new Map<string, EndpointBreaker>();
  private activeGlobal = 0;
  private readonly waiters: Array<() => void> = [];

  constructor(
    private readonly maxGlobalConcurrency = 32,
    private readonly failureThreshold = 5,
    private readonly cooldownMs = 30_000,
    private readonly timeoutMs = 5_000,
    private readonly now: () => number = Date.now,
  ) {}

  async dispatch(
    endpointId: string,
    url: string,
    payload: string,
  ): Promise<{ delivered: boolean; reason?: string }> {
    const breaker = this.getBreaker(endpointId);
    const ts = this.now();

    if (breaker.phase === "open") {
      if (ts < breaker.openUntilMs) {
        return { delivered: false, reason: "circuit_open" };
      }
      breaker.phase = "half_open";
      breaker.probeInFlight = false;
    }

    if (breaker.phase === "half_open") {
      if (breaker.probeInFlight) {
        return { delivered: false, reason: "half_open_probe_busy" };
      }
      breaker.probeInFlight = true;
    }

    await this.acquireSlot();
    try {
      const res = await fetch(url, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: payload,
        signal: AbortSignal.timeout(this.timeoutMs),
      });
      if (res.status >= 500 || res.status === 429) {
        throw new Error(`Upstream HTTP ${res.status}`);
      }
      // Success -> close circuit & reset failure streak
      breaker.phase = "closed";
      breaker.consecutiveFailures = 0;
      breaker.probeInFlight = false;
      return { delivered: true };
    } catch (err) {
      breaker.consecutiveFailures += 1;
      breaker.probeInFlight = false;
      if (
        breaker.phase === "half_open" ||
        breaker.consecutiveFailures >= this.failureThreshold
      ) {
        breaker.phase = "open";
        breaker.openUntilMs = this.now() + this.cooldownMs;
      }
      return {
        delivered: false,
        reason: err instanceof Error ? err.message : "network_error",
      };
    } finally {
      this.releaseSlot();
    }
  }

  private getBreaker(id: string): EndpointBreaker {
    let b = this.breakers.get(id);
    if (!b) {
      b = { phase: "closed", consecutiveFailures: 0, openUntilMs: 0, probeInFlight: false };
      this.breakers.set(id, b);
    }
    return b;
  }

  private acquireSlot(): Promise<void> {
    if (this.activeGlobal < this.maxGlobalConcurrency) {
      this.activeGlobal += 1;
      return Promise.resolve();
    }
    return new Promise((resolve) => this.waiters.push(resolve));
  }

  private releaseSlot(): void {
    const next = this.waiters.shift();
    if (next) next();
    else this.activeGlobal -= 1;
  }
}
```

