export type SExpr =
  | { kind: "num"; value: number; start: number; end: number }
  | { kind: "str"; value: string; start: number; end: number }
  | { kind: "sym"; name: string; start: number; end: number }
  | { kind: "list"; items: SExpr[]; start: number; end: number };

export function parseSExpressions(src: string): SExpr[] {
  const roots: SExpr[] = [];
  const stack: Array<{ start: number; items: SExpr[] }> = [];
  let i = 0;
  const n = src.length;

  const emit = (node: SExpr) => {
    if (stack.length > 0) stack[stack.length - 1].items.push(node);
    else roots.push(node);
  };

  while (i < n) {
    const ch = src[i];
    if (/\s/.test(ch)) {
      i += 1;
      continue;
    }
    if (ch === ";") {
      while (i < n && src[i] !== "\n") i += 1;
      continue;
    }
    if (ch === "(") {
      stack.push({ start: i, items: [] });
      i += 1;
      continue;
    }
    if (ch === ")") {
      const frame = stack.pop();
      if (!frame) throw new SyntaxError(`Unmatched ')' at offset ${i}`);
      i += 1;
      emit({ kind: "list", items: frame.items, start: frame.start, end: i });
      continue;
    }
    if (ch === '"') {
      const start = i++;
      let val = "";
      while (i < n && src[i] !== '"') {
        if (src[i] === "\\") {
          i += 1;
          if (i >= n) throw new SyntaxError(`Unterminated escape at ${start}`);
          const esc = src[i++];
          val += esc === "n" ? "\n" : esc === "t" ? "\t" : esc;
        } else {
          val += src[i++];
        }
      }
      if (i >= n) throw new SyntaxError(`Unterminated string starting at ${start}`);
      i += 1; // closing quote
      emit({ kind: "str", value: val, start, end: i });
      continue;
    }

    // Atom: number or symbol
    const start = i;
    while (i < n && !/[\s();"]/.test(src[i])) i += 1;
    const raw = src.slice(start, i);
    if (/^-?(?:0|[1-9]\d*)(?:\.\d+)?$/.test(raw)) {
      emit({ kind: "num", value: Number(raw), start, end: i });
    } else {
      emit({ kind: "sym", name: raw, start, end: i });
    }
  }

  if (stack.length > 0) {
    const unclosed = stack[stack.length - 1];
    throw new SyntaxError(`Unclosed '(' opened at offset ${unclosed.start}`);
  }
  return roots;
}
```

