```rust
use std::collections::HashMap;
use std::hash::Hash;

struct Node<K, V> {
    prev: u32,
    next: u32,
    kv: Option<(K, V)>,
}

pub struct IndexLruCache<K, V> {
    cap: usize,
    map: HashMap<K, u32>,
    nodes: Vec<Node<K, V>>, // index 0 is the circular sentinel!
}

impl<K: Eq + Hash + Clone, V> IndexLruCache<K, V> {
    pub fn with_capacity(cap: usize) -> Self {
        assert!(cap > 0 && cap < u32::MAX as usize);
        let mut nodes = Vec::with_capacity(cap + 1);
        nodes.push(Node { prev: 0, next: 0, kv: None }); // circular sentinel
        Self {
            cap,
            map: HashMap::with_capacity(cap),
            nodes,
        }
    }

    #[inline]
    fn detach(&mut self, idx: u32) {
        let prev = self.nodes[idx as usize].prev;
        let next = self.nodes[idx as usize].next;
        self.nodes[prev as usize].next = next;
        self.nodes[next as usize].prev = prev;
    }

    #[inline]
    fn attach_mru(&mut self, idx: u32) {
        let old_first = self.nodes[0].next;
        self.nodes[idx as usize].prev = 0;
        self.nodes[idx as usize].next = old_first;
        self.nodes[0].next = idx;
        self.nodes[old_first as usize].prev = idx;
    }

    pub fn get(&mut self, key: &K) -> Option<&V> {
        let idx = *self.map.get(key)?;
        self.detach(idx);
        self.attach_mru(idx);
        self.nodes[idx as usize].kv.as_ref().map(|(_, v)| v)
    }

    pub fn put(&mut self, key: K, val: V) {
        if let Some(&idx) = self.map.get(&key) {
            self.nodes[idx as usize].kv = Some((key, val));
            self.detach(idx);
            self.attach_mru(idx);
            return;
        }

        let slot = if self.map.len() < self.cap {
            let idx = self.nodes.len() as u32;
            self.nodes.push(Node { prev: 0, next: 0, kv: None });
            idx
        } else {
            let lru_idx = self.nodes[0].prev; // sentinel.prev is always LRU!
            self.detach(lru_idx);
            if let Some((old_k, _)) = self.nodes[lru_idx as usize].kv.take() {
                self.map.remove(&old_k);
            }
            lru_idx
        };

        self.map.insert(key.clone(), slot);
        self.nodes[slot as usize].kv = Some((key, val));
        self.attach_mru(slot);
    }
}
```
