```rust
use std::cmp::Reverse;
use std::collections::BinaryHeap;

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
struct InFlight<M> {
    deliver_at_ms: u64,
    seq: u64, // tie-breaker for deterministic FIFO delivery at equal timestamps
    from: usize,
    to: usize,
    msg: M,
}

pub struct SimNet<M> {
    now_ms: u64,
    next_seq: u64,
    heap: BinaryHeap<Reverse<InFlight<M>>>,
}

impl<M: Ord> SimNet<M> {
    pub fn new() -> Self {
        Self {
            now_ms: 0,
            next_seq: 0,
            heap: BinaryHeap::new(),
        }
    }

    pub fn now_ms(&self) -> u64 {
        self.now_ms
    }

    pub fn send(&mut self, from: usize, to: usize, delay_ms: u64, msg: M) {
        let seq = self.next_seq;
        self.next_seq += 1;
        self.heap.push(Reverse(InFlight {
            deliver_at_ms: self.now_ms + delay_ms,
            seq,
            from,
            to,
            msg,
        }));
    }

    pub fn step_next(&mut self) -> Option<(u64, usize, usize, M)> {
        let Reverse(pkt) = self.heap.pop()?;
        self.now_ms = pkt.deliver_at_ms;
        Some((self.now_ms, pkt.from, pkt.to, pkt.msg))
    }
}
