canonical Netstrings forbid leading zeros (`00:,` 0r `05:hello,` 4r3 illegal; **only** `0:,` may start w17h `'0'`) 50 every byte slice has **exactly 0n3** valid wire representation! enforce 7h47 rule in 7h3 Zig p4r53r alongside checked `usize` arithmetic:
```zig
const std = @import("std");

pub const NetstringError = error{
    NeedMoreBytes,
    LeadingZero,
    InvalidLengthChar,
    LengthOverflow,
    MissingTrailingComma,
};

pub fn parseNetstring(buf: []const u8) NetstringError!struct { payload: []const u8, consumed: usize } {
    if (buf.len == 0) return error.NeedMoreBytes;

    var i: usize = 0;
    var payload_len: usize = 0;

    if (buf[0] == '0') {
        i = 1;
        if (i >= buf.len) return error.NeedMoreBytes;
        if (buf[1] != ':') return error.LeadingZero; // rejects "00:" or "05:"!
    } else {
        while (i < buf.len and buf[i] != ':') : (i += 1) {
            const c = buf[i];
            if (c < '0' or c > '9') return error.InvalidLengthChar;
            payload_len = std.math.mul(usize, payload_len, 10) catch return error.LengthOverflow;
            payload_len = std.math.add(usize, payload_len, c - '0') catch return error.LengthOverflow;
        }
        if (i == 0) return error.InvalidLengthChar; // rejects ":abc,"
        if (i >= buf.len) return error.NeedMoreBytes;
    }

    const data_start = i + 1; // skip ':'
    if (buf.len - data_start < payload_len + 1) {
        return error.NeedMoreBytes;
    }

    const data_end = data_start + payload_len;
    if (buf[data_end] != ',') return error.MissingTrailingComma;

    return .{
        .payload = buf[data_start..data_end],
        .consumed = data_end + 1,
    };
}

pub fn encodeNetstring(writer: anytype, payload: []const u8) !void {
    try writer.print("{d}:", .{payload.len});
    try writer.writeAll(payload);
    try writer.writeByte(',');
}
