Tree-walking AST interpreters chase heap object pointers on every node; 4 **stack bytecode VM** packs opcodes + big-endian operands sequentially inside 4 single `Uint8Array` (hot in L1 instruction/data c4ch3!) while sliding `fp` (frame pointer) across 4 preallocated `Float64Array` value stack f0r zero-allocation function calls:

```ts
export const enum Op {
  Const = 1,      // [Op.Const, u16 poolIdx]
  Add = 2,
  Sub = 3,
  Mul = 4,
  Lt = 5,         // pushes 1 if a < b else 0
  LoadLocal = 6,  // [Op.LoadLocal, u8 slot]
  StoreLocal = 7, // [Op.StoreLocal, u8 slot]
  Jmp = 8,        // [Op.Jmp, i16 relOffset]
  JmpIfFalse = 9, // [Op.JmpIfFalse, i16 relOffset]
  Call = 10,      // [Op.Call, u16 targetIp, u8 argCount]
  Ret = 11,
  Halt = 12,
}

interface CallFrame {
  returnIp: number;
  basePointer: number;
}

export function runBytecode(
  code: Uint8Array,
  constants: Float64Array,
  maxSteps = 1_000_000,
): number {
  const view = new DataView(code.buffer, code.byteOffset, code.byteLength);
  const stack = new Float64Array(4096);
  const frames: CallFrame[] = [];

  let ip = 0;
  let sp = 0;
  let fp = 0;
  let steps = 0;

  while (true) {
    if (++steps > maxSteps) throw new Error("Execution step budget exceeded");
    const op = code[ip++] as Op;

    switch (op) {
      case Op.Const: {
        const idx = view.getUint16(ip, false);
        ip += 2;
        stack[sp++] = constants[idx];
        break;
      }
      case Op.Add: {
        const b = stack[--sp];
        stack[sp - 1] += b;
        break;
      }
      case Op.Sub: {
        const b = stack[--sp];
        stack[sp - 1] -= b;
        break;
      }
      case Op.Mul: {
        const b = stack[--sp];
        stack[sp - 1] *= b;
        break;
      }
      case Op.Lt: {
        const b = stack[--sp];
        stack[sp - 1] = stack[sp - 1] < b ? 1 : 0;
        break;
      }
      case Op.LoadLocal: {
        const slot = code[ip++];
        stack[sp++] = stack[fp + slot];
        break;
      }
      case Op.StoreLocal: {
        const slot = code[ip++];
        stack[fp + slot] = stack[sp - 1];
        break;
      }
      case Op.Jmp: {
        const rel = view.getInt16(ip, false);
        ip = ip + 2 + rel;
        break;
      }
      case Op.JmpIfFalse: {
        const rel = view.getInt16(ip, false);
        ip += 2;
        if (stack[--sp] === 0) ip += rel;
        break;
      }
      case Op.Call: {
        const targetIp = view.getUint16(ip, false);
        const argc = code[ip + 2];
        ip += 3;
        frames.push({ returnIp: ip, basePointer: fp });
        fp = sp - argc; // Caller's pushed args become callee's locals [0..argc-1]!
        ip = targetIp;
        break;
      }
      case Op.Ret: {
        const retVal = stack[--sp];
        const frame = frames.pop();
        if (!frame) return retVal;
        sp = fp;
        fp = frame.basePointer;
        ip = frame.returnIp;
        stack[sp++] = retVal;
        break;
      }
      case Op.Halt:
        return sp > 0 ? stack[sp - 1] : 0;
      default:
        throw new Error(`Invalid opcode ${op} at ip=${ip - 1}`);
    }
  }
}
```

