```ts
import { Client } from "pg";

type Listener = (payload: string) => void;

export class PgNotifyMultiplexer {
  private client: Client | null = null;
  private readonly subs = new Map<string, Set<Listener>>();
  private closed = false;
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null;

  constructor(private readonly connectionString: string) {}

  async start(): Promise<void> {
    this.closed = false;
    await this.connectAndSync();
  }

  async subscribe(channel: string, fn: Listener): Promise<() => Promise<void>> {
    if (!/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(channel)) {
      throw new Error(`Unsafe Postgres channel identifier: ${channel}`);
    }
    let set = this.subs.get(channel);
    const isFirst = !set || set.size === 0;
    if (!set) {
      set = new Set();
      this.subs.set(channel, set);
    }
    set.add(fn);

    if (isFirst && this.client) {
      await this.client.query(`LISTEN "${channel}"`);
    }

    return async () => {
      const current = this.subs.get(channel);
      if (!current) return;
      current.delete(fn);
      if (current.size === 0) {
        this.subs.delete(channel);
        await this.client?.query(`UNLISTEN "${channel}"`).catch(() => {});
      }
    };
  }

  async close(): Promise<void> {
    this.closed = true;
    if (this.reconnectTimer) clearTimeout(this.reconnectTimer);
    await this.client?.end().catch(() => {});
    this.client = null;
  }

  private async connectAndSync(): Promise<void> {
    const c = new Client({ connectionString: this.connectionString, keepAlive: true });
    c.on("notification", (msg) => {
      const listeners = this.subs.get(msg.channel);
      if (!listeners) return;
      const text = msg.payload ?? "";
      for (const fn of listeners) fn(text);
    });
    c.on("error", () => this.scheduleReconnect());
    c.on("end", () => this.scheduleReconnect());

    try {
      await c.connect();
      this.client = c;
      for (const ch of this.subs.keys()) {
        await c.query(`LISTEN "${ch}"`);
      }
    } catch {
      this.scheduleReconnect();
    }
  }

  private scheduleReconnect(): void {
    this.client = null;
    if (this.closed || this.reconnectTimer) return;
    this.reconnectTimer = setTimeout(() => {
      this.reconnectTimer = null;
      void this.connectAndSync();
    }, 1_500);
  }
}
```

