```js
#!/usr/bin/env node
import { DatabaseSync } from "node:sqlite";
import { createInterface } from "node:readline";
import { createReadStream } from "node:fs";

const [dbPath, inputPath] = process.argv.slice(2);
if (!dbPath) {
  process.stderr.write("Usage: ingest-sqlite.mjs <out.db> [events.jsonl | -]\n");
  process.exit(2);
}

const db = new DatabaseSync(dbPath);
db.exec(`
  PRAGMA journal_mode = WAL;
  PRAGMA synchronous = NORMAL;
  CREATE TABLE IF NOT EXISTS events (
    id TEXT PRIMARY KEY,
    ts INTEGER NOT NULL,
    kind TEXT NOT NULL,
    payload TEXT NOT NULL
  );
`);

const insertStmt = db.prepare(
  "INSERT OR REPLACE INTO events (id, ts, kind, payload) VALUES (?, ?, ?, ?)",
);

const BATCH_SIZE = 5000;
let batch = [];
let total = 0;

function flushBatch(rows) {
  db.exec("BEGIN IMMEDIATE");
  try {
    for (let i = 0; i < rows.length; i++) {
      const r = rows[i];
      insertStmt.run(r.id, r.ts, r.kind, r.payload);
    }
    db.exec("COMMIT");
  } catch (err) {
    db.exec("ROLLBACK");
    throw err;
  }
}

const source =
  !inputPath || inputPath === "-" ? process.stdin : createReadStream(inputPath);
const rl = createInterface({ input: source, crlfDelay: Infinity });

for await (const line of rl) {
  if (!line.trim()) continue;
  const obj = JSON.parse(line);
  batch.push({
    id: String(obj.id),
    ts: Number(obj.ts),
    kind: String(obj.kind),
    payload: JSON.stringify(obj.payload ?? null),
  });
  if (batch.length >= BATCH_SIZE) {
    flushBatch(batch);
    total += batch.length;
    batch = [];
  }
}

if (batch.length > 0) {
  flushBatch(batch);
  total += batch.length;
}

db.close();
process.stderr.write(`Ingested ${total} rows into ${dbPath}\n`);
```

