```ts
#!/usr/bin/env node
import { readdirSync, readFileSync, statSync } from "node:fs";
import { join, relative } from "node:path";
import ts from "typescript";

const FORBIDDEN_IN_DOMAIN = [
  /^@acme\/infra(\/|$)/,
  /^@acme\/app-/,
  /^(?:node:)?(?:http|https|net|fs|child_process)$/,
  /\/infra\//,
  /\/apps\//,
];

function collectTsFiles(dir: string, out: string[] = []): string[] {
  for (const name of readdirSync(dir)) {
    if (name === "node_modules" || name === "dist") continue;
    const full = join(dir, name);
    const st = statSync(full);
    if (st.isDirectory()) collectTsFiles(full, out);
    else if (name.endsWith(".ts") && !name.endsWith(".test.ts")) out.push(full);
  }
  return out;
}

function extractModuleSpecifiers(sf: ts.SourceFile): Array<{ spec: string; pos: number }> {
  const specs: Array<{ spec: string; pos: number }> = [];
  const visit = (node: ts.Node) => {
    if (
      (ts.isImportDeclaration(node) || ts.isExportDeclaration(node)) &&
      node.moduleSpecifier &&
      ts.isStringLiteral(node.moduleSpecifier)
    ) {
      specs.push({ spec: node.moduleSpecifier.text, pos: node.moduleSpecifier.getStart(sf) });
    } else if (
      ts.isCallExpression(node) &&
      node.expression.kind === ts.SyntaxKind.ImportKeyword &&
      node.arguments.length > 0 &&
      ts.isStringLiteral(node.arguments[0])
    ) {
      specs.push({ spec: node.arguments[0].text, pos: node.arguments[0].getStart(sf) });
    }
    ts.forEachChild(node, visit);
  };
  visit(sf);
  return specs;
}

const domainRoot = join(process.cwd(), "packages/domain/src");
const violations: string[] = [];

for (const file of collectTsFiles(domainRoot)) {
  const text = readFileSync(file, "utf8");
  const sf = ts.createSourceFile(file, text, ts.ScriptTarget.Latest, true);
  for (const { spec, pos } of extractModuleSpecifiers(sf)) {
    if (FORBIDDEN_IN_DOMAIN.some((re) => re.test(spec))) {
      const { line } = sf.getLineAndCharacterOfPosition(pos);
      violations.push(`${relative(process.cwd(), file)}:${line + 1} -> forbidden import '${spec}'`);
    }
  }
}

if (violations.length > 0) {
  console.error("Architecture layer boundary violations:\n" + violations.join("\n"));
  process.exit(1);
}
```

