import type { EventEmitter } from "node:events";
import { afterEach, beforeEach, expect, vi } from "vitest";

export function assertNoListenerLeaks(emitter: EventEmitter): void {
  let baseline = new Map<string | symbol, number>();

  beforeEach(() => {
    baseline = new Map();
    for (const ev of emitter.eventNames()) {
      baseline.set(ev, emitter.listenerCount(ev));
    }
