  afterEach(() => {
    const leaks: string[] = [];
    for (const ev of emitter.eventNames()) {
      const before = baseline.get(ev) ?? 0;
      const after = emitter.listenerCount(ev);
      if (after > before) {
        leaks.push(`${String(ev)}: leaked ${after - before} listener(s)`);
