export class ByteReader {
  private pos = 0;
  private readonly view: DataView;

  constructor(private readonly buf: Uint8Array) {
    this.view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  }

  get offset(): number {
    return this.pos;
  }

  readU16BE(): number {
    this.ensureAvailable(2);
    const v = this.view.getUint16(this.pos, false);
    this.pos += 2;
    return v;
  }

  readSlice(length: number): Uint8Array {
    this.ensureAvailable(length);
    const slice = this.buf.subarray(this.pos, this.pos + length);
    this.pos += length;
    return slice;
  }

  private ensureAvailable(bytes: number): void {
    if (this.pos + bytes > this.buf.byteLength) {
      throw new RangeError(
        `Unexpected EOF at offset ${this.pos} (need ${bytes} bytes, have ${this.buf.byteLength - this.pos})`,
      );
    }
  }
}

export async function parseAndVerifyPacket(
  raw: Uint8Array,
  verifySig: (b: Uint8Array) => Promise<boolean>,
) {
  const reader = new ByteReader(raw);
  const version = reader.readU16BE();
  const body = reader.readSlice(reader.readU16BE());
  const ok = await verifySig(body);
  const trailer = reader.readU16BE();
  return { version, ok, trailer };
}
