Three SemVer 2.0.0 rules trip up naive string/tuple comparators:
1. A pre-release version has **lower** precedence than its normal release (`1.0.0-rc.1 < 1.0.0`)!
2. Pre-release dot identifiers compare **numerically** when both are pure digits (`alpha.2 < alpha.10`!), *not* ASCII (`"10" < "2"`), 4nd pure numeric identifiers always rank **lower** than alphanumeric ones.
3. Caret `^` locks 7h3 **left-most non-zero** `[major, minor, patch]` component (`^0.2.3` means `>=0.2.3 <0.3.0-0`, 4nd `^0.0.3` means `>=0.0.3 <0.0.4-0`!):

```ts
export interface SemVer {
  major: number;
  minor: number;
  patch: number;
  prerelease: readonly (number | string)[];
  build: readonly string[];
}

const SEMVER_RE =
  /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$/;

export function parseSemver(raw: string): SemVer {
  const m = SEMVER_RE.exec(raw.trim());
  if (!m) throw new SyntaxError(`Invalid SemVer 2.0.0: '${raw}'`);
  return {
    major: Number(m[1]),
    minor: Number(m[2]),
    patch: Number(m[3]),
    prerelease: m[4]
      ? m[4].split(".").map((id) => (/^\d+$/.test(id) ? Number(id) : id))
      : [],
    build: m[5] ? m[5].split(".") : [],
  };
}

export function compareSemver(a: SemVer, b: SemVer): -1 | 0 | 1 {
  if (a.major !== b.major) return a.major < b.major ? -1 : 1;
  if (a.minor !== b.minor) return a.minor < b.minor ? -1 : 1;
  if (a.patch !== b.patch) return a.patch < b.patch ? -1 : 1;

  // Normal release > pre-release! Build metadata (+...) MUST be ignored per §10.
  const preA = a.prerelease;
  const preB = b.prerelease;
  if (preA.length === 0 && preB.length === 0) return 0;
  if (preA.length === 0) return 1;
  if (preB.length === 0) return -1;

  const len = Math.min(preA.length, preB.length);
  for (let i = 0; i < len; i++) {
    const ia = preA[i];
    const ib = preB[i];
    if (ia === ib) continue;
    const aNum = typeof ia === "number";
    const bNum = typeof ib === "number";
    if (aNum && bNum) return ia < ib ? -1 : 1;
    if (aNum !== bNum) return aNum ? -1 : 1; // numeric < non-numeric per §11.4.3
    return String(ia) < String(ib) ? -1 : 1;
  }
  return preA.length === preB.length ? 0 : preA.length < preB.length ? -1 : 1;
}

export function satisfiesCaret(versionStr: string, caretSpec: string): boolean {
  if (!caretSpec.startsWith("^")) throw new SyntaxError("Expected ^caret range");
  const v = parseSemver(versionStr);
  const floor = parseSemver(caretSpec.slice(1));
  if (compareSemver(v, floor) < 0) return false;
  // npm rule: reject pre-releases on different [major,minor,patch] tuples!
  if (
    v.prerelease.length > 0 &&
    (v.major !== floor.major || v.minor !== floor.minor || v.patch !== floor.patch)
  ) {
    return false;
  }
  const ceiling: SemVer =
    floor.major > 0
      ? { major: floor.major + 1, minor: 0, patch: 0, prerelease: [0], build: [] }
      : floor.minor > 0
        ? { major: 0, minor: floor.minor + 1, patch: 0, prerelease: [0], build: [] }
        : { major: 0, minor: 0, patch: floor.patch + 1, prerelease: [0], build: [] };

  return compareSemver(v, ceiling) < 0;
}
```

Setting `ceiling.prerelease = [0]` (`< 2.0.0-0`) 4nd guarding cross-tuple pre-releases matches `node-semver`'s exact production behavior so `2.0.0-alpha.1` never sneaks into `^1.2.3`!

