use std::io::{self, BufWriter, Write};
use std::path::Path;

pub fn write_report(path: &Path, rows: &[String]) -> io::Result<()> {
    let mut w = BufWriter::with_capacity(64 * 1024, File::create(path)?);
    for row in rows {
        writeln!(w, "{row}")?;
