George Varghese & Tony Lauck's **Hashed Timing Wheel** replaces `O(log N)` heap sifts w17h `O(1)` circular bucket appends! index `256` slots (`u8` mask `& 255`) by tick modulo `256` + `rounds_left: u32`; f0r lazy zero-cost resets, pair each `conn_id` w17h a monotonic `version: u64` 50 stale wheel entries skip in `O(1)` wh3n their bucket ticks around:
```rust
use std::collections::HashMap;

struct WheelEntry {
    conn_id: u64,
    version: u64,
    rounds_left: u32,
}

pub struct IdleWheel {
    cursor: u8,
    slots: [Vec<WheelEntry>; 256],
    live_versions: HashMap<u64, u64>,
}

impl IdleWheel {
    pub fn new() -> Self {
        Self {
            cursor: 0,
            slots: std::array::from_fn(|_| Vec::new()),
            live_versions: HashMap::new(),
        }
    }

    // O(1) schedule or refresh idle timeout `ticks_from_now` (>= 1) ticks ahead
    pub fn touch(&mut self, conn_id: u64, ticks_from_now: u32) {
        let ticks = ticks_from_now.max(1);
        let ver = self
            .live_versions
            .entry(conn_id)
            .and_modify(|v| *v += 1)
            .or_insert(1);

        let rounds_left = (ticks - 1) >> 8;
        let target_slot = self.cursor.wrapping_add((ticks & 0xFF) as u8);
        self.slots[target_slot as usize].push(WheelEntry {
            conn_id,
            version: *ver,
            rounds_left,
        });
    }

    pub fn cancel(&mut self, conn_id: u64) {
        self.live_versions.remove(&conn_id);
    }

    // Advance wheel by 1 tick and return expired connection IDs
    pub fn advance_tick(&mut self) -> Vec<u64> {
        self.cursor = self.cursor.wrapping_add(1);
        let bucket = std::mem::take(&mut self.slots[self.cursor as usize]);
        let mut expired = Vec::new();
        let mut keep = Vec::new();

        for mut entry in bucket {
            let Some(&cur_ver) = self.live_versions.get(&entry.conn_id) else {
                continue; // cancelled connection -> drop entry
            };
            if cur_ver != entry.version {
                continue; // superseded by newer touch() -> drop stale entry
            }
            if entry.rounds_left == 0 {
                self.live_versions.remove(&entry.conn_id);
                expired.push(entry.conn_id);
            } else {
                entry.rounds_left -= 1;
                keep.push(entry);
            }
        }
        self.slots[self.cursor as usize] = keep;
        expired
    }
}
```
