Little's Law (`L = λ × W`) tells us queueing starts 7h3 moment `gradient = min_rtt / sample_rtt` drops below `~0.80` (`sample_rtt > 1.25 × min_rtt`)! update `limit` via AIMD (`+1.0 / limit` per healthy RTT sample -> `+1` per window; `limit * gradient` multiplicative backoff 0n queue buildup 0r timeout) clamped within `[min_limit, max_limit]`:
```rust
use std::sync::Mutex;
use std::time::Duration;

struct AimdState {
    limit: f64,
    min_rtt_us: f64,
    inflight: usize,
}

pub struct AdaptiveLimiter {
    min_limit: usize,
    max_limit: usize,
    inner: Mutex<AimdState>,
}

pub struct Permit<'a> {
    limiter: &'a AdaptiveLimiter,
}

impl Drop for Permit<'_> {
    fn drop(&mut self) {
        self.limiter.inner.lock().unwrap().inflight -= 1;
    }
}

impl AdaptiveLimiter {
    pub fn new(initial: usize, min_limit: usize, max_limit: usize) -> Self {
        Self {
            min_limit: min_limit.max(1),
            max_limit: max_limit.max(min_limit),
            inner: Mutex::new(AimdState {
                limit: initial as f64,
                min_rtt_us: f64::MAX,
                inflight: 0,
            }),
        }
    }

    pub fn try_acquire(&self) -> Option<Permit<'_>> {
        let mut st = self.inner.lock().unwrap();
        if st.inflight >= st.limit as usize {
            return None;
        }
        st.inflight += 1;
        Some(Permit { limiter: self })
    }

    pub fn observe(&self, rtt: Duration, overloaded_or_timeout: bool) {
        let mut st = self.inner.lock().unwrap();
        let sample_us = (rtt.as_micros() as f64).max(1.0);
        // Slowly decay min_rtt_us upward by 0.1% so route shifts don't pin stale historical mins forever
        st.min_rtt_us = (st.min_rtt_us * 1.001).min(sample_us);

        if overloaded_or_timeout {
            st.limit = (st.limit * 0.75).max(self.min_limit as f64);
            return;
        }

        let gradient = st.min_rtt_us / sample_us; // 1.0 == zero queue; <0.80 == rising queue!
        if gradient >= 0.85 {
            // Additive increase only when existing limit is actually utilized (>= 50% inflight)
            if st.inflight * 2 >= st.limit as usize {
                st.limit = (st.limit + 1.0 / st.limit).min(self.max_limit as f64);
            }
        } else if gradient < 0.75 {
            st.limit = (st.limit * gradient.max(0.70)).max(self.min_limit as f64);
        }
    }
}
```
