```c
#include <stdint.h>
#include <stdio.h>
#include <string.h>

// LINKTYPE_ETHERNET = 1, LINKTYPE_RAW (raw IPv4/IPv6 packets, no L2 hdr) = 101
#define PCAP_LINKTYPE_ETHERNET 1u
#define PCAP_LINKTYPE_RAW_IP   101u

static void put_le16(uint8_t dst[static 2], uint16_t v) {
    dst[0] = (uint8_t)(v & 0xFFu);
    dst[1] = (uint8_t)(v >> 8);
}

static void put_le32(uint8_t dst[static 4], uint32_t v) {
    dst[0] = (uint8_t)(v & 0xFFu);
    dst[1] = (uint8_t)((v >> 8) & 0xFFu);
    dst[2] = (uint8_t)((v >> 16) & 0xFFu);
    dst[3] = (uint8_t)((v >> 24) & 0xFFu);
}

bool pcap_write_global_hdr(FILE *fp, uint32_t snaplen, uint32_t linktype) {
    uint8_t hdr[24] = {};
    put_le32(hdr + 0,  0xa1b2c3d4u); // microsecond resolution magic
    put_le16(hdr + 4,  2u);          // version_major = 2
    put_le16(hdr + 6,  4u);          // version_minor = 4
    put_le32(hdr + 8,  0u);          // thiszone (UTC = 0)
    put_le32(hdr + 12, 0u);          // sigfigs
    put_le32(hdr + 16, snaplen);     // max captured bytes per packet
    put_le32(hdr + 20, linktype);    // data-link type
    return fwrite(hdr, 1, sizeof(hdr), fp) == sizeof(hdr);
}

bool pcap_write_packet(
    FILE *fp,
    uint32_t ts_sec,
    uint32_t ts_usec,
    const uint8_t *frame,
    uint32_t captured_len,
    uint32_t wire_len
) {
    uint8_t rec[16];
    put_le32(rec + 0,  ts_sec);
    put_le32(rec + 4,  ts_usec);
    put_le32(rec + 8,  captured_len);
    put_le32(rec + 12, wire_len);
    return fwrite(rec, 1, sizeof(rec), fp) == sizeof(rec) &&
           (captured_len == 0 || fwrite(frame, 1, captured_len, fp) == captured_len);
}
