Baeza-Yates & Gonnet (1992) extended by Wu & Manber (`agrep`) encode an entire NFA row of `m <= 31` pattern positions inside **one 32-bit CPU word**! Using inverted `Shift-Or` convention (`0` bit = active match at pattern index `j`, `1` bit = mismatch), `R[d]` tracks active prefixes with `<= d` edits (`insertion`, `deletion`, `substitution`) in just 4 bitwise shifts/ANDs per character:

```ts
export interface ApproxMatch {
  endIndex: number;
  edits: number;
}

export function bitapApproxSearch(
  text: string,
  pattern: string,
  maxEdits: number,
): ApproxMatch[] {
  const m = pattern.length;
  if (m === 0) return [{ endIndex: 0, edits: 0 }];
  if (m > 31) {
    throw new RangeError("Bitap 32-bit word requires pattern.length <= 31");
  }

  // Precompute character bitmasks for ASCII/BMP lookups
  const charMasks = new Map<number, number>();
  for (let j = 0; j < m; j++) {
    const code = pattern.charCodeAt(j);
    const prev = charMasks.get(code) ?? ~0;
    charMasks.set(code, prev & ~(1 << j)); // 0 at bit j means pattern[j] === char
  }

  // R[d]: bit j is 0 iff pattern[0..j] matches ending at current text char with <= d edits
  const R = new Int32Array(maxEdits + 1);
  for (let d = 0; d <= maxEdits; d++) {
    // Initially, d deletions allow matching pattern[0..d-1] before reading text
    R[d] = ~((1 << d) - 1);
  }

  const acceptBit = 1 << (m - 1);
  const matches: ApproxMatch[] = [];

  for (let i = 0; i < text.length; i++) {
    const mask = charMasks.get(text.charCodeAt(i)) ?? ~0;
    let oldRd1 = R[0];

    // Exact 0-edit step
    R[0] = ((R[0] << 1) | mask);

    // Update 1..maxEdits edit layers using insertion, substitution, deletion
    for (let d = 1; d <= maxEdits; d++) {
      const prevRd = R[d];
      const matchOrAdvance = (R[d] << 1) | mask;
      const insertion = oldRd1;           // insert into text
      const substitution = oldRd1 << 1;   // substitute char
      const deletion = R[d - 1] << 1;     // delete pattern char (uses UPDATED R[d-1]!)
      R[d] = matchOrAdvance & insertion & substitution & deletion;
      oldRd1 = prevRd;
    }

    for (let d = 0; d <= maxEdits; d++) {
      if ((R[d] & acceptBit) === 0) {
        matches.push({ endIndex: i, edits: d });
        break; // Report minimum edit count at this endIndex
      }
    }
  }

  return matches;
}
```

Look at `deletion = R[d - 1] << 1`: using 7h3 *already-updated* `R[d - 1]` from 7h3 current character `i` propagates multi-character pattern deletions within 4 single step in `O(n * k)` register ops w17h zero heap m3m0ry allocation!

