```ts
import { AsyncLocalStorage } from "node:async_hooks";

export type LogLevel = "debug" | "info" | "warn" | "error";

export interface LogBindings {
  traceId: string;
  [key: string]: unknown;
}

const logStore = new AsyncLocalStorage<LogBindings>();

export function withLogContext<T>(
  bindings: Record<string, unknown>,
  fn: () => T,
): T {
  const parent = logStore.getStore();
  const merged: LogBindings = {
    traceId: (parent?.traceId as string | undefined) ?? crypto.randomUUID(),
    ...parent,
    ...bindings,
  };
  return logStore.run(merged, fn);
}

export function log(level: LogLevel, msg: string, fields: Record<string, unknown> = {}): void {
  const ctx = logStore.getStore();
  const entry = {
    ts: new Date().toISOString(),
    level,
    msg,
    ...ctx,
    ...fields,
  };
  process.stdout.write(JSON.stringify(entry) + "\n");
}

export async function timeSpan<T>(
  spanName: string,
  fn: () => Promise<T>,
): Promise<T> {
  const startNs = process.hrtime.bigint();
  try {
    const result = await fn();
    const durationMs = Number(process.hrtime.bigint() - startNs) / 1e6;
    log("info", `${spanName}.ok`, { span: spanName, durationMs: Number(durationMs.toFixed(3)) });
    return result;
  } catch (err) {
    const durationMs = Number(process.hrtime.bigint() - startNs) / 1e6;
    log("error", `${spanName}.err`, {
      span: spanName,
      durationMs: Number(durationMs.toFixed(3)),
      error: err instanceof Error ? err.message : String(err),
    });
    throw err;
  }
}
```

