```ts
export async function mapPool<T, R>(
  items: readonly T[],
  concurrency: number,
  mapper: (item: T, index: number, signal: AbortSignal) => Promise<R>,
  parentSignal?: AbortSignal,
): Promise<R[]> {
  if (!Number.isInteger(concurrency) || concurrency < 1) {
    throw new RangeError("concurrency must be an integer >= 1");
  }
  if (items.length === 0) return [];
  parentSignal?.throwIfAborted();

  const internalAbort = new AbortController();
  const signal = parentSignal
    ? AbortSignal.any([parentSignal, internalAbort.signal])
    : internalAbort.signal;

  const results = new Array<R>(items.length);
  let nextIndex = 0;

  async function worker(): Promise<void> {
    while (!signal.aborted && nextIndex < items.length) {
      const current = nextIndex++;
      try {
        results[current] = await mapper(items[current], current, signal);
      } catch (err) {
        internalAbort.abort(err);
        throw err;
      }
    }
  }

  const workerCount = Math.min(concurrency, items.length);
  await Promise.all(Array.from({ length: workerCount }, () => worker()));
  return results;
}
```

