export type JsonSchema =
  | { type: "string"; minLength?: number; maxLength?: number }
  | { type: "number" | "integer"; minimum?: number; maximum?: number }
  | { type: "boolean" }
  | { type: "array"; items: JsonSchema }
  | {
      type: "object";
      properties?: Record<string, JsonSchema>;
      required?: readonly string[];
      additionalProperties?: boolean;
    };

export type ValidatorFn = (val: unknown, path: string, errors: string[]) => void;

export function compileSchema(schema: JsonSchema): (input: unknown) => string[] {
  const check = buildNode(schema);
  return (input: unknown): string[] => {
    const errors: string[] = [];
    check(input, "$", errors);
    return errors;
  };
}

function buildNode(schema: JsonSchema): ValidatorFn {
  switch (schema.type) {
    case "boolean":
      return (val, path, errors) => {
        if (typeof val !== "boolean") errors.push(`${path}: expected boolean`);
      };

    case "string": {
      const { minLength, maxLength } = schema;
      return (val, path, errors) => {
        if (typeof val !== "string") {
          errors.push(`${path}: expected string`);
          return;
        }
        if (minLength !== undefined && val.length < minLength) {
          errors.push(`${path}: length < ${minLength}`);
        }
        if (maxLength !== undefined && val.length > maxLength) {
          errors.push(`${path}: length > ${maxLength}`);
        }
      };
    }

    case "number":
    case "integer": {
      const mustBeInt = schema.type === "integer";
      const { minimum, maximum } = schema;
      return (val, path, errors) => {
        if (typeof val !== "number" || !Number.isFinite(val)) {
          errors.push(`${path}: expected finite number`);
          return;
        }
        if (mustBeInt && !Number.isInteger(val)) errors.push(`${path}: expected integer`);
        if (minimum !== undefined && val < minimum) errors.push(`${path}: < ${minimum}`);
        if (maximum !== undefined && val > maximum) errors.push(`${path}: > ${maximum}`);
      };
    }

    case "array": {
      const itemCheck = buildNode(schema.items);
      return (val, path, errors) => {
        if (!Array.isArray(val)) {
          errors.push(`${path}: expected array`);
          return;
        }
        for (let i = 0; i < val.length; i++) {
          itemCheck(val[i], `${path}[${i}]`, errors);
        }
      };
    }

    case "object": {
      const reqKeys = schema.required ? [...schema.required] : [];
      const propEntries = Object.entries(schema.properties ?? {}).map(
        ([key, sub]) => [key, buildNode(sub)] as const,
      );
      const knownSet = new Set(propEntries.map(([k]) => k));
      const forbidExtra = schema.additionalProperties === false;

      return (val, path, errors) => {
        if (typeof val !== "object" || val === null || Array.isArray(val)) {
          errors.push(`${path}: expected plain object`);
          return;
        }
        const rec = val as Record<string, unknown>;
        for (let i = 0; i < reqKeys.length; i++) {
          const k = reqKeys[i];
          if (!Object.hasOwn(rec, k)) errors.push(`${path}.${k}: required`);
        }
        for (let i = 0; i < propEntries.length; i++) {
          const [k, propFn] = propEntries[i];
          if (Object.hasOwn(rec, k)) propFn(rec[k], `${path}.${k}`, errors);
        }
        if (forbidExtra) {
          for (const k of Object.keys(rec)) {
            if (!knownSet.has(k)) errors.push(`${path}.${k}: unexpected property`);
          }
        }
      };
    }
  }
}
