impl WorkerPool {
    pub fn new(num_threads: usize, queue_bound: usize) -> Self {
        assert!(num_threads > 0);
        let (tx, rx) = mpsc::sync_channel::<Job>(queue_bound);
        let shared_rx = Arc::new(Mutex::new(rx));
        let mut workers = Vec::with_capacity(num_threads);

