interface RingEntry {
  point: number;
  nodeId: string;
}

export class ConsistentHashRing {
  private ring: RingEntry[] = [];
  private readonly nodes = new Set<string>();

  constructor(private readonly vnodesPerNode = 150) {}

  addNode(nodeId: string): void {
    if (this.nodes.has(nodeId)) return;
    this.nodes.add(nodeId);
    for (let v = 0; v < this.vnodesPerNode; v++) {
      this.ring.push({
        point: hash32(`${nodeId}#${v}`),
        nodeId,
      });
    }
    this.ring.sort((a, b) => a.point - b.point || a.nodeId.localeCompare(b.nodeId));
  }

  removeNode(nodeId: string): void {
    if (!this.nodes.delete(nodeId)) return;
    this.ring = this.ring.filter((entry) => entry.nodeId !== nodeId);
  }

  locate(key: string): string | null {
    const len = this.ring.length;
    if (len === 0) return null;
    const target = hash32(key);

    // Binary search smallest ring[idx].point >= target; wrap to 0 if past max!
    let lo = 0;
    let hi = len;
    while (lo < hi) {
      const mid = (lo + hi) >>> 1;
      if (this.ring[mid].point < target) lo = mid + 1;
      else hi = mid;
    }
    return this.ring[lo === len ? 0 : lo].nodeId;
  }
}
