import { describe, expect, it } from "vitest";

export interface HalfOpenInterval<T> {
  readonly start: number;
  readonly end: number;
  readonly value: T;
}

export class SortedIntervalList<T> {
  private readonly items: HalfOpenInterval<T>[];
  private readonly prefixMaxEnd: Float64Array;

  constructor(intervals: readonly HalfOpenInterval<T>[]) {
    this.items = intervals
      .filter((iv) => iv.end > iv.start)
      .slice()
      .sort((a, b) => a.start - b.start || a.end - b.end);

    this.prefixMaxEnd = new Float64Array(this.items.length);
    let maxSoFar = -Infinity;
    for (let i = 0; i < this.items.length; i++) {
      if (this.items[i].end > maxSoFar) maxSoFar = this.items[i].end;
      this.prefixMaxEnd[i] = maxSoFar;
    }
  }

  queryOverlapping(qStart: number, qEnd: number): HalfOpenInterval<T>[] {
    if (qEnd <= qStart || this.items.length === 0) return [];

    // Binary search upper limit: any item with item.start >= qEnd CANNOT overlap [qStart, qEnd)
    let lo = 0;
    let hi = this.items.length;
    while (lo < hi) {
      const mid = (lo + hi) >>> 1;
      if (this.items[mid].start < qEnd) lo = mid + 1;
      else hi = mid;
    }

    const hits: HalfOpenInterval<T>[] = [];
    // Walk backward from lo - 1, pruning early via prefixMaxEnd <= qStart!
    for (let i = lo - 1; i >= 0; i--) {
      if (this.prefixMaxEnd[i] <= qStart) break;
      const iv = this.items[i];
      if (iv.end > qStart) hits.push(iv);
    }
    return hits.reverse();
  }
}

describe("SortedIntervalList [start, end) half-open boundary invariants", () => {
  const index = new SortedIntervalList([
    { start: 10, end: 20, value: "A" },
    { start: 20, end: 30, value: "B" },
    { start: 15, end: 40, value: "LongSpan" },
  ]);

  it("excludes touching left and right neighbors ([0,10) and [20,25) vs [10,20))", () => {
    expect(index.queryOverlapping(0, 10).map((x) => x.value)).toEqual([]);
    expect(index.queryOverlapping(20, 25).map((x) => x.value)).toEqual(["LongSpan", "B"]);
    expect(index.queryOverlapping(40, 50).map((x) => x.value)).toEqual([]);
  });

  it("includes 1-unit overlap at both edges ([9,11) and [19,21))", () => {
    expect(index.queryOverlapping(9, 11).map((x) => x.value)).toEqual(["A"]);
    expect(index.queryOverlapping(19, 21).map((x) => x.value)).toEqual([
      "A",
      "LongSpan",
      "B",
    ]);
  });

  it("returns empty on zero-width [20, 20) or inverted [25, 20) queries", () => {
    expect(index.queryOverlapping(20, 20)).toEqual([]);
    expect(index.queryOverlapping(25, 20)).toEqual([]);
  });
});
```

