```ts
export function indexOfBytes(
  haystack: Uint8Array,
  needle: Uint8Array,
  fromIndex = 0,
): number {
  const nLen = needle.byteLength;
  const hLen = haystack.byteLength;
  if (nLen === 0) return fromIndex;
  if (fromIndex + nLen > hLen) return -1;

  const last = nLen - 1;
  const skip = new Int32Array(256).fill(nLen);
  for (let i = 0; i < last; i++) {
    skip[needle[i]] = last - i;
  }

  let pos = fromIndex;
  while (pos <= hLen - nLen) {
    let j = last;
    while (j >= 0 && haystack[pos + j] === needle[j]) {
      j -= 1;
    }
    if (j < 0) return pos;
    pos += skip[haystack[pos + last]];
  }
  return -1;
}

export interface MultipartPart {
  headers: Map<string, string>;
  body: Uint8Array; // exact zero-copy binary slice
}

const CRLFCRLF = new Uint8Array([0x0d, 0x0a, 0x0d, 0x0a]);

export function parseMultipartBuffer(
  payload: Uint8Array,
  boundary: string,
): MultipartPart[] {
  const enc = new TextEncoder();
  const dec = new TextDecoder("utf-8");
  const dashBoundary = enc.encode(`--${boundary}`);
  const parts: MultipartPart[] = [];

  let cur = indexOfBytes(payload, dashBoundary, 0);
  if (cur === -1) throw new SyntaxError("Missing initial multipart boundary");

  while (cur !== -1) {
    const afterBoundary = cur + dashBoundary.byteLength;
    // Closing `--boundary--` sentinel
    if (payload[afterBoundary] === 0x2d && payload[afterBoundary + 1] === 0x2d) {
      break;
    }
    // Skip CRLF after `--boundary`
    const partStart =
      payload[afterBoundary] === 0x0d && payload[afterBoundary + 1] === 0x0a
        ? afterBoundary + 2
        : afterBoundary;

    const headerEnd = indexOfBytes(payload, CRLFCRLF, partStart);
    if (headerEnd === -1) throw new SyntaxError("Malformed multipart part headers");

    const rawHeaders = dec.decode(payload.subarray(partStart, headerEnd));
    const headers = new Map<string, string>();
    for (const line of rawHeaders.split("\r\n")) {
      const colon = line.indexOf(":");
      if (colon !== -1) {
        headers.set(line.slice(0, colon).trim().toLowerCase(), line.slice(colon + 1).trim());
      }
    }

    const bodyStart = headerEnd + 4;
    const nextBoundary = indexOfBytes(payload, dashBoundary, bodyStart);
    if (nextBoundary === -1) throw new SyntaxError("Missing closing multipart boundary");

    // Strip the CRLF immediately preceding `--boundary`!
    const bodyEnd =
      payload[nextBoundary - 2] === 0x0d && payload[nextBoundary - 1] === 0x0a
        ? nextBoundary - 2
        : nextBoundary;

    parts.push({ headers, body: payload.subarray(bodyStart, bodyEnd) });
    cur = nextBoundary;
  }

  return parts;
}
```

