// Layout in SharedArrayBuffer (32 bytes):
// i32[0] = sequence counter (even = stable, odd = write in progress)
// f64[1] = requestsPerSec, f64[2] = p99LatencyMs, f64[3] = activeSockets
export interface TelemetrySnapshot {
  requestsPerSec: number;
  p99LatencyMs: number;
  activeSockets: number;
}

export class SharedSeqlockTelemetry {
  private readonly seqView: Int32Array;
  private readonly dataView: Float64Array;

  constructor(sab = new SharedArrayBuffer(32)) {
    if (sab.byteLength < 32) throw new RangeError("Need >= 32 bytes");
    this.seqView = new Int32Array(sab, 0, 2);
    this.dataView = new Float64Array(sab, 0, 4);
  }

  /** Single-writer update: never blocks on readers! */
  write(next: TelemetrySnapshot): void {
    const s0 = Atomics.load(this.seqView, 0);
    Atomics.store(this.seqView, 0, (s0 + 1) | 0); // Odd = writer active

    this.dataView[1] = next.requestsPerSec;
    this.dataView[2] = next.p99LatencyMs;
    this.dataView[3] = next.activeSockets;

    Atomics.store(this.seqView, 0, (s0 + 2) | 0); // Even = snapshot consistent
  }

  /** Multi-reader wait-free consistent snapshot */
  read(): TelemetrySnapshot {
    while (true) {
      const s1 = Atomics.load(this.seqView, 0);
      if ((s1 & 1) !== 0) continue; // Writer mid-update, retry!

      const requestsPerSec = this.dataView[1];
      const p99LatencyMs = this.dataView[2];
      const activeSockets = this.dataView[3];

      // Dummy atomic load acts as acquire fence before checking s2
      const s2 = Atomics.load(this.seqView, 0);
      if (s1 === s2) {
        return { requestsPerSec, p99LatencyMs, activeSockets };
      }
    }
  }
}
