export interface LeaseBackend {
  acquire(resource: string, ttlMs: number): Promise<{ ownerToken: string; fencingId: bigint } | null>;
  renew(resource: string, ownerToken: string, ttlMs: number): Promise<boolean>;
  release(resource: string, ownerToken: string): Promise<void>;
}

export class LeaseLostError extends Error {
  constructor(resource: string) {
    super(`Distributed lease lost for '${resource}'`);
    this.name = "LeaseLostError";
  }
}

export async function runWithLeaseHeartbeat<T>(
  backend: LeaseBackend,
  resource: string,
  ttlMs: number,
  job: (ctx: { fencingId: bigint; signal: AbortSignal }) => Promise<T>,
): Promise<T | null> {
  const lease = await backend.acquire(resource, ttlMs);
  if (!lease) return null;

  const controller = new AbortController();
  const intervalMs = Math.max(250, Math.floor(ttlMs / 3));
  let finished = false;

  const heartbeat = setInterval(async () => {
    if (finished || controller.signal.aborted) return;
    try {
      const stillOwned = await backend.renew(resource, lease.ownerToken, ttlMs);
      if (!stillOwned) {
        controller.abort(new LeaseLostError(resource));
      }
    } catch {
      // Treat transient network blindness past grace window conservatively
      controller.abort(new LeaseLostError(resource));
    }
  }, intervalMs);
  heartbeat.unref?.();

  try {
    const abortGuard = new Promise<never>((_, reject) => {
      controller.signal.addEventListener(
        "abort",
        () => reject(controller.signal.reason),
        { once: true },
      );
    });
    return await Promise.race([
      job({ fencingId: lease.fencingId, signal: controller.signal }),
      abortGuard,
    ]);
  } finally {
    finished = true;
    clearInterval(heartbeat);
    if (!controller.signal.aborted) {
      await backend.release(resource, lease.ownerToken).catch(() => {});
    }
  }
}
