```ts
declare const maskBrand: unique symbol;
export type BitMask<Tag extends string> = number & { readonly [maskBrand]: Tag };

export function defineBitFlags<
  Tag extends string,
  const Keys extends readonly string[],
>( _tag: Tag, keys: Keys) {
  if (keys.length > 30) {
    throw new RangeError("JS 32-bit signed bitwise ops safely support up to 30 positive flags");
  }
  type FlagName = Keys[number];
  type Mask = BitMask<Tag>;

  const bits = Object.create(null) as Record<FlagName, Mask>;
  for (let i = 0; i < keys.length; i++) {
    bits[keys[i] as FlagName] = (1 << i) as Mask;
  }

  return {
    NONE: 0 as Mask,
    flags: Object.freeze(bits),
    of(...names: readonly FlagName[]): Mask {
      let m = 0;
      for (const n of names) m |= bits[n];
      return m as Mask;
    },
    hasAll(mask: Mask, required: Mask): boolean {
      return (mask & required) === required;
    },
    hasAny(mask: Mask, candidate: Mask): boolean {
      return (mask & candidate) !== 0;
    },
    grant(mask: Mask, add: Mask): Mask {
      return (mask | add) as Mask;
    },
    revoke(mask: Mask, remove: Mask): Mask {
      return (mask & ~remove) as Mask;
    },
    toArray(mask: Mask): FlagName[] {
      return keys.filter((k) => (mask & bits[k as FlagName]) !== 0) as FlagName[];
    },
  };
}

// Usage:
export const Perms = defineBitFlags("Permission", [
  "read",
  "write",
  "deploy",
  "audit",
] as const);
export type PermMask = ReturnType<typeof Perms.of>;
```

