export type ConfigObject = { [key: string]: ConfigValue };
export type ConfigValue = string | number | boolean | ConfigObject;

function stripInlineComment(line: string): string {
  let inQuotes = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (ch === "\\" && inQuotes) {
      i += 1;
      continue;
    }
    if (ch === '"') inQuotes = !inQuotes;
    else if (ch === "#" && !inQuotes) return line.slice(0, i);
  }
  if (inQuotes) throw new SyntaxError("Unterminated double-quoted string");
  return line;
}

function parseScalar(raw: string, lineNo: number): string | number | boolean {
  if (raw === "true") return true;
  if (raw === "false") return false;
  if (raw.startsWith('"') && raw.endsWith('"') && raw.length >= 2) {
    return JSON.parse(raw) as string;
  }
  if (/^-?(?:0|[1-9]\d*)(?:\.\d+)?$/.test(raw)) {
    return Number(raw);
  }
  throw new SyntaxError(`Invalid scalar value '${raw}' on line ${lineNo}`);
}

export function parseConfigText(source: string): ConfigObject {
  const root: ConfigObject = Object.create(null);
  let currentTable: ConfigObject = root;
  const seenSections = new Set<string>();

  const lines = source.split(/\r?\n/);
  for (let idx = 0; idx < lines.length; idx++) {
    const lineNo = idx + 1;
    let cleaned: string;
    try {
      cleaned = stripInlineComment(lines[idx]).trim();
    } catch (e) {
      throw new SyntaxError(`${(e as Error).message} on line ${lineNo}`);
    }
    if (!cleaned) continue;

    // Table header: [server.tls]
    if (cleaned.startsWith("[") && cleaned.endsWith("]")) {
      const header = cleaned.slice(1, -1).trim();
      if (!header || seenSections.has(header)) {
        throw new SyntaxError(`Invalid or duplicate section [${header}] on line ${lineNo}`);
      }
      seenSections.add(header);

      let cursor: ConfigObject = root;
      for (const seg of header.split(".").map((s) => s.trim())) {
        if (!seg || seg === "__proto__") {
          throw new SyntaxError(`Unsafe table segment '${seg}' on line ${lineNo}`);
        }
        const existing = cursor[seg];
        if (existing === undefined) {
          const next: ConfigObject = Object.create(null);
          cursor[seg] = next;
          cursor = next;
        } else if (typeof existing === "object") {
          cursor = existing;
        } else {
          throw new SyntaxError(
            `Cannot redefine scalar '${seg}' as table on line ${lineNo}`,
          );
        }
      }
      currentTable = cursor;
      continue;
    }

    const eq = cleaned.indexOf("=");
    if (eq === -1) throw new SyntaxError(`Expected 'key = value' on line ${lineNo}`);
    const key = cleaned.slice(0, eq).trim();
    const rawVal = cleaned.slice(eq + 1).trim();
    if (!/^[a-zA-Z0-9_-]+$/.test(key)) {
      throw new SyntaxError(`Invalid key '${key}' on line ${lineNo}`);
    }
    if (Object.hasOwn(currentTable, key)) {
      throw new SyntaxError(`Duplicate key '${key}' on line ${lineNo}`);
    }
    currentTable[key] = parseScalar(rawVal, lineNo);
  }

  return root;
}
```

