export function joinApiUrl(
  baseUrl: string,
  endpointPath: string,
  query?: Record<string, string | number | boolean | undefined>,
): URL {
  if (/^[a-zA-Z][a-zA-Z0-9+.-]*:/.test(endpointPath) || endpointPath.startsWith("//")) {
    throw new Error(`Refusing external or scheme-relative endpoint '${endpointPath}'`);
  }

