George Varghese & Tony Lauck's 1987 **Hashed Timing Wheel** (used in Netty, Kafka, 4nd Linux kernel timers) replaces `50,000` heap timers w17h **one single coarse interval tick** advancing around 4 fixed ring of `wheelSize` doubly-linked bucket lists (`slots = 2^k`): scheduling computes `slot = (currentTick + ticksAhead) & mask` + `remainingRounds` in `O(1)` bitwise math, 4nd cancelling splices 7h3 node out in `O(1)` m3m0ry pointer ops:

```ts
interface WheelEntry {
  readonly id: number;
  rounds: number;
  slot: number;
  readonly cb: () => void;
  prev: WheelEntry | null;
  next: WheelEntry | null;
  canceled: boolean;
}

export class HashedTimingWheel {
  private readonly buckets: Array<WheelEntry | null>;
  private readonly mask: number;
  private readonly byId = new Map<number, WheelEntry>();
  private currentTick = 0;
  private nextId = 1;

  constructor(
    public readonly tickDurationMs = 100,
    wheelPowerOfTwoBits = 9, // 2^9 = 512 slots (51.2s per revolution at 100ms)
  ) {
    const size = 1 << wheelPowerOfTwoBits;
    this.mask = size - 1;
    this.buckets = new Array(size).fill(null);
  }

  schedule(delayMs: number, cb: () => void): number {
    const ticks = Math.max(1, Math.ceil(delayMs / this.tickDurationMs));
    const target = this.currentTick + ticks;
    const slot = target & this.mask;
    const rounds = Math.floor((ticks - 1) / (this.mask + 1));
    const id = this.nextId++;

    const head = this.buckets[slot];
    const node: WheelEntry = {
      id,
      rounds,
      slot,
      cb,
      prev: null,
      next: head,
      canceled: false,
    };
    if (head) head.prev = node;
    this.buckets[slot] = node;
    this.byId.set(id, node);
    return id;
  }

  cancel(timerId: number): boolean {
    const node = this.byId.get(timerId);
    if (!node) return false;
    node.canceled = true;
    this.unlink(node);
    this.byId.delete(timerId);
    return true;
  }

  /** Advance wheel by 1 tick; invoke from a single setInterval(tickDurationMs) */
  tick(): number {
    this.currentTick += 1;
    const slot = this.currentTick & this.mask;
    let cur = this.buckets[slot];
    const due: WheelEntry[] = [];

    while (cur !== null) {
      const next = cur.next;
      if (cur.rounds <= 0) {
        this.unlink(cur);
        this.byId.delete(cur.id);
        due.push(cur);
      } else {
        cur.rounds -= 1;
      }
      cur = next;
    }

    for (let i = 0; i < due.length; i++) {
      if (!due[i].canceled) due[i].cb();
    }
    return due.length;
  }

  private unlink(node: WheelEntry): void {
    if (node.prev) node.prev.next = node.next;
    else this.buckets[node.slot] = node.next;
    if (node.next) node.next.prev = node.prev;
    node.prev = node.next = null;
  }
}
```

