```ts
function normalizeWeakEtag(tag: string): string {
  const t = tag.trim();
  return t.startsWith("W/") ? t.slice(2) : t;
}

export function ifNoneMatchHit(header: string | null, currentEtag: string): boolean {
  if (!header) return false;
  if (header.trim() === "*") return true;
  const target = normalizeWeakEtag(currentEtag);
  const candidates = header.match(/(?:W\/)?"[^"]*"/g) ?? [];
  return candidates.some((c) => normalizeWeakEtag(c) === target);
}

export function parseByteRange(
  rangeHeader: string,
  totalLength: number,
): { start: number; end: number } | "unsatisfiable" | "ignore" {
  if (!rangeHeader.startsWith("bytes=") || rangeHeader.includes(",")) {
    return "ignore";
  }
  const spec = rangeHeader.slice(6).trim();
  const dash = spec.indexOf("-");
  if (dash === -1 || totalLength === 0) return "unsatisfiable";

  const startStr = spec.slice(0, dash);
  const endStr = spec.slice(dash + 1);

  if (startStr === "") {
    const suffixLen = Number.parseInt(endStr, 10);
    if (!Number.isInteger(suffixLen) || suffixLen <= 0) return "unsatisfiable";
    const start = Math.max(0, totalLength - suffixLen);
    return { start, end: totalLength - 1 };
  }

  const start = Number.parseInt(startStr, 10);
  const end = endStr === "" ? totalLength - 1 : Number.parseInt(endStr, 10);
  if (
    !Number.isInteger(start) ||
    !Number.isInteger(end) ||
    start < 0 ||
    start >= totalLength ||
    end < start
  ) {
    return "unsatisfiable";
  }
  return { start, end: Math.min(end, totalLength - 1) };
}

export function buildBlobResponse(
  req: Request,
  body: Uint8Array,
  contentType: string,
  etag: string,
): Response {
  const baseHeaders = new Headers({
    "Content-Type": contentType,
    ETag: etag,
    "Accept-Ranges": "bytes",
  });

  if (ifNoneMatchHit(req.headers.get("if-none-match"), etag)) {
    return new Response(null, { status: 304, headers: baseHeaders });
  }

  const rangeHdr = req.headers.get("range");
  if (rangeHdr) {
    const parsed = parseByteRange(rangeHdr, body.byteLength);
    if (parsed === "unsatisfiable") {
      baseHeaders.set("Content-Range", `bytes */${body.byteLength}`);
      return new Response(null, { status: 416, headers: baseHeaders });
    }
    if (parsed !== "ignore") {
      const slice = body.subarray(parsed.start, parsed.end + 1);
      baseHeaders.set(
        "Content-Range",
        `bytes ${parsed.start}-${parsed.end}/${body.byteLength}`,
      );
      baseHeaders.set("Content-Length", String(slice.byteLength));
      return new Response(slice, { status: 206, headers: baseHeaders });
    }
  }

  baseHeaders.set("Content-Length", String(body.byteLength));
  return new Response(body, { status: 200, headers: baseHeaders });
}
```

