import { parseArgs } from "node:util";
import { readFileSync } from "node:fs";

const { values, positionals } = parseArgs({
  allowPositionals: true,
  options: {
    concurrency: { type: "string", short: "c", default: "10" },
    timeoutMs: { type: "string", short: "t", default: "4000" },
  },
});

const rawInput =
  positionals.length > 0
    ? readFileSync(positionals[0], "utf8")
    : readFileSync(0, "utf8");

const urls = rawInput
  .split(/\r?\n/)
  .map((s) => s.trim())
  .filter((s) => s && !s.startsWith("#"));

const limit = Math.max(1, Number.parseInt(values.concurrency, 10) || 10);
const timeoutMs = Math.max(100, Number.parseInt(values.timeoutMs, 10) || 4000);

async function probeOne(url) {
  const t0 = performance.now();
  try {
    const res = await fetch(url, {
      method: "GET",
      redirect: "follow",
      signal: AbortSignal.timeout(timeoutMs),
    });
    await res.body?.cancel();
    const ms = (performance.now() - t0).toFixed(1);
    const ok = res.status >= 200 && res.status < 400;
    return { url, ok, status: String(res.status), ms, detail: res.statusText || "OK" };
  } catch (err) {
    const ms = (performance.now() - t0).toFixed(1);
    return {
      url,
      ok: false,
      status: "ERR",
      ms,
      detail: err instanceof Error ? err.name + ": " + err.message : String(err),
    };
  }
}

const results = new Array(urls.length);
let cursor = 0;
await Promise.all(
  Array.from({ length: Math.min(limit, urls.length) }, async () => {
    while (cursor < urls.length) {
      const i = cursor++;
      results[i] = await probeOne(urls[i]);
    }
  }),
);

let failures = 0;
process.stdout.write("STATE\tHTTP\tLATENCY_MS\tURL\tDETAIL\n");
for (const r of results) {
  if (!r.ok) failures += 1;
  process.stdout.write(
    `${r.ok ? "PASS" : "FAIL"}\t${r.status}\t${r.ms}\t${r.url}\t${r.detail}\n`,
  );
}
process.exit(failures > 0 ? 1 : 0);
