```ts
export type Decoder<T> = (input: unknown, path?: string) => T;

export const dString: Decoder<string> = (v, path = "$") => {
  if (typeof v !== "string") throw new TypeError(`${path}: expected string, got ${typeof v}`);
  return v;
};

export const dNumber: Decoder<number> = (v, path = "$") => {
  if (typeof v !== "number" || !Number.isFinite(v)) {
    throw new TypeError(`${path}: expected finite number`);
  }
  return v;
};

export function dArray<T>(item: Decoder<T>): Decoder<T[]> {
  return (v, path = "$") => {
    if (!Array.isArray(v)) throw new TypeError(`${path}: expected array`);
    return v.map((el, i) => item(el, `${path}[${i}]`));
  };
}

export function dOptional<T>(inner: Decoder<T>): Decoder<T | undefined> {
  return (v, path = "$") => (v === undefined || v === null ? undefined : inner(v, path));
}

export function dObject<Shape extends Record<string, Decoder<unknown>>>(
  shape: Shape,
): Decoder<{ [K in keyof Shape]: ReturnType<Shape[K]> }> {
  const entries = Object.entries(shape);
  return (v, path = "$") => {
    if (typeof v !== "object" || v === null || Array.isArray(v)) {
      throw new TypeError(`${path}: expected object`);
    }
    const src = v as Record<string, unknown>;
    const out: Record<string, unknown> = {};
    for (const [key, decodeField] of entries) {
      out[key] = decodeField(src[key], `${path}.${key}`);
    }
    return out as { [K in keyof Shape]: ReturnType<Shape[K]> };
  };
}

