Plain uncompressed bitsets waste `8 KiB` even f0r 2 sparse IDs, whereas sorted `Uint32Array` posting lists blow past bitset size once density crosses `1/16`! **Roaring Bitmaps** (Lemire et al., 2016 — used in Lucene, ClickHouse, Druid, Postgres) partition 32-bit integers by their **upper 16 bits** (`key = x >>> 16`) into 16-bit chunks (`low = x & 0xffff`), dynamically switching each chunk at **`4,096` elements** (`4096 × 2 bytes = 8,192 bytes == 65,536 bits`!):
- `size <= 4096` -> sorted `Uint16Array` (`O(log n)` binary search, compact m3m0ry).
- `size > 4096` -> fixed `2048`-word `Uint32Array` bitset (`8 KiB`, `O(1)` bit test + popcount intersections!):

```ts
const CUTOFF = 4096;

function popcount32(v: number): number {
  let x = v - ((v >>> 1) & 0x55555555);
  x = (x & 0x33333333) + ((x >>> 2) & 0x33333333);
  return (((x + (x >>> 4)) & 0x0f0f0f0f) * 0x01010101) >>> 24;
}

export class RoaringChunk16 {
  private mode: "array" | "bitset" = "array";
  private arr = new Uint16Array(16);
  private bits: Uint32Array | null = null;
  private count = 0;

  get size(): number {
    return this.count;
  }

  has(val16: number): boolean {
    const x = val16 & 0xffff;
    if (this.mode === "bitset") {
      return (this.bits![x >>> 5] & (1 << (x & 31))) !== 0;
    }
    return this.binarySearch(x) >= 0;
  }

  add(val16: number): boolean {
    const x = val16 & 0xffff;
    if (this.mode === "bitset") {
      const word = x >>> 5;
      const mask = 1 << (x & 31);
      if ((this.bits![word] & mask) !== 0) return false;
      this.bits![word] |= mask;
      this.count += 1;
      return true;
    }

    const idx = this.binarySearch(x);
    if (idx >= 0) return false;
    const insertAt = ~idx;

    if (this.count === CUTOFF) {
      const bm = new Uint32Array(2048);
      for (let i = 0; i < this.count; i++) {
        const v = this.arr[i];
        bm[v >>> 5] |= 1 << (v & 31);
      }
      bm[x >>> 5] |= 1 << (x & 31);
      this.bits = bm;
      this.arr = new Uint16Array(0);
      this.mode = "bitset";
      this.count += 1;
      return true;
    }

    if (this.count === this.arr.length) {
      const grown = new Uint16Array(Math.min(CUTOFF, this.arr.length * 2));
      grown.set(this.arr);
      this.arr = grown;
    }
    this.arr.copyWithin(insertAt + 1, insertAt, this.count);
    this.arr[insertAt] = x;
    this.count += 1;
    return true;
  }

  intersectCount(other: RoaringChunk16): number {
    if (this.mode === "bitset" && other.mode === "bitset") {
      let sum = 0;
      const a = this.bits!;
      const b = other.bits!;
      for (let i = 0; i < 2048; i++) sum += popcount32(a[i] & b[i]);
      return sum;
    }
    if (this.mode === "array" && other.mode === "array") {
      let i = 0, j = 0, hits = 0;
      while (i < this.count && j < other.count) {
        const va = this.arr[i], vb = other.arr[j];
        if (va === vb) { hits++; i++; j++; }
