```ts
// Header: first 64-byte cache line = head (i32[0]), second 64-byte cache line = tail (i32[16])
// Separating head & tail by 64 bytes prevents CPU false sharing between producer & consumer cores!
const HEADER_BYTES = 128;
const IDX_HEAD = 0;
const IDX_TAIL = 16;

export class SpscSharedRing {
  private readonly ctrl: Int32Array;
  private readonly data: Uint8Array;
  private readonly cap: number;
  private readonly mask: number;

  constructor(sab: SharedArrayBuffer) {
    const dataLen = sab.byteLength - HEADER_BYTES;
    if (dataLen < 16 || (dataLen & (dataLen - 1)) !== 0) {
      throw new RangeError("Data region (sab.byteLength - 128) must be a power of 2 >= 16");
    }
    this.ctrl = new Int32Array(sab, 0, HEADER_BYTES / 4);
    this.data = new Uint8Array(sab, HEADER_BYTES, dataLen);
    this.cap = dataLen;
    this.mask = dataLen - 1;
  }

  static allocate(capacityPow2: number): SpscSharedRing {
    return new SpscSharedRing(new SharedArrayBuffer(HEADER_BYTES + capacityPow2));
  }

  write(src: Uint8Array): number {
    const head = Atomics.load(this.ctrl, IDX_HEAD);
    const tail = Atomics.load(this.ctrl, IDX_TAIL);
    const free = this.cap - (head - tail);
    const toWrite = Math.min(src.byteLength, free);
    if (toWrite === 0) return 0;

    const startOff = head & this.mask;
    const firstChunk = Math.min(toWrite, this.cap - startOff);
    this.data.set(src.subarray(0, firstChunk), startOff);
    if (firstChunk < toWrite) {
      this.data.set(src.subarray(firstChunk, toWrite), 0);
    }

    // Release store publishes payload bytes BEFORE advancing head!
    Atomics.store(this.ctrl, IDX_HEAD, (head + toWrite) | 0);
    return toWrite;
  }

  read(dst: Uint8Array): number {
    const tail = Atomics.load(this.ctrl, IDX_TAIL);
    const head = Atomics.load(this.ctrl, IDX_HEAD);
    const avail = head - tail;
    const toRead = Math.min(dst.byteLength, avail);
    if (toRead === 0) return 0;

    const startOff = tail & this.mask;
    const firstChunk = Math.min(toRead, this.cap - startOff);
    dst.set(this.data.subarray(startOff, startOff + firstChunk), 0);
    if (firstChunk < toRead) {
      dst.set(this.data.subarray(0, toRead - firstChunk), firstChunk);
    }

    Atomics.store(this.ctrl, IDX_TAIL, (tail + toRead) | 0);
    return toRead;
  }
}
```

