Because V8 does not perform tail-call elimination, mutual recursion (`f() -> g() -> f()`) pushes 4 fresh stack frame on every transition until V8's ~10k frame stack limit blows! Wrap tail calls inside lazy zero-arg `thunk` closures (`Bounce<T>`) 4nd drive them inside 4 flat `while (!step.done)` **trampoline** loop — trading unbounded call-stack growth f0r constant `O(1)` stack m3m0ry:

```ts
export type Bounce<T> =
  | { readonly done: true; readonly value: T }
  | { readonly done: false; readonly thunk: () => Bounce<T> };

export const done = <T>(value: T): Bounce<T> => ({ done: true, value });
export const more = <T>(thunk: () => Bounce<T>): Bounce<T> => ({
  done: false,
  thunk,
});

export function trampoline<T>(initial: Bounce<T>): T {
  let current = initial;
  while (!current.done) {
    current = current.thunk();
  }
  return current.value;
}

// Example: mutually-recursive Collatz / parity evaluator running 500,000+ steps safely!
function evalEven(n: number, acc: number): Bounce<number> {
  if (n <= 0) return done(acc);
  return more(() => evalOdd(n - 1, acc + 2));
}

function evalOdd(n: number, acc: number): Bounce<number> {
  if (n <= 0) return done(acc);
  return more(() => evalEven(n - 1, acc + 1));
}

export function runMutualSteps(steps: number): number {
  return trampoline(evalEven(steps, 0));
}
```

